# -----------------------------------------------------------------------------
# 6.2. Normalização de sinais de carga
# -----------------------------------------------------------------------------

def normalize_charge_sign(
    value: Any,
    *,
    default: str = CHARGE_UNKNOWN,
) -> str:
    """
    Normalize a charge-sign description.
    """

    if value is None:
        return default

    if isinstance(value, bool):
        return default

    if isinstance(value, (int, float)):
        numeric_value = _normalize_optional_numeric(value)

        if numeric_value is None:
            return default

        if numeric_value > 0.0:
            return CHARGE_POSITIVE

        if numeric_value < 0.0:
            return CHARGE_NEGATIVE

        return CHARGE_NEUTRAL

    normalized = str(value).strip().lower()

    aliases = {
        "+": CHARGE_POSITIVE,
        "positive": CHARGE_POSITIVE,
        "cation": CHARGE_POSITIVE,
        "cationic": CHARGE_POSITIVE,
        "pos": CHARGE_POSITIVE,
        "-": CHARGE_NEGATIVE,
        "negative": CHARGE_NEGATIVE,
        "anion": CHARGE_NEGATIVE,
        "anionic": CHARGE_NEGATIVE,
        "neg": CHARGE_NEGATIVE,
        "0": CHARGE_NEUTRAL,
        "neutral": CHARGE_NEUTRAL,
        "unknown": CHARGE_UNKNOWN,
        "none": CHARGE_UNKNOWN,
    }

    return aliases.get(normalized, default)


def charge_sign_from_value(
    charge: Optional[Number],
    *,
    tolerance: float = 1.0e-8,
) -> str:
    """
    Return the charge sign associated with a numeric charge.
    """

    numeric_charge = _normalize_optional_numeric(charge)

    if numeric_charge is None:
        return CHARGE_UNKNOWN

    tolerance_value = _coerce_non_negative_float(
        tolerance,
        field_name="tolerance",
    )

    if numeric_charge > tolerance_value:
        return CHARGE_POSITIVE

    if numeric_charge < -tolerance_value:
        return CHARGE_NEGATIVE

    return CHARGE_NEUTRAL


# -----------------------------------------------------------------------------
# 6.3. Cálculo de cargas agregadas
# -----------------------------------------------------------------------------

def calculate_group_formal_charge(
    atoms: Iterable[Any],
) -> Optional[float]:
    """
    Sum explicit formal charges for a group.

    ``None`` is returned when no atom exposes formal-charge information.
    """

    charges = [
        get_atom_formal_charge(atom)
        for atom in atoms
    ]

    known_charges = [
        charge
        for charge in charges
        if charge is not None
    ]

    if not known_charges:
        return None

    return float(sum(known_charges))


def calculate_group_partial_charge(
    atoms: Iterable[Any],
) -> Optional[float]:
    """
    Sum explicit partial charges for a group.
    """

    charges = [
        get_atom_partial_charge(atom)
        for atom in atoms
    ]

    known_charges = [
        charge
        for charge in charges
        if charge is not None
    ]

    if not known_charges:
        return None

    return float(sum(known_charges))


def calculate_group_effective_charge(
    atoms: Iterable[Any],
    *,
    inferred_charge: Optional[float] = None,
    prefer_formal: bool = True,
) -> Optional[float]:
    """
    Return the best available charge estimate for a group.
    """

    atom_tuple = tuple(atoms)

    formal_charge = calculate_group_formal_charge(atom_tuple)
    partial_charge = calculate_group_partial_charge(atom_tuple)

    if prefer_formal and formal_charge is not None:
        if abs(formal_charge) > 1.0e-8:
            return formal_charge

    if partial_charge is not None:
        if abs(partial_charge) > 1.0e-8:
            return partial_charge

    if formal_charge is not None:
        return formal_charge

    return _normalize_optional_numeric(inferred_charge)


def group_has_positive_charge(
    atoms: Iterable[Any],
    *,
    inferred_charge: Optional[float] = None,
    minimum_magnitude: float = DEFAULT_MINIMUM_GROUP_CHARGE_MAGNITUDE,
) -> bool:
    """
    Return whether a group has a sufficiently positive effective charge.
    """

    charge = calculate_group_effective_charge(
        atoms,
        inferred_charge=inferred_charge,
    )

    return (
        charge is not None
        and charge >= minimum_magnitude
    )


def group_has_negative_charge(
    atoms: Iterable[Any],
    *,
    inferred_charge: Optional[float] = None,
    minimum_magnitude: float = DEFAULT_MINIMUM_GROUP_CHARGE_MAGNITUDE,
) -> bool:
    """
    Return whether a group has a sufficiently negative effective charge.
    """

    charge = calculate_group_effective_charge(
        atoms,
        inferred_charge=inferred_charge,
    )

    return (
        charge is not None
        and charge <= -minimum_magnitude
    )


# -----------------------------------------------------------------------------
# 6.4. Centro geométrico e centro ponderado por carga
# -----------------------------------------------------------------------------

def calculate_charge_weighted_center(
    atoms: Iterable[Any],
    *,
    charge_sign: Optional[str] = None,
    use_scene_coordinates: bool = True,
    weight_floor: float = DEFAULT_CHARGE_CENTER_WEIGHT_FLOOR,
    fallback_to_centroid: bool = True,
) -> Optional[Coordinate3D]:
    """
    Calculate a center weighted by the magnitude of atomic charge.

    For positive groups, only positive atomic contributions are preferred.
    For negative groups, only negative contributions are preferred.
    """

    atom_tuple = tuple(atoms)

    if not atom_tuple:
        return None

    normalized_sign = normalize_charge_sign(
        charge_sign,
        default=CHARGE_UNKNOWN,
    )

    weighted_coordinates: List[
        Tuple[Coordinate3D, float]
    ] = []

    for atom in atom_tuple:
        coordinate = get_atom_coordinate(
            atom,
            use_scene_coordinates=use_scene_coordinates,
        )

        if coordinate is None:
            continue

        formal_charge = get_atom_formal_charge(atom)
        partial_charge = get_atom_partial_charge(atom)

        charge = (
            formal_charge
            if formal_charge is not None
            else partial_charge
        )

        if charge is None:
            continue

        if normalized_sign == CHARGE_POSITIVE:
            weight = max(0.0, charge)

        elif normalized_sign == CHARGE_NEGATIVE:
            weight = max(0.0, -charge)

        else:
            weight = abs(charge)

        if weight < weight_floor:
            continue

        weighted_coordinates.append(
            (
                coordinate,
                weight,
            )
        )

    total_weight = sum(
        weight
        for _, weight in weighted_coordinates
    )

    if total_weight > 0.0:
        return (
            sum(
                coordinate[0] * weight
                for coordinate, weight in weighted_coordinates
            ) / total_weight,
            sum(
                coordinate[1] * weight
                for coordinate, weight in weighted_coordinates
            ) / total_weight,
            sum(
                coordinate[2] * weight
                for coordinate, weight in weighted_coordinates
            ) / total_weight,
        )

    if not fallback_to_centroid:
        return None

    coordinates = get_atom_coordinates(
        atom_tuple,
        use_scene_coordinates=use_scene_coordinates,
        skip_invalid=True,
    )

    if not coordinates:
        return None

    return calculate_centroid(coordinates)


def calculate_charged_group_center(
    group_atoms: Iterable[Any],
    *,
    charge_atoms: Optional[Iterable[Any]] = None,
    charge_sign: Optional[str] = None,
    use_scene_coordinates: bool = True,
) -> Optional[Coordinate3D]:
    """
    Calculate the chemically relevant center of a charged group.
    """

    atom_tuple = tuple(group_atoms)
    charge_atom_tuple = tuple(charge_atoms or ())

    preferred_atoms = (
        charge_atom_tuple
        if charge_atom_tuple
        else atom_tuple
    )

    center = calculate_charge_weighted_center(
        preferred_atoms,
        charge_sign=charge_sign,
        use_scene_coordinates=use_scene_coordinates,
        fallback_to_centroid=True,
    )

    if center is not None:
        return center

    coordinates = get_atom_coordinates(
        atom_tuple,
        use_scene_coordinates=use_scene_coordinates,
        skip_invalid=True,
    )

    if not coordinates:
        return None

    return calculate_centroid(coordinates)


# -----------------------------------------------------------------------------
# 6.5. Vetor direcional de grupos carregados
# -----------------------------------------------------------------------------

def calculate_group_direction_vector(
    center: Sequence[Number],
    support_atoms: Iterable[Any],
    *,
    use_scene_coordinates: bool = True,
    point_away_from_support: bool = True,
) -> Optional[Vector3D]:
    """
    Calculate a direction vector for a charged functional group.

    The vector usually points from the supporting molecular scaffold toward
    the charged center.
    """

    normalized_center = _coerce_coordinate3d(
        center,
        field_name="center",
    )

    assert normalized_center is not None

    support_coordinates = get_atom_coordinates(
        support_atoms,
        use_scene_coordinates=use_scene_coordinates,
        skip_invalid=True,
    )

    if not support_coordinates:
        return None

    support_center = calculate_centroid(
        support_coordinates
    )

    if point_away_from_support:
        vector = subtract_vectors(
            normalized_center,
            support_center,
        )

    else:
        vector = subtract_vectors(
            support_center,
            normalized_center,
        )

    return normalize_vector(vector)


def calculate_group_plane_normal(
    atoms: Iterable[Any],
    *,
    use_scene_coordinates: bool = True,
) -> Optional[Vector3D]:
    """
    Fit a plane normal to a planar charged group.
    """

    atom_tuple = tuple(atoms)

    if len(atom_tuple) < 3:
        return None

    plane = fit_plane_to_atoms(
        atom_tuple,
        use_scene_coordinates=use_scene_coordinates,
        skip_invalid=True,
        strict=False,
    )

    if plane is None:
        return None

    return orient_normal_deterministically(
        plane.normal
    )


# -----------------------------------------------------------------------------
# 6.6. Construção de grupos carregados conhecidos
# -----------------------------------------------------------------------------

def _create_known_residue_charged_group(
    residue: Any,
    definition: Mapping[str, Any],
    *,
    charge_sign: str,
    participant_type: Optional[str] = None,
    group_index: Optional[int] = None,
    use_scene_coordinates: bool = True,
    ligand_residue_names: Optional[Collection[str]] = None,
    receptor_residue_names: Optional[Collection[str]] = None,
) -> Optional[PiChargedGroup]:
    """
    Create a charged group from a residue-specific definition.
    """

    atom_map = map_atoms_by_name(residue)

    required_names = tuple(
        str(name).strip().upper()
        for name in definition.get(
            "atom_names",
            (),
        )
    )

    charge_names = tuple(
        str(name).strip().upper()
        for name in definition.get(
            "charge_atom_names",
            required_names,
        )
    )

    support_names = tuple(
        str(name).strip().upper()
        for name in definition.get(
            "support_atom_names",
            (),
        )
    )

    atoms = tuple(
        atom_map[name]
        for name in required_names
        if name in atom_map
    )

    if len(atoms) != len(required_names):
        return None

    if not all(
        atom_has_valid_coordinate(
            atom,
            use_scene_coordinates=use_scene_coordinates,
        )
        for atom in atoms
    ):
        return None

    charge_atoms = tuple(
        atom_map[name]
        for name in charge_names
        if name in atom_map
    )

    support_atoms = tuple(
        atom_map[name]
        for name in support_names
        if name in atom_map
    )

    inferred_charge = _normalize_optional_numeric(
        definition.get("formal_charge")
    )

    center = calculate_charged_group_center(
        atoms,
        charge_atoms=charge_atoms,
        charge_sign=charge_sign,
        use_scene_coordinates=use_scene_coordinates,
    )

    if center is None:
        return None

    direction = calculate_group_direction_vector(
        center,
        support_atoms,
        use_scene_coordinates=use_scene_coordinates,
    )

    plane_normal = calculate_group_plane_normal(
        atoms,
        use_scene_coordinates=use_scene_coordinates,
    )

    residue_name = get_residue_name(residue)
    residue_number = get_residue_number(residue)
    chain_id = get_residue_chain_id(residue)

    model = _safe_get_value(
        residue,
        (
            "structure",
            "model",
            "molecule",
        ),
        default=None,
    )

    normalized_participant_type = (
        participant_type
        or infer_participant_type(
            residue,
            ligand_residue_names=ligand_residue_names,
            receptor_residue_names=receptor_residue_names,
        )
    )

    formal_charge = calculate_group_formal_charge(atoms)
    partial_charge = calculate_group_partial_charge(atoms)

    effective_charge = calculate_group_effective_charge(
        atoms,
        inferred_charge=inferred_charge,
    )

    return PiChargedGroup(
        atoms=atoms,
        atom_references=create_pi_atom_references(
            atoms,
            skip_invalid=False,
        ),
        charge_atoms=charge_atoms,
        support_atoms=support_atoms,
        group_index=group_index,
        group_type=str(
            definition.get(
                "group_type",
                (
                    POSITIVE_GROUP_GENERIC
                    if charge_sign == CHARGE_POSITIVE
                    else NEGATIVE_GROUP_GENERIC
                ),
            )
        ),
        charge_sign=charge_sign,
        center=center,
        direction=direction,
        plane_normal=plane_normal,
        formal_charge=formal_charge,
        partial_charge=partial_charge,
        effective_charge=effective_charge,
        residue_name=residue_name,
        residue_number=residue_number,
        chain_id=chain_id,
        model_id=get_model_identifier(model),
        participant_type=normalized_participant_type,
        valid=True,
        metadata={
            "detection_method": "known_residue_definition",
            "definition": dict(definition),
        },
    )


def detect_known_residue_charged_groups(
    residue: Any,
    *,
    include_positive: bool = True,
    include_negative: bool = True,
    participant_type: Optional[str] = None,
    use_scene_coordinates: bool = True,
    ligand_residue_names: Optional[Collection[str]] = None,
    receptor_residue_names: Optional[Collection[str]] = None,
) -> List[PiChargedGroup]:
    """
    Detect known charged groups in protein residues.
    """

    residue_name = get_residue_name(residue)
    groups: List[PiChargedGroup] = []

    if include_positive:
        positive_definitions = (
            STANDARD_POSITIVE_RESIDUE_GROUPS.get(
                residue_name,
                (),
            )
        )

        for definition in positive_definitions:
            group = _create_known_residue_charged_group(
                residue,
                definition,
                charge_sign=CHARGE_POSITIVE,
                participant_type=participant_type,
                group_index=len(groups) + 1,
                use_scene_coordinates=use_scene_coordinates,
                ligand_residue_names=ligand_residue_names,
                receptor_residue_names=receptor_residue_names,
            )

            if group is not None:
                groups.append(group)

    if include_negative:
        negative_definitions = (
            STANDARD_NEGATIVE_RESIDUE_GROUPS.get(
                residue_name,
                (),
            )
        )

        for definition in negative_definitions:
            group = _create_known_residue_charged_group(
                residue,
                definition,
                charge_sign=CHARGE_NEGATIVE,
                participant_type=participant_type,
                group_index=len(groups) + 1,
                use_scene_coordinates=use_scene_coordinates,
                ligand_residue_names=ligand_residue_names,
                receptor_residue_names=receptor_residue_names,
            )

            if group is not None:
                groups.append(group)

    return groups


# -----------------------------------------------------------------------------
# 6.7. Detecção de grupos fosfato
# -----------------------------------------------------------------------------

def detect_phosphate_groups(
    atoms_or_residue: Any,
    *,
    participant_type: Optional[str] = None,
    require_negative_charge: bool = False,
    use_scene_coordinates: bool = True,
) -> List[PiChargedGroup]:
    """
    Detect phosphate groups centered on phosphorus atoms.
    """

    atoms = normalize_atom_collection(
        atoms_or_residue,
        include_hydrogens=False,
        valid_coordinates_only=True,
    )

    atom_identity_set = {
        id(atom)
        for atom in atoms
    }

    groups: List[PiChargedGroup] = []

    for phosphorus in atoms:
        if get_atom_element(phosphorus) != "P":
            continue

        bonded_oxygens = tuple(
            neighbor
            for neighbor in get_bonded_atoms(
                phosphorus,
                include_hydrogens=False,
            )
            if (
                id(neighbor) in atom_identity_set
                and get_atom_element(neighbor) == "O"
            )
        )

        if len(bonded_oxygens) < 3:
            continue

        group_atoms = (
            phosphorus,
            *bonded_oxygens,
        )

        inferred_charge = calculate_group_effective_charge(
            group_atoms,
            inferred_charge=-1.0,
        )

        if (
            require_negative_charge
            and (
                inferred_charge is None
                or inferred_charge >= 0.0
            )
        ):
            continue

        negative_oxygens = tuple(
            oxygen
            for oxygen in bonded_oxygens
            if atom_has_negative_charge(
                oxygen,
                infer_from_type=True,
            )
        )

        charge_atoms = (
            negative_oxygens
            if negative_oxygens
            else bonded_oxygens
        )

        center = calculate_charged_group_center(
            group_atoms,
            charge_atoms=charge_atoms,
            charge_sign=CHARGE_NEGATIVE,
            use_scene_coordinates=use_scene_coordinates,
        )

        if center is None:
            continue

        residue = get_atom_residue(phosphorus)
        model = get_atom_model(phosphorus)

        group = PiChargedGroup(
            atoms=tuple(group_atoms),
            atom_references=create_pi_atom_references(
                group_atoms
            ),
            charge_atoms=charge_atoms,
            support_atoms=(phosphorus,),
            group_index=len(groups) + 1,
            group_type=NEGATIVE_GROUP_PHOSPHATE,
            charge_sign=CHARGE_NEGATIVE,
            center=center,
            direction=None,
            plane_normal=calculate_group_plane_normal(
                bonded_oxygens,
                use_scene_coordinates=use_scene_coordinates,
            ),
            formal_charge=calculate_group_formal_charge(
                group_atoms
            ),
            partial_charge=calculate_group_partial_charge(
                group_atoms
            ),
            effective_charge=inferred_charge,
            residue_name=get_residue_name(
                residue or phosphorus
            ),
            residue_number=get_residue_number(
                residue or phosphorus
            ),
            chain_id=get_residue_chain_id(
                residue or phosphorus
            ),
            model_id=get_model_identifier(model),
            participant_type=(
                participant_type
                or infer_participant_type(
                    residue or phosphorus
                )
            ),
            valid=True,
            metadata={
                "detection_method": "phosphorus_connectivity",
                "oxygen_count": len(bonded_oxygens),
            },
        )

        groups.append(group)

    return groups


# -----------------------------------------------------------------------------
# 6.8. Detecção de carboxilatos genéricos
# -----------------------------------------------------------------------------

def detect_carboxylate_groups(
    atoms_or_residue: Any,
    *,
    participant_type: Optional[str] = None,
    require_negative_charge: bool = False,
    use_scene_coordinates: bool = True,
) -> List[PiChargedGroup]:
    """
    Detect generic carboxylate groups from carbon–oxygen connectivity.
    """

    atoms = normalize_atom_collection(
        atoms_or_residue,
        include_hydrogens=False,
        valid_coordinates_only=True,
    )

    atom_identity_set = {
        id(atom)
        for atom in atoms
    }

    groups: List[PiChargedGroup] = []

    for carbon in atoms:
        if get_atom_element(carbon) != "C":
            continue

        bonded_oxygens = tuple(
            neighbor
            for neighbor in get_bonded_atoms(
                carbon,
                include_hydrogens=False,
            )
            if (
                id(neighbor) in atom_identity_set
                and get_atom_element(neighbor) == "O"
            )
        )

        if len(bonded_oxygens) != 2:
            continue

        bond_orders = tuple(
            get_bond_order(carbon, oxygen)
            for oxygen in bonded_oxygens
        )

        aromatic_like = any(
            order is not None
            and abs(order - 1.5) <= 0.20
            for order in bond_orders
        )

        double_bond_count = sum(
            1
            for order in bond_orders
            if order is not None
            and order >= 1.75
        )

        negative_oxygen_count = sum(
            1
            for oxygen in bonded_oxygens
            if atom_has_negative_charge(oxygen)
        )

        carboxylate_like = (
            aromatic_like
            or double_bond_count == 1
            or negative_oxygen_count >= 1
        )

        if not carboxylate_like:
            continue

        group_atoms = (
            carbon,
            *bonded_oxygens,
        )

        inferred_charge = calculate_group_effective_charge(
            group_atoms,
            inferred_charge=-1.0,
        )

        if (
            require_negative_charge
            and (
                inferred_charge is None
                or inferred_charge >= 0.0
            )
        ):
            continue

        negative_oxygens = tuple(
            oxygen
            for oxygen in bonded_oxygens
            if atom_has_negative_charge(oxygen)
        )

        charge_atoms = (
            negative_oxygens
            if negative_oxygens
            else bonded_oxygens
        )

        center = calculate_charged_group_center(
            group_atoms,
            charge_atoms=charge_atoms,
            charge_sign=CHARGE_NEGATIVE,
            use_scene_coordinates=use_scene_coordinates,
        )

        if center is None:
            continue

        support_atoms = tuple(
            neighbor
            for neighbor in get_bonded_atoms(
                carbon,
                include_hydrogens=False,
            )
            if (
                id(neighbor) in atom_identity_set
                and neighbor not in bonded_oxygens
            )
        )

        residue = get_atom_residue(carbon)
        model = get_atom_model(carbon)

        groups.append(
            PiChargedGroup(
                atoms=group_atoms,
                atom_references=create_pi_atom_references(
                    group_atoms
                ),
                charge_atoms=charge_atoms,
                support_atoms=support_atoms,
                group_index=len(groups) + 1,
                group_type=NEGATIVE_GROUP_CARBOXYLATE,
                charge_sign=CHARGE_NEGATIVE,
                center=center,
                direction=calculate_group_direction_vector(
                    center,
                    support_atoms,
                    use_scene_coordinates=use_scene_coordinates,
                ),
                plane_normal=calculate_group_plane_normal(
                    group_atoms,
                    use_scene_coordinates=use_scene_coordinates,
                ),
                formal_charge=calculate_group_formal_charge(
                    group_atoms
                ),
                partial_charge=calculate_group_partial_charge(
                    group_atoms
                ),
                effective_charge=inferred_charge,
                residue_name=get_residue_name(
                    residue or carbon
                ),
                residue_number=get_residue_number(
                    residue or carbon
                ),
                chain_id=get_residue_chain_id(
                    residue or carbon
                ),
                model_id=get_model_identifier(model),
                participant_type=(
                    participant_type
                    or infer_participant_type(
                        residue or carbon
                    )
                ),
                valid=True,
                metadata={
                    "detection_method": (
                        "carboxylate_connectivity"
                    ),
                    "bond_orders": list(bond_orders),
                },
            )
        )

    return groups


# -----------------------------------------------------------------------------
# 6.9. Detecção de amônio e nitrogênios catiônicos
# -----------------------------------------------------------------------------

def _infer_nitrogen_positive_group_type(
    nitrogen: Any,
    bonded_atoms: Sequence[Any],
) -> str:
    """
    Infer a positive nitrogen group class.
    """

    carbon_neighbors = [
        atom
        for atom in bonded_atoms
        if get_atom_element(atom) == "C"
    ]

    nitrogen_neighbors = [
        atom
        for atom in bonded_atoms
        if get_atom_element(atom) == "N"
    ]

    if len(carbon_neighbors) >= 4:
        return POSITIVE_GROUP_AMMONIUM

    if nitrogen_neighbors:
        return POSITIVE_GROUP_GUANIDINIUM

    return POSITIVE_GROUP_GENERIC


def detect_positive_nitrogen_groups(
    atoms_or_residue: Any,
    *,
    participant_type: Optional[str] = None,
    require_explicit_charge: bool = False,
    use_scene_coordinates: bool = True,
) -> List[PiChargedGroup]:
    """
    Detect positively charged nitrogen centers.
    """

    atoms = normalize_atom_collection(
        atoms_or_residue,
        include_hydrogens=True,
        valid_coordinates_only=True,
    )

    atom_identity_set = {
        id(atom)
        for atom in atoms
    }

    groups: List[PiChargedGroup] = []

    for nitrogen in atoms:
        if get_atom_element(nitrogen) != "N":
            continue

        explicit_positive = atom_has_positive_charge(
            nitrogen,
            infer_from_type=True,
        )

        bonded_atoms = tuple(
            neighbor
            for neighbor in get_bonded_atoms(
                nitrogen,
                include_hydrogens=True,
            )
            if id(neighbor) in atom_identity_set
        )

        heavy_neighbors = tuple(
            atom
            for atom in bonded_atoms
            if is_heavy_atom(atom)
        )

        hydrogen_neighbors = tuple(
            atom
            for atom in bonded_atoms
            if is_hydrogen_atom(atom)
        )

        valence_estimate = (
            len(heavy_neighbors)
            + len(hydrogen_neighbors)
        )

        quaternary_like = len(heavy_neighbors) >= 4

        protonated_like = (
            valence_estimate >= 4
            and len(hydrogen_neighbors) >= 1
        )

        if require_explicit_charge:
            if not explicit_positive:
                continue

        elif not (
            explicit_positive
            or quaternary_like
            or protonated_like
        ):
            continue

        support_atoms = heavy_neighbors

        center = get_atom_coordinate(
            nitrogen,
            use_scene_coordinates=use_scene_coordinates,
        )

        if center is None:
            continue

        residue = get_atom_residue(nitrogen)
        model = get_atom_model(nitrogen)

        effective_charge = calculate_group_effective_charge(
            (nitrogen,),
            inferred_charge=1.0,
        )

        groups.append(
            PiChargedGroup(
                atoms=(nitrogen,),
                atom_references=create_pi_atom_references(
                    (nitrogen,)
                ),
                charge_atoms=(nitrogen,),
                support_atoms=support_atoms,
                group_index=len(groups) + 1,
                group_type=_infer_nitrogen_positive_group_type(
                    nitrogen,
                    bonded_atoms,
                ),
                charge_sign=CHARGE_POSITIVE,
                center=center,
                direction=calculate_group_direction_vector(
                    center,
                    support_atoms,
                    use_scene_coordinates=use_scene_coordinates,
                ),
                plane_normal=None,
                formal_charge=get_atom_formal_charge(
                    nitrogen
                ),
                partial_charge=get_atom_partial_charge(
                    nitrogen
                ),
                effective_charge=effective_charge,
                residue_name=get_residue_name(
                    residue or nitrogen
                ),
                residue_number=get_residue_number(
                    residue or nitrogen
                ),
                chain_id=get_residue_chain_id(
                    residue or nitrogen
                ),
                model_id=get_model_identifier(model),
                participant_type=(
                    participant_type
                    or infer_participant_type(
                        residue or nitrogen
                    )
                ),
                valid=True,
                metadata={
                    "detection_method": (
                        "positive_nitrogen_connectivity"
                    ),
                    "explicit_positive_charge": (
                        explicit_positive
                    ),
                    "heavy_neighbor_count": len(
                        heavy_neighbors
                    ),
                    "hydrogen_neighbor_count": len(
                        hydrogen_neighbors
                    ),
                },
            )
        )

    return groups


# -----------------------------------------------------------------------------
# 6.10. Detecção de metais catiônicos
# -----------------------------------------------------------------------------

def detect_metal_cations(
    atoms_or_model: Any,
    *,
    participant_type: Optional[str] = None,
    require_positive_charge: bool = False,
    use_scene_coordinates: bool = True,
) -> List[PiChargedGroup]:
    """
    Detect monoatomic metal cations.
    """

    atoms = normalize_atom_collection(
        atoms_or_model,
        include_hydrogens=False,
        valid_coordinates_only=True,
    )

    groups: List[PiChargedGroup] = []

    for atom in atoms:
        element = get_atom_element(atom)

        if element not in COMMON_METAL_ELEMENTS:
            continue

        formal_charge = get_atom_formal_charge(atom)
        partial_charge = get_atom_partial_charge(atom)

        explicit_positive = (
            formal_charge is not None
            and formal_charge > 0.0
        ) or (
            partial_charge is not None
            and partial_charge > 0.0
        )

        if require_positive_charge and not explicit_positive:
            continue

        inferred_charge = (
            formal_charge
            if formal_charge is not None
            else partial_charge
        )

        if inferred_charge is None:
            inferred_charge = 2.0 if element in {
                "MG",
                "CA",
                "ZN",
                "FE",
                "MN",
                "CU",
                "CO",
                "NI",
                "CD",
                "HG",
            } else 1.0

        center = get_atom_coordinate(
            atom,
            use_scene_coordinates=use_scene_coordinates,
        )

        if center is None:
            continue

        residue = get_atom_residue(atom)
        model = get_atom_model(atom)

        groups.append(
            PiChargedGroup(
                atoms=(atom,),
                atom_references=create_pi_atom_references(
                    (atom,)
                ),
                charge_atoms=(atom,),
                support_atoms=(),
                group_index=len(groups) + 1,
                group_type=POSITIVE_GROUP_METAL,
                charge_sign=CHARGE_POSITIVE,
                center=center,
                direction=None,
                plane_normal=None,
                formal_charge=formal_charge,
                partial_charge=partial_charge,
                effective_charge=inferred_charge,
                residue_name=get_residue_name(
                    residue or atom
                ),
                residue_number=get_residue_number(
                    residue or atom
                ),
                chain_id=get_residue_chain_id(
                    residue or atom
                ),
                model_id=get_model_identifier(model),
                participant_type=(
                    participant_type
                    or infer_participant_type(
                        residue or atom
                    )
                ),
                valid=True,
                metadata={
                    "detection_method": "metal_element",
                    "element": element,
                },
            )
        )

    return groups


# -----------------------------------------------------------------------------
# 6.11. Detecção genérica por cargas atômicas
# -----------------------------------------------------------------------------

def _expand_local_charged_environment(
    atom: Any,
    allowed_atom_ids: Set[int],
    *,
    bond_depth: int = DEFAULT_CHARGE_GROUP_BOND_DEPTH,
) -> Tuple[Any, ...]:
    """
    Expand a charged atom into a local bonded environment.
    """

    if bond_depth < 0:
        raise ValueError(
            "bond_depth must be non-negative."
        )

    collected: List[Any] = [atom]
    visited: Set[int] = {id(atom)}
    frontier: List[Tuple[Any, int]] = [
        (
            atom,
            0,
        )
    ]

    while frontier:
        current, depth = frontier.pop(0)

        if depth >= bond_depth:
            continue

        for neighbor in get_bonded_atoms(
            current,
            include_hydrogens=False,
        ):
            neighbor_id = id(neighbor)

            if neighbor_id not in allowed_atom_ids:
                continue

            if neighbor_id in visited:
                continue

            visited.add(neighbor_id)
            collected.append(neighbor)
            frontier.append(
                (
                    neighbor,
                    depth + 1,
                )
            )

    return tuple(collected)


def detect_explicitly_charged_atom_groups(
    atoms_or_model: Any,
    *,
    charge_sign: Optional[str] = None,
    participant_type: Optional[str] = None,
    bond_depth: int = DEFAULT_CHARGE_GROUP_BOND_DEPTH,
    minimum_charge_magnitude: float = (
        DEFAULT_MINIMUM_GROUP_CHARGE_MAGNITUDE
    ),
    use_scene_coordinates: bool = True,
) -> List[PiChargedGroup]:
    """
    Detect generic groups centered on explicitly charged atoms.
    """

    atoms = normalize_atom_collection(
        atoms_or_model,
        include_hydrogens=False,
        valid_coordinates_only=True,
    )

    allowed_atom_ids = {
        id(atom)
        for atom in atoms
    }

    requested_sign = normalize_charge_sign(
        charge_sign,
        default=CHARGE_UNKNOWN,
    )

    groups: List[PiChargedGroup] = []

    for atom in atoms:
        effective_charge = get_atom_effective_charge(atom)

        if effective_charge is None:
            continue

        detected_sign = charge_sign_from_value(
            effective_charge
        )

        if detected_sign not in {
            CHARGE_POSITIVE,
            CHARGE_NEGATIVE,
        }:
            continue

        if (
            abs(effective_charge)
            < minimum_charge_magnitude
        ):
            continue

        if (
            requested_sign != CHARGE_UNKNOWN
            and detected_sign != requested_sign
        ):
            continue

        group_atoms = _expand_local_charged_environment(
            atom,
            allowed_atom_ids,
            bond_depth=bond_depth,
        )

        center = calculate_charged_group_center(
            group_atoms,
            charge_atoms=(atom,),
            charge_sign=detected_sign,
            use_scene_coordinates=use_scene_coordinates,
        )

        if center is None:
            continue

        support_atoms = tuple(
            candidate
            for candidate in group_atoms
            if candidate is not atom
        )

        residue = get_atom_residue(atom)
        model = get_atom_model(atom)

        groups.append(
            PiChargedGroup(
                atoms=group_atoms,
                atom_references=create_pi_atom_references(
                    group_atoms
                ),
                charge_atoms=(atom,),
                support_atoms=support_atoms,
                group_index=len(groups) + 1,
                group_type=(
                    POSITIVE_GROUP_GENERIC
                    if detected_sign == CHARGE_POSITIVE
                    else NEGATIVE_GROUP_GENERIC
                ),
                charge_sign=detected_sign,
                center=center,
                direction=calculate_group_direction_vector(
                    center,
                    support_atoms,
                    use_scene_coordinates=use_scene_coordinates,
                ),
                plane_normal=calculate_group_plane_normal(
                    group_atoms,
                    use_scene_coordinates=use_scene_coordinates,
                ),
                formal_charge=calculate_group_formal_charge(
                    group_atoms
                ),
                partial_charge=calculate_group_partial_charge(
                    group_atoms
                ),
                effective_charge=calculate_group_effective_charge(
                    group_atoms,
                    inferred_charge=effective_charge,
                ),
                residue_name=get_residue_name(
                    residue or atom
                ),
                residue_number=get_residue_number(
                    residue or atom
                ),
                chain_id=get_residue_chain_id(
                    residue or atom
                ),
                model_id=get_model_identifier(model),
                participant_type=(
                    participant_type
                    or infer_participant_type(
                        residue or atom
                    )
                ),
                valid=True,
                metadata={
                    "detection_method": (
                        "explicit_atomic_charge"
                    ),
                    "central_atom": get_atom_identifier(
                        atom
                    ),
                    "bond_depth": bond_depth,
                },
            )
        )

    return groups


# -----------------------------------------------------------------------------
# 6.12. Identidade e deduplicação de grupos carregados
# -----------------------------------------------------------------------------

def get_charged_group_identity_key(
    group: PiChargedGroup,
) -> Tuple[Any, ...]:
    """
    Return a hashable identity key for a charged group.
    """

    if not isinstance(group, PiChargedGroup):
        raise TypeError(
            "group must be a PiChargedGroup."
        )

    atom_ids = tuple(
        sorted(
            id(atom)
            for atom in group.atoms
        )
    )

    charge_atom_ids = tuple(
        sorted(
            id(atom)
            for atom in group.charge_atoms
        )
    )

    return (
        group.model_id,
        group.chain_id,
        group.residue_name,
        group.residue_number,
        group.group_type,
        group.charge_sign,
        atom_ids,
        charge_atom_ids,
    )


def _charged_group_priority(
    group: PiChargedGroup,
) -> Tuple[int, float, int]:
    """
    Return a priority tuple used during deduplication.
    """

    method = str(
        group.metadata.get(
            "detection_method",
            "",
        )
    )

    method_priority = {
        "known_residue_definition": 5,
        "phosphorus_connectivity": 4,
        "carboxylate_connectivity": 4,
        "positive_nitrogen_connectivity": 4,
        "metal_element": 4,
        "explicit_atomic_charge": 2,
    }.get(method, 1)

    charge_magnitude = abs(
        group.effective_charge
        if group.effective_charge is not None
        else 0.0
    )

    return (
        method_priority,
        charge_magnitude,
        len(group.atoms),
    )


def charged_groups_overlap(
    group_1: PiChargedGroup,
    group_2: PiChargedGroup,
    *,
    minimum_shared_fraction: float = 0.50,
) -> bool:
    """
    Return whether two charged groups substantially overlap.
    """

    atom_ids_1 = {
        id(atom)
        for atom in group_1.atoms
    }

    atom_ids_2 = {
        id(atom)
        for atom in group_2.atoms
    }

    if not atom_ids_1 or not atom_ids_2:
        return False

    shared_count = len(
        atom_ids_1 & atom_ids_2
    )

    denominator = min(
        len(atom_ids_1),
        len(atom_ids_2),
    )

    return (
        shared_count / denominator
        >= minimum_shared_fraction
    )


def deduplicate_charged_groups(
    groups: Iterable[PiChargedGroup],
) -> List[PiChargedGroup]:
    """
    Remove identical or substantially overlapping charged groups.
    """

    group_list = list(groups)
    unique: List[PiChargedGroup] = []

    group_list.sort(
        key=_charged_group_priority,
        reverse=True,
    )

    for candidate in group_list:
        duplicate_index: Optional[int] = None

        for index, existing in enumerate(unique):
            same_sign = (
                candidate.charge_sign
                == existing.charge_sign
            )

            same_model = (
                candidate.model_id
                == existing.model_id
            )

            same_residue = (
                candidate.chain_id
                == existing.chain_id
                and candidate.residue_name
                == existing.residue_name
                and candidate.residue_number
                == existing.residue_number
            )

            if not (
                same_sign
                and same_model
                and same_residue
            ):
                continue

            if (
                get_charged_group_identity_key(candidate)
                == get_charged_group_identity_key(existing)
            ) or charged_groups_overlap(
                candidate,
                existing,
            ):
                duplicate_index = index
                break

        if duplicate_index is None:
            unique.append(candidate)
            continue

        existing = unique[duplicate_index]

        if (
            _charged_group_priority(candidate)
            > _charged_group_priority(existing)
        ):
            unique[duplicate_index] = candidate

    unique.sort(
        key=lambda group: (
            group.model_id or "",
            group.chain_id or "",
            str(group.residue_number or ""),
            group.residue_name or "",
            group.charge_sign,
            group.group_type,
        )
    )

    for group_index, group in enumerate(
        unique,
        start=1,
    ):
        group.group_index = group_index

        if not group.group_id:
            group.group_id = group.build_group_id()

    return unique


# -----------------------------------------------------------------------------
# 6.13. Validação de grupos carregados
# -----------------------------------------------------------------------------

def validate_charged_group(
    group: PiChargedGroup,
    *,
    minimum_charge_magnitude: float = (
        DEFAULT_MINIMUM_GROUP_CHARGE_MAGNITUDE
    ),
    require_center: bool = True,
    require_charge_evidence: bool = True,
) -> Tuple[bool, Tuple[str, ...]]:
    """
    Validate a charged group.
    """

    if not isinstance(group, PiChargedGroup):
        raise TypeError(
            "group must be a PiChargedGroup."
        )

    messages: List[str] = []

    if not group.atoms:
        messages.append(
            "Charged group contains no atoms."
        )

    if group.charge_sign not in {
        CHARGE_POSITIVE,
        CHARGE_NEGATIVE,
    }:
        messages.append(
            "Charged group sign must be positive or negative."
        )

    if require_center and group.center is None:
        messages.append(
            "Charged group center is unavailable."
        )

    if group.center is not None:
        try:
            _coerce_coordinate3d(
                group.center,
                field_name="group.center",
            )

        except (TypeError, ValueError):
            messages.append(
                "Charged group center is invalid."
            )

    effective_charge = group.effective_charge

    if effective_charge is None:
        effective_charge = calculate_group_effective_charge(
            group.atoms
        )

        group.effective_charge = effective_charge

    if require_charge_evidence:
        if effective_charge is None:
            messages.append(
                "No explicit or inferred charge is available."
            )

        elif (
            abs(effective_charge)
            < minimum_charge_magnitude
        ):
            messages.append(
                "Charge magnitude is below the configured threshold."
            )

        elif (
            group.charge_sign == CHARGE_POSITIVE
            and effective_charge <= 0.0
        ):
            messages.append(
                "Effective charge is inconsistent with a positive group."
            )

        elif (
            group.charge_sign == CHARGE_NEGATIVE
            and effective_charge >= 0.0
        ):
            messages.append(
                "Effective charge is inconsistent with a negative group."
            )

    group.valid = not messages

    existing_messages = list(
        group.validation_messages
    )

    existing_messages.extend(
        message
        for message in messages
        if message not in existing_messages
    )

    group.validation_messages = tuple(
        existing_messages
    )

    return group.valid, tuple(messages)


def validate_charged_groups(
    groups: Iterable[PiChargedGroup],
    *,
    minimum_charge_magnitude: float = (
        DEFAULT_MINIMUM_GROUP_CHARGE_MAGNITUDE
    ),
    remove_invalid: bool = False,
) -> List[PiChargedGroup]:
    """
    Validate multiple charged groups.
    """

    validated: List[PiChargedGroup] = []

    for group in groups:
        valid, _ = validate_charged_group(
            group,
            minimum_charge_magnitude=(
                minimum_charge_magnitude
            ),
        )

        if remove_invalid and not valid:
            continue

        validated.append(group)

    return validated


# -----------------------------------------------------------------------------
# 6.14. Detecção integrada de grupos carregados
# -----------------------------------------------------------------------------

def detect_charged_groups(
    molecular_input: Any,
    *,
    config: Optional[PiAnalysisConfig] = None,
    participant_type: Optional[str] = None,
    charge_sign: Optional[str] = None,
    include_known_residue_groups: bool = True,
    include_generic_carboxylates: bool = True,
    include_phosphates: bool = True,
    include_positive_nitrogens: bool = True,
    include_metals: bool = True,
    include_explicit_atomic_charges: bool = True,
    ligand_residue_names: Optional[Collection[str]] = None,
    receptor_residue_names: Optional[Collection[str]] = None,
) -> List[PiChargedGroup]:
    """
    Detect charged groups in a model, residue or atom collection.
    """

    analysis_config = (
        config
        if config is not None
        else create_default_pi_config()
    )

    if not isinstance(
        analysis_config,
        PiAnalysisConfig,
    ):
        raise TypeError(
            "config must be a PiAnalysisConfig or None."
        )

    requested_sign = normalize_charge_sign(
        charge_sign,
        default=CHARGE_UNKNOWN,
    )

    atoms = normalize_atom_collection(
        molecular_input,
        include_hydrogens=True,
        valid_coordinates_only=True,
    )

    residues = normalize_residue_collection(
        atoms
    )

    detected: List[PiChargedGroup] = []

    if include_known_residue_groups:
        for residue in residues:
            residue_participant_type = (
                participant_type
                or infer_participant_type(
                    residue,
                    ligand_residue_names=ligand_residue_names,
                    receptor_residue_names=receptor_residue_names,
                )
            )

            detected.extend(
                detect_known_residue_charged_groups(
                    residue,
                    include_positive=(
                        requested_sign
                        in {
                            CHARGE_POSITIVE,
                            CHARGE_UNKNOWN,
                        }
                    ),
                    include_negative=(
                        requested_sign
                        in {
                            CHARGE_NEGATIVE,
                            CHARGE_UNKNOWN,
                        }
                    ),
                    participant_type=(
                        residue_participant_type
                    ),
                    ligand_residue_names=(
                        ligand_residue_names
                    ),
                    receptor_residue_names=(
                        receptor_residue_names
                    ),
                )
            )

    if (
        include_generic_carboxylates
        and requested_sign
        in {
            CHARGE_NEGATIVE,
            CHARGE_UNKNOWN,
        }
    ):
        detected.extend(
            detect_carboxylate_groups(
                atoms,
                participant_type=participant_type,
            )
        )

    if (
        include_phosphates
        and requested_sign
        in {
            CHARGE_NEGATIVE,
            CHARGE_UNKNOWN,
        }
    ):
        detected.extend(
            detect_phosphate_groups(
                atoms,
                participant_type=participant_type,
            )
        )

    if (
        include_positive_nitrogens
        and requested_sign
        in {
            CHARGE_POSITIVE,
            CHARGE_UNKNOWN,
        }
    ):
        detected.extend(
            detect_positive_nitrogen_groups(
                atoms,
                participant_type=participant_type,
            )
        )

    if (
        include_metals
        and requested_sign
        in {
            CHARGE_POSITIVE,
            CHARGE_UNKNOWN,
        }
    ):
        detected.extend(
            detect_metal_cations(
                atoms,
                participant_type=participant_type,
            )
        )

    if include_explicit_atomic_charges:
        detected.extend(
            detect_explicitly_charged_atom_groups(
                atoms,
                charge_sign=(
                    None
                    if requested_sign == CHARGE_UNKNOWN
                    else requested_sign
                ),
                participant_type=participant_type,
                minimum_charge_magnitude=(
                    analysis_config
                    .minimum_group_charge_magnitude
                ),
            )
        )

    deduplicated = deduplicate_charged_groups(
        detected
    )

    validated = validate_charged_groups(
        deduplicated,
        minimum_charge_magnitude=(
            analysis_config
            .minimum_group_charge_magnitude
        ),
        remove_invalid=True,
    )

    return validated


# -----------------------------------------------------------------------------
# 6.15. Funções específicas para cátions e ânions
# -----------------------------------------------------------------------------

def detect_cationic_groups(
    molecular_input: Any,
    *,
    config: Optional[PiAnalysisConfig] = None,
    participant_type: Optional[str] = None,
    ligand_residue_names: Optional[Collection[str]] = None,
    receptor_residue_names: Optional[Collection[str]] = None,
) -> List[PiChargedGroup]:
    """
    Detect positively charged groups.
    """

    return detect_charged_groups(
        molecular_input,
        config=config,
        participant_type=participant_type,
        charge_sign=CHARGE_POSITIVE,
        ligand_residue_names=ligand_residue_names,
        receptor_residue_names=receptor_residue_names,
    )


def detect_anionic_groups(
    molecular_input: Any,
    *,
    config: Optional[PiAnalysisConfig] = None,
    participant_type: Optional[str] = None,
    ligand_residue_names: Optional[Collection[str]] = None,
    receptor_residue_names: Optional[Collection[str]] = None,
) -> List[PiChargedGroup]:
    """
    Detect negatively charged groups.
    """

    return detect_charged_groups(
        molecular_input,
        config=config,
        participant_type=participant_type,
        charge_sign=CHARGE_NEGATIVE,
        ligand_residue_names=ligand_residue_names,
        receptor_residue_names=receptor_residue_names,
    )


# -----------------------------------------------------------------------------
# 6.16. Detecção para receptor e ligante
# -----------------------------------------------------------------------------

def detect_receptor_charged_groups(
    receptor: Any,
    *,
    config: Optional[PiAnalysisConfig] = None,
    charge_sign: Optional[str] = None,
) -> List[PiChargedGroup]:
    """
    Detect charged groups associated with a receptor.
    """

    return detect_charged_groups(
        receptor,
        config=config,
        participant_type=PARTICIPANT_RECEPTOR,
        charge_sign=charge_sign,
    )


def detect_ligand_charged_groups(
    ligand: Any,
    *,
    config: Optional[PiAnalysisConfig] = None,
    charge_sign: Optional[str] = None,
) -> List[PiChargedGroup]:
    """
    Detect charged groups associated with a ligand.
    """

    return detect_charged_groups(
        ligand,
        config=config,
        participant_type=PARTICIPANT_LIGAND,
        charge_sign=charge_sign,
    )


def detect_pi_analysis_charged_groups(
    normalized_input: PiNormalizedInput,
    *,
    config: Optional[PiAnalysisConfig] = None,
) -> Tuple[
    List[PiChargedGroup],
    List[PiChargedGroup],
]:
    """
    Detect receptor and ligand charged groups.
    """

    if not isinstance(
        normalized_input,
        PiNormalizedInput,
    ):
        raise TypeError(
            "normalized_input must be a PiNormalizedInput."
        )

    analysis_config = (
        config
        if config is not None
        else create_default_pi_config()
    )

    receptor_groups = detect_receptor_charged_groups(
        normalized_input.receptor_atoms,
        config=analysis_config,
    )

    ligand_groups = detect_ligand_charged_groups(
        normalized_input.ligand_atoms,
        config=analysis_config,
    )

    return (
        receptor_groups,
        ligand_groups,
    )


# -----------------------------------------------------------------------------
# 6.17. Separação por sinal
# -----------------------------------------------------------------------------

def split_charged_groups_by_sign(
    groups: Iterable[PiChargedGroup],
) -> Tuple[
    List[PiChargedGroup],
    List[PiChargedGroup],
]:
    """
    Split charged groups into cationic and anionic collections.
    """

    cations: List[PiChargedGroup] = []
    anions: List[PiChargedGroup] = []

    for group in groups:
        if group.charge_sign == CHARGE_POSITIVE:
            cations.append(group)

        elif group.charge_sign == CHARGE_NEGATIVE:
            anions.append(group)

    return cations, anions


def filter_charged_groups_by_participant(
    groups: Iterable[PiChargedGroup],
    participant_type: str,
) -> List[PiChargedGroup]:
    """
    Filter charged groups by molecular participant type.
    """

    normalized_type = str(
        participant_type
    ).strip().lower()

    return [
        group
        for group in groups
        if group.participant_type == normalized_type
    ]


# -----------------------------------------------------------------------------
# 6.18. Geometria entre grupos carregados e anéis
# -----------------------------------------------------------------------------

def calculate_charged_group_ring_geometry(
    group: PiChargedGroup,
    ring: PiRing,
    *,
    config: Optional[PiAnalysisConfig] = None,
    strict: bool = False,
) -> Optional[PiPointRingGeometry]:
    """
    Calculate point-ring geometry for a charged group.
    """

    if not isinstance(
        group,
        PiChargedGroup,
    ):
        raise TypeError(
            "group must be a PiChargedGroup."
        )

    if group.center is None:
        if strict:
            raise PiGeometryError(
                "Charged group center is unavailable."
            )

        return None

    direction = (
        group.direction
        if group.direction is not None
        else group.plane_normal
    )

    return calculate_point_ring_geometry(
        group.center,
        ring,
        direction_vector=direction,
        config=config,
        strict=strict,
    )


def charged_group_is_on_ring_face(
    group: PiChargedGroup,
    ring: PiRing,
    *,
    maximum_radial_offset: float,
    maximum_plane_distance: float,
    config: Optional[PiAnalysisConfig] = None,
) -> bool:
    """
    Return whether a charged group lies above or below a ring face.
    """

    geometry = calculate_charged_group_ring_geometry(
        group,
        ring,
        config=config,
        strict=False,
    )

    if geometry is None:
        return False

    return (
        geometry.radial_offset
        <= maximum_radial_offset
        and geometry.absolute_plane_distance
        <= maximum_plane_distance
    )


# -----------------------------------------------------------------------------
# 6.19. Criação de contatos atômicos preliminares
# -----------------------------------------------------------------------------

def create_charged_group_atomic_contacts(
    group: PiChargedGroup,
    ring: PiRing,
    *,
    maximum_distance: float,
) -> Tuple[PiAtomicContact, ...]:
    """
    Create atomic contacts between charged-group atoms and ring atoms.
    """

    maximum_distance_value = (
        _coerce_non_negative_float(
            maximum_distance,
            field_name="maximum_distance",
        )
    )

    contacts: List[PiAtomicContact] = []

    source_atoms = (
        group.charge_atoms
        if group.charge_atoms
        else group.atoms
    )

    for group_atom in source_atoms:
        group_coordinate = get_atom_coordinate(
            group_atom
        )

        if group_coordinate is None:
            continue

        for ring_atom in ring.atoms:
            ring_coordinate = get_atom_coordinate(
                ring_atom
            )

            if ring_coordinate is None:
                continue

            distance = distance_between_points(
                group_coordinate,
                ring_coordinate,
            )

            if distance > maximum_distance_value:
                continue

            contacts.append(
                PiAtomicContact(
                    atom_1=create_pi_atom_reference(
                        group_atom
                    ),
                    atom_2=create_pi_atom_reference(
                        ring_atom
                    ),
                    distance=distance,
                    contact_type=(
                        CATION_PI
                        if group.charge_sign
                        == CHARGE_POSITIVE
                        else ANION_PI
                    ),
                    metadata={
                        "charged_group_id": (
                            group.group_id
                        ),
                        "ring_id": ring.ring_id,
                    },
                )
            )

    contacts.sort(
        key=lambda contact: contact.distance
    )

    return tuple(contacts)


# -----------------------------------------------------------------------------
# 6.20. Resumo de grupos carregados
# -----------------------------------------------------------------------------

def summarize_charged_groups(
    groups: Iterable[PiChargedGroup],
) -> Dict[str, Any]:
    """
    Generate a serializable summary of charged groups.
    """

    group_list = list(groups)

    positive_groups = [
        group
        for group in group_list
        if group.charge_sign == CHARGE_POSITIVE
    ]

    negative_groups = [
        group
        for group in group_list
        if group.charge_sign == CHARGE_NEGATIVE
    ]

    effective_charges = [
        group.effective_charge
        for group in group_list
        if group.effective_charge is not None
    ]

    charge_magnitudes = [
        abs(charge)
        for charge in effective_charges
    ]

    group_type_distribution = Counter(
        group.group_type
        for group in group_list
    )

    participant_distribution = Counter(
        group.participant_type
        for group in group_list
    )

    residue_distribution = Counter(
        group.residue_name or "UNK"
        for group in group_list
    )

    detection_method_distribution = Counter(
        str(
            group.metadata.get(
                "detection_method",
                "unknown",
            )
        )
        for group in group_list
    )

    return {
        "total_groups": len(group_list),
        "positive_groups": len(positive_groups),
        "negative_groups": len(negative_groups),
        "valid_groups": sum(
            1
            for group in group_list
            if group.valid
        ),
        "invalid_groups": sum(
            1
            for group in group_list
            if not group.valid
        ),
        "group_type_distribution": dict(
            group_type_distribution
        ),
        "participant_distribution": dict(
            participant_distribution
        ),
        "residue_distribution": dict(
            residue_distribution
        ),
        "detection_method_distribution": dict(
            detection_method_distribution
        ),
        "effective_charge": {
            "minimum": (
                min(effective_charges)
                if effective_charges
                else None
            ),
            "mean": (
                sum(effective_charges)
                / len(effective_charges)
                if effective_charges
                else None
            ),
            "maximum": (
                max(effective_charges)
                if effective_charges
                else None
            ),
        },
        "charge_magnitude": {
            "minimum": (
                min(charge_magnitudes)
                if charge_magnitudes
                else None
            ),
            "mean": (
                sum(charge_magnitudes)
                / len(charge_magnitudes)
                if charge_magnitudes
                else None
            ),
            "maximum": (
                max(charge_magnitudes)
                if charge_magnitudes
                else None
            ),
        },
        "group_ids": [
            group.group_id
            for group in group_list
        ],
    }


# -----------------------------------------------------------------------------
# 6.21. Preparação integrada
# -----------------------------------------------------------------------------

def prepare_charged_groups(
    molecular_input: Any,
    *,
    config: Optional[PiAnalysisConfig] = None,
    participant_type: Optional[str] = None,
    charge_sign: Optional[str] = None,
) -> List[PiChargedGroup]:
    """
    Run the complete charged-group preparation pipeline.
    """

    groups = detect_charged_groups(
        molecular_input,
        config=config,
        participant_type=participant_type,
        charge_sign=charge_sign,
    )

    groups = deduplicate_charged_groups(
        groups
    )

    groups = validate_charged_groups(
        groups,
        minimum_charge_magnitude=(
            (
                config
                if config is not None
                else create_default_pi_config()
            ).minimum_group_charge_magnitude
        ),
        remove_invalid=True,
    )

    return groups


def prepare_pi_analysis_charged_groups(
    normalized_input: PiNormalizedInput,
    *,
    config: Optional[PiAnalysisConfig] = None,
) -> Dict[str, List[PiChargedGroup]]:
    """
    Prepare and separate receptor and ligand cations and anions.
    """

    receptor_groups, ligand_groups = (
        detect_pi_analysis_charged_groups(
            normalized_input,
            config=config,
        )
    )

    receptor_cations, receptor_anions = (
        split_charged_groups_by_sign(
            receptor_groups
        )
    )

    ligand_cations, ligand_anions = (
        split_charged_groups_by_sign(
            ligand_groups
        )
    )

    return {
        "receptor_groups": receptor_groups,
        "ligand_groups": ligand_groups,
        "receptor_cations": receptor_cations,
        "receptor_anions": receptor_anions,
        "ligand_cations": ligand_cations,
        "ligand_anions": ligand_anions,
    }

# =============================================================================
# 7. DETECÇÃO E GEOMETRIA DE GRUPOS AMIDA
# =============================================================================

# -----------------------------------------------------------------------------
# 7.1. Tipos e constantes auxiliares
# -----------------------------------------------------------------------------

AmideGroupAtomTuple: TypeAlias = Tuple[Any, ...]


AMIDE_GROUP_PEPTIDE: Final[str] = "peptide_amide"
AMIDE_GROUP_PRIMARY: Final[str] = "primary_amide"
AMIDE_GROUP_SECONDARY: Final[str] = "secondary_amide"
AMIDE_GROUP_TERTIARY: Final[str] = "tertiary_amide"
AMIDE_GROUP_CYCLIC: Final[str] = "cyclic_amide"
AMIDE_GROUP_UREA: Final[str] = "urea"
AMIDE_GROUP_CARBAMATE: Final[str] = "carbamate"
AMIDE_GROUP_IMIDE: Final[str] = "imide"
AMIDE_GROUP_LACTAM: Final[str] = "lactam"
AMIDE_GROUP_GENERIC: Final[str] = "generic_amide"


SUPPORTED_AMIDE_GROUP_TYPES: Final[FrozenSet[str]] = frozenset(
    {
        AMIDE_GROUP_PEPTIDE,
        AMIDE_GROUP_PRIMARY,
        AMIDE_GROUP_SECONDARY,
        AMIDE_GROUP_TERTIARY,
        AMIDE_GROUP_CYCLIC,
        AMIDE_GROUP_UREA,
        AMIDE_GROUP_CARBAMATE,
        AMIDE_GROUP_IMIDE,
        AMIDE_GROUP_LACTAM,
        AMIDE_GROUP_GENERIC,
    }
)


DEFAULT_AMIDE_CARBONYL_BOND_MINIMUM: Final[float] = 1.60
DEFAULT_AMIDE_CARBONYL_BOND_MAXIMUM: Final[float] = 2.20

DEFAULT_AMIDE_CN_BOND_MINIMUM: Final[float] = 0.80
DEFAULT_AMIDE_CN_BOND_MAXIMUM: Final[float] = 1.60

DEFAULT_AMIDE_PLANARITY_RMSD: Final[float] = 0.20
DEFAULT_MAXIMUM_AMIDE_PLANARITY_RMSD: Final[float] = 0.35
DEFAULT_MAXIMUM_AMIDE_ATOM_DEVIATION: Final[float] = 0.50

DEFAULT_AMIDE_CARBONYL_DISTANCE_MINIMUM: Final[float] = 1.15
DEFAULT_AMIDE_CARBONYL_DISTANCE_MAXIMUM: Final[float] = 1.40

DEFAULT_AMIDE_CN_DISTANCE_MINIMUM: Final[float] = 1.25
DEFAULT_AMIDE_CN_DISTANCE_MAXIMUM: Final[float] = 1.55

DEFAULT_AMIDE_NEIGHBOR_DISTANCE_MAXIMUM: Final[float] = 1.90

DEFAULT_MINIMUM_AMIDE_ATOM_COUNT: Final[int] = 3

DEFAULT_AMIDE_NORMAL_ORIENTATION_TOLERANCE: Final[float] = 1.0e-8


PROTEIN_BACKBONE_AMIDE_ATOM_NAMES: Final[Tuple[str, ...]] = (
    "C",
    "O",
    "N",
)


PROTEIN_SIDECHAIN_AMIDE_DEFINITIONS: Final[
    Mapping[str, Tuple[Mapping[str, Any], ...]]
] = {
    "ASN": (
        {
            "group_type": AMIDE_GROUP_PRIMARY,
            "carbonyl_carbon": "CG",
            "carbonyl_oxygen": "OD1",
            "amide_nitrogen": "ND2",
            "support_atom_names": ("CB",),
        },
    ),
    "GLN": (
        {
            "group_type": AMIDE_GROUP_PRIMARY,
            "carbonyl_carbon": "CD",
            "carbonyl_oxygen": "OE1",
            "amide_nitrogen": "NE2",
            "support_atom_names": ("CG",),
        },
    ),
}


COMMON_AMIDE_ATOM_TYPE_PATTERNS: Final[Tuple[str, ...]] = (
    "AM",
    "NPL",
    "NPL3",
    "N.AM",
    "N_AM",
    "NAM",
    "C.AM",
    "C_AM",
)


# -----------------------------------------------------------------------------
# 7.2. Normalização do tipo de amida
# -----------------------------------------------------------------------------

def normalize_amide_group_type(
    value: Any,
    *,
    default: str = AMIDE_GROUP_GENERIC,
) -> str:
    """
    Normalize an amide-group type.
    """

    if value is None:
        return default

    normalized = str(value).strip().lower()

    aliases = {
        "peptide": AMIDE_GROUP_PEPTIDE,
        "peptide_amide": AMIDE_GROUP_PEPTIDE,
        "backbone": AMIDE_GROUP_PEPTIDE,
        "backbone_amide": AMIDE_GROUP_PEPTIDE,
        "primary": AMIDE_GROUP_PRIMARY,
        "primary_amide": AMIDE_GROUP_PRIMARY,
        "secondary": AMIDE_GROUP_SECONDARY,
        "secondary_amide": AMIDE_GROUP_SECONDARY,
        "tertiary": AMIDE_GROUP_TERTIARY,
        "tertiary_amide": AMIDE_GROUP_TERTIARY,
        "cyclic": AMIDE_GROUP_CYCLIC,
        "cyclic_amide": AMIDE_GROUP_CYCLIC,
        "lactam": AMIDE_GROUP_LACTAM,
        "urea": AMIDE_GROUP_UREA,
        "carbamate": AMIDE_GROUP_CARBAMATE,
        "imide": AMIDE_GROUP_IMIDE,
        "generic": AMIDE_GROUP_GENERIC,
        "amide": AMIDE_GROUP_GENERIC,
    }

    normalized = aliases.get(
        normalized,
        normalized,
    )

    if normalized not in SUPPORTED_AMIDE_GROUP_TYPES:
        return default

    return normalized


# -----------------------------------------------------------------------------
# 7.3. Reconhecimento de ligações carbonila
# -----------------------------------------------------------------------------

def is_carbonyl_carbon(
    atom: Any,
    *,
    allow_distance_inference: bool = True,
) -> bool:
    """
    Return whether an atom behaves as a carbonyl carbon.
    """

    if get_atom_element(atom) != "C":
        return False

    bonded_oxygens = tuple(
        neighbor
        for neighbor in get_bonded_atoms(
            atom,
            include_hydrogens=False,
        )
        if get_atom_element(neighbor) == "O"
    )

    if not bonded_oxygens:
        return False

    for oxygen in bonded_oxygens:
        bond_order = get_bond_order(
            atom,
            oxygen,
        )

        if (
            bond_order is not None
            and DEFAULT_AMIDE_CARBONYL_BOND_MINIMUM
            <= bond_order
            <= DEFAULT_AMIDE_CARBONYL_BOND_MAXIMUM
        ):
            return True

        if is_aromatic_bond(atom, oxygen):
            return True

        if not allow_distance_inference:
            continue

        carbon_coordinate = get_atom_coordinate(atom)
        oxygen_coordinate = get_atom_coordinate(oxygen)

        if (
            carbon_coordinate is None
            or oxygen_coordinate is None
        ):
            continue

        distance = distance_between_points(
            carbon_coordinate,
            oxygen_coordinate,
        )

        if (
            DEFAULT_AMIDE_CARBONYL_DISTANCE_MINIMUM
            <= distance
            <= DEFAULT_AMIDE_CARBONYL_DISTANCE_MAXIMUM
        ):
            return True

    return False


def get_carbonyl_oxygens(
    carbon: Any,
    *,
    allow_distance_inference: bool = True,
) -> Tuple[Any, ...]:
    """
    Return oxygen atoms behaving as carbonyl oxygens.
    """

    if get_atom_element(carbon) != "C":
        return ()

    carbon_coordinate = get_atom_coordinate(carbon)

    oxygens: List[Any] = []

    for neighbor in get_bonded_atoms(
        carbon,
        include_hydrogens=False,
    ):
        if get_atom_element(neighbor) != "O":
            continue

        bond_order = get_bond_order(
            carbon,
            neighbor,
        )

        accepted = (
            bond_order is not None
            and DEFAULT_AMIDE_CARBONYL_BOND_MINIMUM
            <= bond_order
            <= DEFAULT_AMIDE_CARBONYL_BOND_MAXIMUM
        )

        if is_aromatic_bond(carbon, neighbor):
            accepted = True

        if (
            not accepted
            and allow_distance_inference
            and carbon_coordinate is not None
        ):
            oxygen_coordinate = get_atom_coordinate(neighbor)

            if oxygen_coordinate is not None:
                distance = distance_between_points(
                    carbon_coordinate,
                    oxygen_coordinate,
                )

                accepted = (
                    DEFAULT_AMIDE_CARBONYL_DISTANCE_MINIMUM
                    <= distance
                    <= DEFAULT_AMIDE_CARBONYL_DISTANCE_MAXIMUM
                )

        if accepted:
            oxygens.append(neighbor)

    return tuple(oxygens)


# -----------------------------------------------------------------------------
# 7.4. Reconhecimento de nitrogênio amídico
# -----------------------------------------------------------------------------

def nitrogen_has_amide_atom_type(
    nitrogen: Any,
) -> bool:
    """
    Return whether an atom-type label indicates an amide nitrogen.
    """

    if get_atom_element(nitrogen) != "N":
        return False

    atom_type = get_atom_type(nitrogen)

    if atom_type is None:
        return False

    normalized = str(atom_type).strip().upper()

    return any(
        pattern in normalized
        for pattern in COMMON_AMIDE_ATOM_TYPE_PATTERNS
    )


def is_amide_carbon_nitrogen_bond(
    carbon: Any,
    nitrogen: Any,
    *,
    allow_distance_inference: bool = True,
) -> bool:
    """
    Return whether a carbon–nitrogen bond is compatible with an amide.
    """

    if get_atom_element(carbon) != "C":
        return False

    if get_atom_element(nitrogen) != "N":
        return False

    if not atoms_are_bonded(
        carbon,
        nitrogen,
    ):
        return False

    bond_order = get_bond_order(
        carbon,
        nitrogen,
    )

    if bond_order is not None:
        if (
            DEFAULT_AMIDE_CN_BOND_MINIMUM
            <= bond_order
            <= DEFAULT_AMIDE_CN_BOND_MAXIMUM
        ):
            return True

    if nitrogen_has_amide_atom_type(nitrogen):
        return True

    if not allow_distance_inference:
        return False

    carbon_coordinate = get_atom_coordinate(carbon)
    nitrogen_coordinate = get_atom_coordinate(nitrogen)

    if (
        carbon_coordinate is None
        or nitrogen_coordinate is None
    ):
        return False

    distance = distance_between_points(
        carbon_coordinate,
        nitrogen_coordinate,
    )

    return (
        DEFAULT_AMIDE_CN_DISTANCE_MINIMUM
        <= distance
        <= DEFAULT_AMIDE_CN_DISTANCE_MAXIMUM
    )


def get_amide_nitrogens_for_carbonyl(
    carbonyl_carbon: Any,
    *,
    allow_distance_inference: bool = True,
) -> Tuple[Any, ...]:
    """
    Return nitrogen atoms bound to a carbonyl carbon in an amide-like pattern.
    """

    if not is_carbonyl_carbon(
        carbonyl_carbon,
        allow_distance_inference=allow_distance_inference,
    ):
        return ()

    nitrogens = tuple(
        neighbor
        for neighbor in get_bonded_atoms(
            carbonyl_carbon,
            include_hydrogens=False,
        )
        if (
            get_atom_element(neighbor) == "N"
            and is_amide_carbon_nitrogen_bond(
                carbonyl_carbon,
                neighbor,
                allow_distance_inference=allow_distance_inference,
            )
        )
    )

    return nitrogens


# -----------------------------------------------------------------------------
# 7.5. Classificação estrutural de grupos amida
# -----------------------------------------------------------------------------

def count_nitrogen_non_hydrogen_substituents(
    nitrogen: Any,
    *,
    exclude_atoms: Optional[Collection[Any]] = None,
) -> int:
    """
    Count heavy-atom substituents attached to an amide nitrogen.
    """

    excluded_ids = {
        id(atom)
        for atom in (
            exclude_atoms or ()
        )
    }

    return sum(
        1
        for neighbor in get_bonded_atoms(
            nitrogen,
            include_hydrogens=False,
        )
        if id(neighbor) not in excluded_ids
    )


def detect_amide_hydrogen_count(
    nitrogen: Any,
) -> int:
    """
    Count explicit hydrogens bound to an amide nitrogen.
    """

    return sum(
        1
        for neighbor in get_bonded_atoms(
            nitrogen,
            include_hydrogens=True,
        )
        if is_hydrogen_atom(neighbor)
    )


def carbonyl_carbon_has_second_heteroatom(
    carbonyl_carbon: Any,
    *,
    excluded_atoms: Optional[Collection[Any]] = None,
) -> Tuple[bool, Optional[str]]:
    """
    Detect additional nitrogen or oxygen substitution at a carbonyl carbon.
    """

    excluded_ids = {
        id(atom)
        for atom in (
            excluded_atoms or ()
        )
    }

    heteroatoms = tuple(
        neighbor
        for neighbor in get_bonded_atoms(
            carbonyl_carbon,
            include_hydrogens=False,
        )
        if (
            id(neighbor) not in excluded_ids
            and get_atom_element(neighbor)
            in {
                "N",
                "O",
                "S",
            }
        )
    )

    if not heteroatoms:
        return False, None

    elements = {
        get_atom_element(atom)
        for atom in heteroatoms
    }

    if "N" in elements:
        return True, "nitrogen"

    if "O" in elements:
        return True, "oxygen"

    if "S" in elements:
        return True, "sulfur"

    return True, "other"


def infer_amide_group_type(
    carbonyl_carbon: Any,
    carbonyl_oxygen: Any,
    amide_nitrogen: Any,
    *,
    residue: Optional[Any] = None,
    is_peptide: bool = False,
    is_cyclic: bool = False,
) -> str:
    """
    Infer the most likely amide-group class.
    """

    if is_peptide:
        return AMIDE_GROUP_PEPTIDE

    if is_cyclic:
        return AMIDE_GROUP_LACTAM

    has_second_heteroatom, heteroatom_type = (
        carbonyl_carbon_has_second_heteroatom(
            carbonyl_carbon,
            excluded_atoms=(
                carbonyl_oxygen,
                amide_nitrogen,
            ),
        )
    )

    if has_second_heteroatom:
        if heteroatom_type == "nitrogen":
            return AMIDE_GROUP_UREA

        if heteroatom_type == "oxygen":
            return AMIDE_GROUP_CARBAMATE

    substituent_count = count_nitrogen_non_hydrogen_substituents(
        amide_nitrogen,
        exclude_atoms=(carbonyl_carbon,),
    )

    hydrogen_count = detect_amide_hydrogen_count(
        amide_nitrogen
    )

    if hydrogen_count >= 2:
        return AMIDE_GROUP_PRIMARY

    if hydrogen_count == 1:
        return AMIDE_GROUP_SECONDARY

    if substituent_count >= 2:
        return AMIDE_GROUP_TERTIARY

    if substituent_count == 1:
        return AMIDE_GROUP_SECONDARY

    return AMIDE_GROUP_PRIMARY


# -----------------------------------------------------------------------------
# 7.6. Identificação de ligação peptídica
# -----------------------------------------------------------------------------

def residues_are_sequential(
    residue_1: Any,
    residue_2: Any,
) -> bool:
    """
    Return whether two residues appear sequential in the same chain.
    """

    chain_1 = get_residue_chain_id(residue_1)
    chain_2 = get_residue_chain_id(residue_2)

    if chain_1 != chain_2:
        return False

    number_1 = get_residue_number(residue_1)
    number_2 = get_residue_number(residue_2)

    if (
        not isinstance(number_1, int)
        or not isinstance(number_2, int)
    ):
        return True

    return abs(number_1 - number_2) == 1


def is_protein_peptide_amide(
    carbonyl_carbon: Any,
    carbonyl_oxygen: Any,
    amide_nitrogen: Any,
) -> bool:
    """
    Return whether atoms form a protein backbone peptide bond.
    """

    carbon_name = get_atom_name(
        carbonyl_carbon
    ).upper()

    oxygen_name = get_atom_name(
        carbonyl_oxygen
    ).upper()

    nitrogen_name = get_atom_name(
        amide_nitrogen
    ).upper()

    if (
        carbon_name != "C"
        or oxygen_name != "O"
        or nitrogen_name != "N"
    ):
        return False

    carbon_residue = get_atom_residue(
        carbonyl_carbon
    )

    nitrogen_residue = get_atom_residue(
        amide_nitrogen
    )

    if (
        carbon_residue is None
        or nitrogen_residue is None
    ):
        return False

    if not (
        is_standard_amino_acid_residue(
            carbon_residue
        )
        and is_standard_amino_acid_residue(
            nitrogen_residue
        )
    ):
        return False

    return (
        carbon_residue is nitrogen_residue
        or residues_are_sequential(
            carbon_residue,
            nitrogen_residue,
        )
    )


# -----------------------------------------------------------------------------
# 7.7. Detecção de ciclos contendo amida
# -----------------------------------------------------------------------------

def atoms_belong_to_same_cycle(
    atom_1: Any,
    atom_2: Any,
    molecular_atoms: Iterable[Any],
    *,
    minimum_size: int = 4,
    maximum_size: int = 12,
) -> bool:
    """
    Return whether two atoms occur in at least one common molecular cycle.
    """

    cycles = find_simple_cycles(
        molecular_atoms,
        minimum_size=minimum_size,
        maximum_size=maximum_size,
        heavy_atoms_only=True,
    )

    atom_1_id = id(atom_1)
    atom_2_id = id(atom_2)

    return any(
        atom_1_id in {
            id(atom)
            for atom in cycle
        }
        and atom_2_id in {
            id(atom)
            for atom in cycle
        }
        for cycle in cycles
    )


# -----------------------------------------------------------------------------
# 7.8. Seleção de átomos de suporte
# -----------------------------------------------------------------------------

def get_amide_support_atoms(
    carbonyl_carbon: Any,
    carbonyl_oxygen: Any,
    amide_nitrogen: Any,
    *,
    include_nitrogen_substituents: bool = True,
    include_carbonyl_substituents: bool = True,
) -> Tuple[Any, ...]:
    """
    Return atoms attached to the amide core that define its orientation.
    """

    excluded_ids = {
        id(carbonyl_carbon),
        id(carbonyl_oxygen),
        id(amide_nitrogen),
    }

    support_atoms: List[Any] = []

    if include_carbonyl_substituents:
        support_atoms.extend(
            neighbor
            for neighbor in get_bonded_atoms(
                carbonyl_carbon,
                include_hydrogens=False,
            )
            if id(neighbor) not in excluded_ids
        )

    if include_nitrogen_substituents:
        support_atoms.extend(
            neighbor
            for neighbor in get_bonded_atoms(
                amide_nitrogen,
                include_hydrogens=False,
            )
            if id(neighbor) not in excluded_ids
        )

    return deduplicate_atoms(
        support_atoms
    )


def get_complete_amide_geometry_atoms(
    carbonyl_carbon: Any,
    carbonyl_oxygen: Any,
    amide_nitrogen: Any,
    *,
    support_atoms: Optional[Iterable[Any]] = None,
) -> Tuple[Any, ...]:
    """
    Return the atom set used for amide-plane fitting.
    """

    atoms = [
        carbonyl_carbon,
        carbonyl_oxygen,
        amide_nitrogen,
    ]

    atoms.extend(
        support_atoms or ()
    )

    return tuple(
        atom
        for atom in deduplicate_atoms(atoms)
        if (
            is_heavy_atom(atom)
            and atom_has_valid_coordinate(atom)
        )
    )


# -----------------------------------------------------------------------------
# 7.9. Centro geométrico do grupo amida
# -----------------------------------------------------------------------------

def calculate_amide_group_center(
    carbonyl_carbon: Any,
    carbonyl_oxygen: Any,
    amide_nitrogen: Any,
    *,
    method: str = "core_centroid",
) -> Coordinate3D:
    """
    Calculate the chemically relevant center of an amide group.
    """

    normalized_method = str(
        method
    ).strip().lower()

    carbon_coordinate = require_atom_coordinate(
        carbonyl_carbon
    )

    oxygen_coordinate = require_atom_coordinate(
        carbonyl_oxygen
    )

    nitrogen_coordinate = require_atom_coordinate(
        amide_nitrogen
    )

    if normalized_method == "carbonyl_carbon":
        return carbon_coordinate

    if normalized_method == "carbonyl_midpoint":
        return midpoint(
            carbon_coordinate,
            oxygen_coordinate,
        )

    if normalized_method == "cn_midpoint":
        return midpoint(
            carbon_coordinate,
            nitrogen_coordinate,
        )

    if normalized_method == "core_centroid":
        return calculate_centroid(
            (
                carbon_coordinate,
                oxygen_coordinate,
                nitrogen_coordinate,
            )
        )

    raise ValueError(
        "method must be 'carbonyl_carbon', "
        "'carbonyl_midpoint', 'cn_midpoint' or "
        "'core_centroid'."
    )


# -----------------------------------------------------------------------------
# 7.10. Vetores direcionais do grupo amida
# -----------------------------------------------------------------------------

def calculate_carbonyl_direction(
    carbonyl_carbon: Any,
    carbonyl_oxygen: Any,
) -> Vector3D:
    """
    Return the unit vector from carbonyl carbon toward oxygen.
    """

    carbon_coordinate = require_atom_coordinate(
        carbonyl_carbon
    )

    oxygen_coordinate = require_atom_coordinate(
        carbonyl_oxygen
    )

    direction = normalize_vector(
        subtract_vectors(
            oxygen_coordinate,
            carbon_coordinate,
        ),
        strict=True,
    )

    assert direction is not None

    return direction


def calculate_amide_cn_direction(
    carbonyl_carbon: Any,
    amide_nitrogen: Any,
) -> Vector3D:
    """
    Return the unit vector from carbonyl carbon toward amide nitrogen.
    """

    carbon_coordinate = require_atom_coordinate(
        carbonyl_carbon
    )

    nitrogen_coordinate = require_atom_coordinate(
        amide_nitrogen
    )

    direction = normalize_vector(
        subtract_vectors(
            nitrogen_coordinate,
            carbon_coordinate,
        ),
        strict=True,
    )

    assert direction is not None

    return direction


def calculate_amide_bisector_direction(
    carbonyl_carbon: Any,
    carbonyl_oxygen: Any,
    amide_nitrogen: Any,
) -> Optional[Vector3D]:
    """
    Calculate the in-plane bisector between C=O and C–N directions.
    """

    carbonyl_direction = calculate_carbonyl_direction(
        carbonyl_carbon,
        carbonyl_oxygen,
    )

    cn_direction = calculate_amide_cn_direction(
        carbonyl_carbon,
        amide_nitrogen,
    )

    bisector = add_vectors(
        carbonyl_direction,
        cn_direction,
    )

    return normalize_vector(
        bisector
    )


# -----------------------------------------------------------------------------
# 7.11. Ajuste do plano da amida
# -----------------------------------------------------------------------------

def fit_amide_plane(
    carbonyl_carbon: Any,
    carbonyl_oxygen: Any,
    amide_nitrogen: Any,
    *,
    support_atoms: Optional[Iterable[Any]] = None,
    prefer_numpy: bool = True,
    strict: bool = False,
) -> Optional[PiPlaneGeometry]:
    """
    Fit a plane to an amide group.
    """

    geometry_atoms = get_complete_amide_geometry_atoms(
        carbonyl_carbon,
        carbonyl_oxygen,
        amide_nitrogen,
        support_atoms=support_atoms,
    )

    if len(geometry_atoms) < 3:
        if strict:
            raise PiGeometryError(
                "At least three valid atoms are required "
                "to fit an amide plane."
            )

        return None

    return fit_plane_to_atoms(
        geometry_atoms,
        skip_invalid=False,
        prefer_numpy=prefer_numpy,
        strict=strict,
    )


def orient_amide_normal(
    normal: Sequence[Number],
    carbonyl_carbon: Any,
    carbonyl_oxygen: Any,
    amide_nitrogen: Any,
) -> Vector3D:
    """
    Orient an amide normal deterministically using its core geometry.
    """

    normalized_normal = normalize_vector(
        normal,
        strict=True,
    )

    assert normalized_normal is not None

    carbonyl_direction = (
        calculate_carbonyl_direction(
            carbonyl_carbon,
            carbonyl_oxygen,
        )
    )

    cn_direction = calculate_amide_cn_direction(
        carbonyl_carbon,
        amide_nitrogen,
    )

    local_cross = normalize_vector(
        cross_product(
            carbonyl_direction,
            cn_direction,
        )
    )

    if local_cross is None:
        return orient_normal_deterministically(
            normalized_normal
        )

    return align_normal_to_reference(
        normalized_normal,
        local_cross,
    )


# -----------------------------------------------------------------------------
# 7.12. Planaridade da amida
# -----------------------------------------------------------------------------

def calculate_amide_planarity_score(
    planarity_rmsd: Optional[Number],
    *,
    maximum_rmsd: float = (
        DEFAULT_MAXIMUM_AMIDE_PLANARITY_RMSD
    ),
) -> float:
    """
    Convert amide planarity RMSD into a normalized score.
    """

    rmsd = _normalize_optional_numeric(
        planarity_rmsd
    )

    if rmsd is None:
        return 0.0

    maximum = _coerce_non_negative_float(
        maximum_rmsd,
        field_name="maximum_rmsd",
    )

    if maximum <= 0.0:
        return 1.0 if rmsd <= 0.0 else 0.0

    return max(
        0.0,
        min(
            1.0,
            1.0 - rmsd / maximum,
        ),
    )


def classify_amide_planarity(
    planarity_rmsd: Optional[Number],
    *,
    preferred_rmsd: float = DEFAULT_AMIDE_PLANARITY_RMSD,
    maximum_rmsd: float = (
        DEFAULT_MAXIMUM_AMIDE_PLANARITY_RMSD
    ),
) -> str:
    """
    Classify amide planarity.
    """

    rmsd = _normalize_optional_numeric(
        planarity_rmsd
    )

    if rmsd is None:
        return GEOMETRY_REJECTED

    if rmsd <= preferred_rmsd:
        return GEOMETRY_OPTIMAL

    if rmsd <= maximum_rmsd:
        return GEOMETRY_FAVORABLE

    return GEOMETRY_REJECTED


# -----------------------------------------------------------------------------
# 7.13. Construção de PiAmideGroup
# -----------------------------------------------------------------------------

def create_pi_amide_group(
    carbonyl_carbon: Any,
    carbonyl_oxygen: Any,
    amide_nitrogen: Any,
    *,
    group_index: Optional[int] = None,
    group_type: Optional[str] = None,
    participant_type: Optional[str] = None,
    support_atoms: Optional[Iterable[Any]] = None,
    is_peptide: bool = False,
    is_cyclic: bool = False,
    prefer_numpy: bool = True,
    ligand_residue_names: Optional[Collection[str]] = None,
    receptor_residue_names: Optional[Collection[str]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
    strict: bool = False,
) -> Optional[PiAmideGroup]:
    """
    Create a complete ``PiAmideGroup`` from an amide core.
    """

    try:
        if get_atom_element(
            carbonyl_carbon
        ) != "C":
            raise ValueError(
                "carbonyl_carbon must be carbon."
            )

        if get_atom_element(
            carbonyl_oxygen
        ) != "O":
            raise ValueError(
                "carbonyl_oxygen must be oxygen."
            )

        if get_atom_element(
            amide_nitrogen
        ) != "N":
            raise ValueError(
                "amide_nitrogen must be nitrogen."
            )

        if not atoms_are_bonded(
            carbonyl_carbon,
            carbonyl_oxygen,
        ):
            raise ValueError(
                "Carbonyl carbon and oxygen are not bonded."
            )

        if not atoms_are_bonded(
            carbonyl_carbon,
            amide_nitrogen,
        ):
            raise ValueError(
                "Carbonyl carbon and amide nitrogen are not bonded."
            )

        normalized_support_atoms = (
            tuple(support_atoms)
            if support_atoms is not None
            else get_amide_support_atoms(
                carbonyl_carbon,
                carbonyl_oxygen,
                amide_nitrogen,
            )
        )

        normalized_support_atoms = tuple(
            atom
            for atom in deduplicate_atoms(
                normalized_support_atoms
            )
            if atom_has_valid_coordinate(atom)
        )

        core_atoms = (
            carbonyl_carbon,
            carbonyl_oxygen,
            amide_nitrogen,
        )

        group_atoms = get_complete_amide_geometry_atoms(
            carbonyl_carbon,
            carbonyl_oxygen,
            amide_nitrogen,
            support_atoms=normalized_support_atoms,
        )

        plane = fit_amide_plane(
            carbonyl_carbon,
            carbonyl_oxygen,
            amide_nitrogen,
            support_atoms=normalized_support_atoms,
            prefer_numpy=prefer_numpy,
            strict=True,
        )

        assert plane is not None

        oriented_normal = orient_amide_normal(
            plane.normal,
            carbonyl_carbon,
            carbonyl_oxygen,
            amide_nitrogen,
        )

        center = calculate_amide_group_center(
            carbonyl_carbon,
            carbonyl_oxygen,
            amide_nitrogen,
            method="core_centroid",
        )

        carbonyl_direction = (
            calculate_carbonyl_direction(
                carbonyl_carbon,
                carbonyl_oxygen,
            )
        )

        cn_direction = calculate_amide_cn_direction(
            carbonyl_carbon,
            amide_nitrogen,
        )

        bisector_direction = (
            calculate_amide_bisector_direction(
                carbonyl_carbon,
                carbonyl_oxygen,
                amide_nitrogen,
            )
        )

        carbonyl_residue = get_atom_residue(
            carbonyl_carbon
        )

        nitrogen_residue = get_atom_residue(
            amide_nitrogen
        )

        residue = (
            carbonyl_residue
            if carbonyl_residue is not None
            else nitrogen_residue
        )

        model = get_atom_model(
            carbonyl_carbon
        )

        normalized_participant_type = (
            participant_type
            or infer_participant_type(
                residue or carbonyl_carbon,
                ligand_residue_names=(
                    ligand_residue_names
                ),
                receptor_residue_names=(
                    receptor_residue_names
                ),
            )
        )

        inferred_group_type = (
            normalize_amide_group_type(
                group_type
            )
            if group_type is not None
            else infer_amide_group_type(
                carbonyl_carbon,
                carbonyl_oxygen,
                amide_nitrogen,
                residue=residue,
                is_peptide=is_peptide,
                is_cyclic=is_cyclic,
            )
        )

        carbonyl_bond_order = get_bond_order(
            carbonyl_carbon,
            carbonyl_oxygen,
        )

        cn_bond_order = get_bond_order(
            carbonyl_carbon,
            amide_nitrogen,
        )

        carbonyl_distance = distance_between_points(
            require_atom_coordinate(
                carbonyl_carbon
            ),
            require_atom_coordinate(
                carbonyl_oxygen
            ),
        )

        cn_distance = distance_between_points(
            require_atom_coordinate(
                carbonyl_carbon
            ),
            require_atom_coordinate(
                amide_nitrogen
            ),
        )

        group_metadata = _copy_mapping(
            metadata
        )

        group_metadata.update(
            {
                "plane_fit_method": plane.method,
                "plane_eigenvalues": list(
                    plane.eigenvalues
                ),
                "signed_plane_deviations": list(
                    plane.signed_deviations
                ),
                "carbonyl_bond_order": (
                    carbonyl_bond_order
                ),
                "cn_bond_order": cn_bond_order,
                "carbonyl_distance": (
                    carbonyl_distance
                ),
                "cn_distance": cn_distance,
                "carbonyl_direction": list(
                    carbonyl_direction
                ),
                "cn_direction": list(
                    cn_direction
                ),
                "bisector_direction": (
                    list(bisector_direction)
                    if bisector_direction is not None
                    else None
                ),
                "is_peptide": bool(is_peptide),
                "is_cyclic": bool(is_cyclic),
            }
        )

        group = PiAmideGroup(
            atoms=group_atoms,
            atom_references=create_pi_atom_references(
                group_atoms,
                skip_invalid=False,
            ),
            core_atoms=core_atoms,
            support_atoms=normalized_support_atoms,
            carbonyl_carbon=carbonyl_carbon,
            carbonyl_oxygen=carbonyl_oxygen,
            amide_nitrogen=amide_nitrogen,
            group_index=group_index,
            group_type=inferred_group_type,
            center=center,
            normal=oriented_normal,
            direction=carbonyl_direction,
            carbonyl_direction=carbonyl_direction,
            cn_direction=cn_direction,
            planarity_rmsd=plane.planarity_rmsd,
            maximum_plane_deviation=(
                plane.maximum_deviation
            ),
            carbonyl_bond_order=carbonyl_bond_order,
            cn_bond_order=cn_bond_order,
            carbonyl_distance=carbonyl_distance,
            cn_distance=cn_distance,
            residue_name=get_residue_name(
                residue or carbonyl_carbon
            ),
            residue_number=get_residue_number(
                residue or carbonyl_carbon
            ),
            chain_id=get_residue_chain_id(
                residue or carbonyl_carbon
            ),
            model_id=get_model_identifier(model),
            participant_type=normalized_participant_type,
            is_peptide=is_peptide,
            is_cyclic=is_cyclic,
            valid=True,
            metadata=group_metadata,
        )

        if not group.group_id:
            group.group_id = group.build_group_id()

        return group

    except (
        PiGeometryError,
        PiAtomAccessError,
        PiCoordinateError,
        TypeError,
        ValueError,
        ArithmeticError,
    ):
        if strict:
            raise

        return None


# -----------------------------------------------------------------------------
# 7.14. Detecção por definição conhecida de resíduos
# -----------------------------------------------------------------------------

def detect_sidechain_amide_groups(
    residue: Any,
    *,
    participant_type: Optional[str] = None,
    prefer_numpy: bool = True,
    ligand_residue_names: Optional[Collection[str]] = None,
    receptor_residue_names: Optional[Collection[str]] = None,
) -> List[PiAmideGroup]:
    """
    Detect side-chain amides in standard amino acids.
    """

    residue_name = get_residue_name(
        residue
    )

    definitions = (
        PROTEIN_SIDECHAIN_AMIDE_DEFINITIONS.get(
            residue_name,
            (),
        )
    )

    if not definitions:
        return []

    atom_map = map_atoms_by_name(
        residue
    )

    groups: List[PiAmideGroup] = []

    for definition in definitions:
        carbon = atom_map.get(
            str(
                definition[
                    "carbonyl_carbon"
                ]
            ).upper()
        )

        oxygen = atom_map.get(
            str(
                definition[
                    "carbonyl_oxygen"
                ]
            ).upper()
        )

        nitrogen = atom_map.get(
            str(
                definition[
                    "amide_nitrogen"
                ]
            ).upper()
        )

        if (
            carbon is None
            or oxygen is None
            or nitrogen is None
        ):
            continue

        support_atoms = tuple(
            atom_map[name.upper()]
            for name in definition.get(
                "support_atom_names",
                (),
            )
            if name.upper() in atom_map
        )

        group = create_pi_amide_group(
            carbon,
            oxygen,
            nitrogen,
            group_index=len(groups) + 1,
            group_type=definition.get(
                "group_type",
                AMIDE_GROUP_PRIMARY,
            ),
            participant_type=participant_type,
            support_atoms=support_atoms,
            is_peptide=False,
            is_cyclic=False,
            prefer_numpy=prefer_numpy,
            ligand_residue_names=(
                ligand_residue_names
            ),
            receptor_residue_names=(
                receptor_residue_names
            ),
            metadata={
                "detection_method": (
                    "known_sidechain_definition"
                ),
                "residue_definition": dict(
                    definition
                ),
            },
        )

        if group is not None:
            groups.append(group)

    return groups


# -----------------------------------------------------------------------------
# 7.15. Detecção de ligações peptídicas
# -----------------------------------------------------------------------------

def detect_peptide_amide_groups(
    molecular_input: Any,
    *,
    participant_type: Optional[str] = None,
    prefer_numpy: bool = True,
    include_proline: bool = True,
) -> List[PiAmideGroup]:
    """
    Detect backbone peptide bonds in a protein structure.
    """

    atoms = normalize_atom_collection(
        molecular_input,
        include_hydrogens=True,
        valid_coordinates_only=True,
    )

    atom_ids = {
        id(atom)
        for atom in atoms
    }

    groups: List[PiAmideGroup] = []

    for carbon in atoms:
        if get_atom_name(carbon).upper() != "C":
            continue

        carbon_residue = get_atom_residue(
            carbon
        )

        if (
            carbon_residue is None
            or not is_standard_amino_acid_residue(
                carbon_residue
            )
        ):
            continue

        oxygen_candidates = tuple(
            neighbor
            for neighbor in get_bonded_atoms(
                carbon,
                include_hydrogens=False,
            )
            if (
                id(neighbor) in atom_ids
                and get_atom_name(
                    neighbor
                ).upper() == "O"
            )
        )

        if not oxygen_candidates:
            continue

        nitrogen_candidates = tuple(
            neighbor
            for neighbor in get_bonded_atoms(
                carbon,
                include_hydrogens=False,
            )
            if (
                id(neighbor) in atom_ids
                and get_atom_name(
                    neighbor
                ).upper() == "N"
            )
        )

        for oxygen in oxygen_candidates:
            for nitrogen in nitrogen_candidates:
                nitrogen_residue = get_atom_residue(
                    nitrogen
                )

                if nitrogen_residue is None:
                    continue

                if (
                    not include_proline
                    and get_residue_name(
                        nitrogen_residue
                    ) == "PRO"
                ):
                    continue

                if not is_protein_peptide_amide(
                    carbon,
                    oxygen,
                    nitrogen,
                ):
                    continue

                support_atoms = (
                    get_amide_support_atoms(
                        carbon,
                        oxygen,
                        nitrogen,
                    )
                )

                group = create_pi_amide_group(
                    carbon,
                    oxygen,
                    nitrogen,
                    group_index=len(groups) + 1,
                    group_type=AMIDE_GROUP_PEPTIDE,
                    participant_type=(
                        participant_type
                        or PARTICIPANT_RECEPTOR
                    ),
                    support_atoms=support_atoms,
                    is_peptide=True,
                    prefer_numpy=prefer_numpy,
                    metadata={
                        "detection_method": (
                            "protein_backbone_connectivity"
                        ),
                        "carbonyl_residue": (
                            get_residue_identifier(
                                carbon_residue
                            )
                        ),
                        "nitrogen_residue": (
                            get_residue_identifier(
                                nitrogen_residue
                            )
                        ),
                    },
                )

                if group is not None:
                    groups.append(group)

    return groups


# -----------------------------------------------------------------------------
# 7.16. Detecção genérica por conectividade
# -----------------------------------------------------------------------------

def detect_generic_amide_groups(
    molecular_input: Any,
    *,
    participant_type: Optional[str] = None,
    allow_distance_inference: bool = True,
    prefer_numpy: bool = True,
    detect_cyclic_amides: bool = True,
    ligand_residue_names: Optional[Collection[str]] = None,
    receptor_residue_names: Optional[Collection[str]] = None,
) -> List[PiAmideGroup]:
    """
    Detect amide groups using generic carbonyl–nitrogen connectivity.
    """

    atoms = normalize_atom_collection(
        molecular_input,
        include_hydrogens=True,
        valid_coordinates_only=True,
    )

    atom_ids = {
        id(atom)
        for atom in atoms
    }

    groups: List[PiAmideGroup] = []

    for carbon in atoms:
        if not is_carbonyl_carbon(
            carbon,
            allow_distance_inference=(
                allow_distance_inference
            ),
        ):
            continue

        oxygens = tuple(
            oxygen
            for oxygen in get_carbonyl_oxygens(
                carbon,
                allow_distance_inference=(
                    allow_distance_inference
                ),
            )
            if id(oxygen) in atom_ids
        )

        nitrogens = tuple(
            nitrogen
            for nitrogen in get_amide_nitrogens_for_carbonyl(
                carbon,
                allow_distance_inference=(
                    allow_distance_inference
                ),
            )
            if id(nitrogen) in atom_ids
        )

        if not oxygens or not nitrogens:
            continue

        for oxygen in oxygens:
            for nitrogen in nitrogens:
                peptide = is_protein_peptide_amide(
                    carbon,
                    oxygen,
                    nitrogen,
                )

                cyclic = False

                if detect_cyclic_amides:
                    cyclic = atoms_belong_to_same_cycle(
                        carbon,
                        nitrogen,
                        atoms,
                    )

                support_atoms = get_amide_support_atoms(
                    carbon,
                    oxygen,
                    nitrogen,
                )

                group = create_pi_amide_group(
                    carbon,
                    oxygen,
                    nitrogen,
                    group_index=len(groups) + 1,
                    participant_type=participant_type,
                    support_atoms=support_atoms,
                    is_peptide=peptide,
                    is_cyclic=cyclic,
                    prefer_numpy=prefer_numpy,
                    ligand_residue_names=(
                        ligand_residue_names
                    ),
                    receptor_residue_names=(
                        receptor_residue_names
                    ),
                    metadata={
                        "detection_method": (
                            "generic_amide_connectivity"
                        ),
                        "distance_inference_enabled": (
                            allow_distance_inference
                        ),
                    },
                )

                if group is not None:
                    groups.append(group)

    return groups


# -----------------------------------------------------------------------------
# 7.17. Identidade e deduplicação de grupos amida
# -----------------------------------------------------------------------------

def get_amide_group_identity_key(
    group: PiAmideGroup,
) -> Tuple[Any, ...]:
    """
    Return a stable identity key for a ``PiAmideGroup``.
    """

    if not isinstance(
        group,
        PiAmideGroup,
    ):
        raise TypeError(
            "group must be a PiAmideGroup."
        )

    return (
        group.model_id,
        id(group.carbonyl_carbon),
        id(group.carbonyl_oxygen),
        id(group.amide_nitrogen),
    )


def _amide_group_priority(
    group: PiAmideGroup,
) -> Tuple[int, float, int]:
    """
    Return a priority tuple for amide-group deduplication.
    """

    detection_method = str(
        group.metadata.get(
            "detection_method",
            "",
        )
    )

    method_priority = {
        "known_sidechain_definition": 5,
        "protein_backbone_connectivity": 5,
        "generic_amide_connectivity": 3,
    }.get(
        detection_method,
        1,
    )

    planarity_score = (
        calculate_amide_planarity_score(
            group.planarity_rmsd
        )
    )

    return (
        method_priority,
        planarity_score,
        len(group.atoms),
    )


def amide_groups_overlap(
    group_1: PiAmideGroup,
    group_2: PiAmideGroup,
) -> bool:
    """
    Return whether two amide groups describe the same amide core.
    """

    core_ids_1 = {
        id(group_1.carbonyl_carbon),
        id(group_1.carbonyl_oxygen),
        id(group_1.amide_nitrogen),
    }

    core_ids_2 = {
        id(group_2.carbonyl_carbon),
        id(group_2.carbonyl_oxygen),
        id(group_2.amide_nitrogen),
    }

    return len(
        core_ids_1 & core_ids_2
    ) >= 2


def deduplicate_amide_groups(
    groups: Iterable[PiAmideGroup],
) -> List[PiAmideGroup]:
    """
    Remove duplicate or overlapping amide groups.
    """

    group_list = list(groups)

    group_list.sort(
        key=_amide_group_priority,
        reverse=True,
    )

    unique: List[PiAmideGroup] = []

    for candidate in group_list:
        duplicate_index: Optional[int] = None

        for index, existing in enumerate(unique):
            if (
                get_amide_group_identity_key(
                    candidate
                )
                == get_amide_group_identity_key(
                    existing
                )
            ) or amide_groups_overlap(
                candidate,
                existing,
            ):
                duplicate_index = index
                break

        if duplicate_index is None:
            unique.append(candidate)
            continue

        existing = unique[
            duplicate_index
        ]

        if (
            _amide_group_priority(candidate)
            > _amide_group_priority(existing)
        ):
            unique[
                duplicate_index
            ] = candidate

    unique.sort(
        key=lambda group: (
            group.model_id or "",
            group.chain_id or "",
            str(
                group.residue_number or ""
            ),
            group.residue_name or "",
            get_atom_name(
                group.carbonyl_carbon
            ),
            get_atom_name(
                group.amide_nitrogen
            ),
        )
    )

    for group_index, group in enumerate(
        unique,
        start=1,
    ):
        group.group_index = group_index

        if not group.group_id:
            group.group_id = (
                group.build_group_id()
            )

    return unique


# -----------------------------------------------------------------------------
# 7.18. Validação estrutural de grupos amida
# -----------------------------------------------------------------------------

def validate_amide_group(
    group: PiAmideGroup,
    *,
    maximum_planarity_rmsd: float = (
        DEFAULT_MAXIMUM_AMIDE_PLANARITY_RMSD
    ),
    maximum_atom_deviation: float = (
        DEFAULT_MAXIMUM_AMIDE_ATOM_DEVIATION
    ),
    require_complete_geometry: bool = True,
) -> Tuple[bool, Tuple[str, ...]]:
    """
    Validate the structure and geometry of an amide group.
    """

    if not isinstance(
        group,
        PiAmideGroup,
    ):
        raise TypeError(
            "group must be a PiAmideGroup."
        )

    messages: List[str] = []

    if len(group.core_atoms) < 3:
        messages.append(
            "Amide group must contain three core atoms."
        )

    if get_atom_element(
        group.carbonyl_carbon
    ) != "C":
        messages.append(
            "Carbonyl carbon is invalid."
        )

    if get_atom_element(
        group.carbonyl_oxygen
    ) != "O":
        messages.append(
            "Carbonyl oxygen is invalid."
        )

    if get_atom_element(
        group.amide_nitrogen
    ) != "N":
        messages.append(
            "Amide nitrogen is invalid."
        )

    if not atoms_are_bonded(
        group.carbonyl_carbon,
        group.carbonyl_oxygen,
    ):
        messages.append(
            "Carbonyl carbon and oxygen are not bonded."
        )

    if not atoms_are_bonded(
        group.carbonyl_carbon,
        group.amide_nitrogen,
    ):
        messages.append(
            "Carbonyl carbon and nitrogen are not bonded."
        )

    if require_complete_geometry:
        if group.center is None:
            messages.append(
                "Amide center is unavailable."
            )

        if group.normal is None:
            messages.append(
                "Amide plane normal is unavailable."
            )

        elif normalize_vector(
            group.normal
        ) is None:
            messages.append(
                "Amide plane normal is degenerate."
            )

        if group.direction is None:
            messages.append(
                "Amide carbonyl direction is unavailable."
            )

    if group.planarity_rmsd is None:
        messages.append(
            "Amide planarity RMSD is unavailable."
        )

    elif (
        group.planarity_rmsd
        > maximum_planarity_rmsd
    ):
        messages.append(
            "Amide planarity RMSD exceeds the maximum threshold."
        )

    if (
        group.maximum_plane_deviation
        is None
    ):
        messages.append(
            "Maximum amide-plane deviation is unavailable."
        )

    elif (
        group.maximum_plane_deviation
        > maximum_atom_deviation
    ):
        messages.append(
            "Maximum amide-plane deviation exceeds the threshold."
        )

    if group.carbonyl_distance is not None:
        if not (
            DEFAULT_AMIDE_CARBONYL_DISTANCE_MINIMUM
            <= group.carbonyl_distance
            <= DEFAULT_AMIDE_CARBONYL_DISTANCE_MAXIMUM
        ):
            messages.append(
                "Carbonyl bond distance is outside the expected range."
            )

    if group.cn_distance is not None:
        if not (
            DEFAULT_AMIDE_CN_DISTANCE_MINIMUM
            <= group.cn_distance
            <= DEFAULT_AMIDE_CN_DISTANCE_MAXIMUM
        ):
            messages.append(
                "Amide C–N distance is outside the expected range."
            )

    group.valid = not messages

    existing_messages = list(
        group.validation_messages
    )

    existing_messages.extend(
        message
        for message in messages
        if message not in existing_messages
    )

    group.validation_messages = tuple(
        existing_messages
    )

    return (
        group.valid,
        tuple(messages),
    )


def validate_amide_groups(
    groups: Iterable[PiAmideGroup],
    *,
    maximum_planarity_rmsd: float = (
        DEFAULT_MAXIMUM_AMIDE_PLANARITY_RMSD
    ),
    maximum_atom_deviation: float = (
        DEFAULT_MAXIMUM_AMIDE_ATOM_DEVIATION
    ),
    remove_invalid: bool = False,
) -> List[PiAmideGroup]:
    """
    Validate multiple amide groups.
    """

    validated: List[PiAmideGroup] = []

    for group in groups:
        valid, _ = validate_amide_group(
            group,
            maximum_planarity_rmsd=(
                maximum_planarity_rmsd
            ),
            maximum_atom_deviation=(
                maximum_atom_deviation
            ),
        )

        if remove_invalid and not valid:
            continue

        validated.append(group)

    return validated


# -----------------------------------------------------------------------------
# 7.19. Detecção integrada
# -----------------------------------------------------------------------------

def detect_amide_groups(
    molecular_input: Any,
    *,
    config: Optional[PiAnalysisConfig] = None,
    participant_type: Optional[str] = None,
    include_peptide_amides: bool = True,
    include_sidechain_amides: bool = True,
    include_generic_amides: bool = True,
    include_cyclic_amides: bool = True,
    prefer_numpy: bool = True,
    ligand_residue_names: Optional[Collection[str]] = None,
    receptor_residue_names: Optional[Collection[str]] = None,
) -> List[PiAmideGroup]:
    """
    Detect amide groups in a model, residue or atom collection.
    """

    analysis_config = (
        config
        if config is not None
        else create_default_pi_config()
    )

    if not isinstance(
        analysis_config,
        PiAnalysisConfig,
    ):
        raise TypeError(
            "config must be a PiAnalysisConfig or None."
        )

    atoms = normalize_atom_collection(
        molecular_input,
        include_hydrogens=True,
        valid_coordinates_only=True,
    )

    residues = normalize_residue_collection(
        atoms
    )

    detected: List[PiAmideGroup] = []

    if include_peptide_amides:
        detected.extend(
            detect_peptide_amide_groups(
                atoms,
                participant_type=participant_type,
                prefer_numpy=prefer_numpy,
            )
        )

    if include_sidechain_amides:
        for residue in residues:
            residue_participant_type = (
                participant_type
                or infer_participant_type(
                    residue,
                    ligand_residue_names=(
                        ligand_residue_names
                    ),
                    receptor_residue_names=(
                        receptor_residue_names
                    ),
                )
            )

            detected.extend(
                detect_sidechain_amide_groups(
                    residue,
                    participant_type=(
                        residue_participant_type
                    ),
                    prefer_numpy=prefer_numpy,
                    ligand_residue_names=(
                        ligand_residue_names
                    ),
                    receptor_residue_names=(
                        receptor_residue_names
                    ),
                )
            )

    if include_generic_amides:
        detected.extend(
            detect_generic_amide_groups(
                atoms,
                participant_type=participant_type,
                prefer_numpy=prefer_numpy,
                detect_cyclic_amides=(
                    include_cyclic_amides
                ),
                ligand_residue_names=(
                    ligand_residue_names
                ),
                receptor_residue_names=(
                    receptor_residue_names
                ),
            )
        )

    deduplicated = deduplicate_amide_groups(
        detected
    )

    maximum_planarity_rmsd = getattr(
        analysis_config,
        "maximum_amide_planarity_rmsd",
        DEFAULT_MAXIMUM_AMIDE_PLANARITY_RMSD,
    )

    maximum_atom_deviation = getattr(
        analysis_config,
        "maximum_amide_atom_deviation",
        DEFAULT_MAXIMUM_AMIDE_ATOM_DEVIATION,
    )

    return validate_amide_groups(
        deduplicated,
        maximum_planarity_rmsd=(
            maximum_planarity_rmsd
        ),
        maximum_atom_deviation=(
            maximum_atom_deviation
        ),
        remove_invalid=True,
    )


# -----------------------------------------------------------------------------
# 7.20. Detecção específica para receptor e ligante
# -----------------------------------------------------------------------------

def detect_receptor_amide_groups(
    receptor: Any,
    *,
    config: Optional[PiAnalysisConfig] = None,
    include_peptide_amides: bool = True,
) -> List[PiAmideGroup]:
    """
    Detect amide groups associated with a receptor.
    """

    return detect_amide_groups(
        receptor,
        config=config,
        participant_type=PARTICIPANT_RECEPTOR,
        include_peptide_amides=(
            include_peptide_amides
        ),
    )


def detect_ligand_amide_groups(
    ligand: Any,
    *,
    config: Optional[PiAnalysisConfig] = None,
) -> List[PiAmideGroup]:
    """
    Detect amide groups associated with a ligand.
    """

    return detect_amide_groups(
        ligand,
        config=config,
        participant_type=PARTICIPANT_LIGAND,
        include_peptide_amides=False,
    )


def detect_pi_analysis_amide_groups(
    normalized_input: PiNormalizedInput,
    *,
    config: Optional[PiAnalysisConfig] = None,
) -> Tuple[
    List[PiAmideGroup],
    List[PiAmideGroup],
]:
    """
    Detect receptor and ligand amide groups.
    """

    if not isinstance(
        normalized_input,
        PiNormalizedInput,
    ):
        raise TypeError(
            "normalized_input must be a PiNormalizedInput."
        )

    receptor_groups = (
        detect_receptor_amide_groups(
            normalized_input.receptor_atoms,
            config=config,
        )
    )

    ligand_groups = (
        detect_ligand_amide_groups(
            normalized_input.ligand_atoms,
            config=config,
        )
    )

    return (
        receptor_groups,
        ligand_groups,
    )


# -----------------------------------------------------------------------------
# 7.21. Geometria entre grupo amida e anel aromático
# -----------------------------------------------------------------------------

def calculate_amide_group_ring_geometry(
    group: PiAmideGroup,
    ring: PiRing,
    *,
    config: Optional[PiAnalysisConfig] = None,
    strict: bool = False,
) -> Optional[Dict[str, Any]]:
    """
    Calculate complete geometry between an amide group and an aromatic ring.
    """

    if not isinstance(
        group,
        PiAmideGroup,
    ):
        raise TypeError(
            "group must be a PiAmideGroup."
        )

    if not isinstance(
        ring,
        PiRing,
    ):
        raise TypeError(
            "ring must be a PiRing."
        )

    try:
        if (
            group.center is None
            or group.normal is None
        ):
            raise PiGeometryError(
                "Amide group geometry is incomplete."
            )

        ensure_pi_ring_geometry(
            ring,
            config=config,
            strict=True,
        )

        point_geometry = calculate_point_ring_geometry(
            group.center,
            ring,
            direction_vector=group.direction,
            config=config,
            strict=True,
        )

        assert point_geometry is not None
        assert ring.normal is not None

        plane_angle = angle_between_planes(
            group.normal,
            ring.normal,
            strict=True,
        )

        assert plane_angle is not None

        carbonyl_angle: Optional[float] = None

        if group.carbonyl_direction is not None:
            carbonyl_angle = (
                acute_angle_between_vectors(
                    group.carbonyl_direction,
                    ring.normal,
                    strict=False,
                )
            )

        cn_angle: Optional[float] = None

        if group.cn_direction is not None:
            cn_angle = (
                acute_angle_between_vectors(
                    group.cn_direction,
                    ring.normal,
                    strict=False,
                )
            )

        minimum_atomic_distance = (
            calculate_minimum_atomic_distance(
                group.core_atoms,
                ring.atoms,
                skip_invalid=False,
            )
        )

        maximum_atomic_distance = (
            calculate_maximum_atomic_distance(
                group.core_atoms,
                ring.atoms,
                skip_invalid=False,
            )
        )

        closest_pair = find_closest_atom_pair(
            group.core_atoms,
            ring.atoms,
            skip_invalid=False,
        )

        closest_contact: Optional[
            Dict[str, Any]
        ] = None

        if closest_pair is not None:
            atom_1, atom_2, distance = (
                closest_pair
            )

            closest_contact = {
                "amide_atom": (
                    get_atom_identifier(
                        atom_1
                    )
                ),
                "ring_atom": (
                    get_atom_identifier(
                        atom_2
                    )
                ),
                "distance": distance,
            }

        return {
            "centroid_distance": (
                point_geometry.center_distance
            ),
            "plane_height": (
                point_geometry.absolute_plane_distance
            ),
            "signed_plane_height": (
                point_geometry.signed_plane_distance
            ),
            "radial_offset": (
                point_geometry.radial_offset
            ),
            "plane_angle": plane_angle,
            "carbonyl_angle": carbonyl_angle,
            "cn_angle": cn_angle,
            "minimum_atomic_distance": (
                minimum_atomic_distance
            ),
            "maximum_atomic_distance": (
                maximum_atomic_distance
            ),
            "closest_atomic_contact": (
                closest_contact
            ),
            "amide_planarity_rmsd": (
                group.planarity_rmsd
            ),
            "ring_planarity_rmsd": (
                ring.planarity_rmsd
            ),
            "valid": True,
            "warnings": list(
                point_geometry.warnings
            ),
        }

    except (
        PiGeometryError,
        PiAtomAccessError,
        PiCoordinateError,
        TypeError,
        ValueError,
        ArithmeticError,
    ):
        if strict:
            raise

        return None


# -----------------------------------------------------------------------------
# 7.22. Criação de contatos atômicos amide–π
# -----------------------------------------------------------------------------

def create_amide_ring_atomic_contacts(
    group: PiAmideGroup,
    ring: PiRing,
    *,
    maximum_distance: float,
) -> Tuple[PiAtomicContact, ...]:
    """
    Create atomic contacts between an amide core and an aromatic ring.
    """

    maximum_distance_value = (
        _coerce_non_negative_float(
            maximum_distance,
            field_name="maximum_distance",
        )
    )

    contacts: List[PiAtomicContact] = []

    for amide_atom in group.core_atoms:
        amide_coordinate = get_atom_coordinate(
            amide_atom
        )

        if amide_coordinate is None:
            continue

        for ring_atom in ring.atoms:
            ring_coordinate = get_atom_coordinate(
                ring_atom
            )

            if ring_coordinate is None:
                continue

            distance = distance_between_points(
                amide_coordinate,
                ring_coordinate,
            )

            if distance > maximum_distance_value:
                continue

            contacts.append(
                PiAtomicContact(
                    atom_1=create_pi_atom_reference(
                        amide_atom
                    ),
                    atom_2=create_pi_atom_reference(
                        ring_atom
                    ),
                    distance=distance,
                    contact_type=AMIDE_PI,
                    metadata={
                        "amide_group_id": (
                            group.group_id
                        ),
                        "ring_id": ring.ring_id,
                        "amide_atom_role": (
                            "carbonyl_carbon"
                            if amide_atom
                            is group.carbonyl_carbon
                            else (
                                "carbonyl_oxygen"
                                if amide_atom
                                is group.carbonyl_oxygen
                                else "amide_nitrogen"
                            )
                        ),
                    },
                )
            )

    contacts.sort(
        key=lambda contact: (
            contact.distance,
            contact.atom_1.atom_name,
            contact.atom_2.atom_name,
        )
    )

    return tuple(contacts)


# -----------------------------------------------------------------------------
# 7.23. Atualização de PiInteraction
# -----------------------------------------------------------------------------

def attach_amide_ring_geometry_to_interaction(
    interaction: PiInteraction,
    geometry: Mapping[str, Any],
) -> PiInteraction:
    """
    Attach amide–ring geometry to a ``PiInteraction``.
    """

    if not isinstance(
        interaction,
        PiInteraction,
    ):
        raise TypeError(
            "interaction must be a PiInteraction."
        )

    interaction.centroid_distance = (
        _normalize_optional_numeric(
            geometry.get(
                "centroid_distance"
            )
        )
    )

    interaction.plane_height = (
        _normalize_optional_numeric(
            geometry.get(
                "plane_height"
            )
        )
    )

    interaction.radial_offset = (
        _normalize_optional_numeric(
            geometry.get(
                "radial_offset"
            )
        )
    )

    interaction.lateral_offset = (
        interaction.radial_offset
    )

    interaction.plane_angle = (
        _normalize_optional_numeric(
            geometry.get(
                "plane_angle"
            )
        )
    )

    interaction.normal_angle = (
        interaction.plane_angle
    )

    interaction.minimum_atomic_distance = (
        _normalize_optional_numeric(
            geometry.get(
                "minimum_atomic_distance"
            )
        )
    )

    interaction.maximum_atomic_distance = (
        _normalize_optional_numeric(
            geometry.get(
                "maximum_atomic_distance"
            )
        )
    )

    interaction.ring_1_planarity = (
        _normalize_optional_numeric(
            geometry.get(
                "ring_planarity_rmsd"
            )
        )
    )

    interaction.metadata[
        "amide_ring_geometry"
    ] = dict(geometry)

    for warning in geometry.get(
        "warnings",
        (),
    ):
        if warning not in interaction.warnings:
            interaction.warnings.append(
                str(warning)
            )

    return interaction


# -----------------------------------------------------------------------------
# 7.24. Filtragem preliminar por proximidade
# -----------------------------------------------------------------------------

def filter_amide_ring_candidates(
    amide_groups: Iterable[PiAmideGroup],
    rings: Iterable[PiRing],
    *,
    maximum_centroid_distance: float,
    maximum_minimum_atomic_distance: Optional[float] = None,
    config: Optional[PiAnalysisConfig] = None,
) -> List[
    Tuple[
        PiAmideGroup,
        PiRing,
        Dict[str, Any],
    ]
]:
    """
    Return geometrically plausible amide–ring candidate pairs.
    """

    centroid_limit = _coerce_non_negative_float(
        maximum_centroid_distance,
        field_name="maximum_centroid_distance",
    )

    atomic_limit = (
        _coerce_non_negative_float(
            maximum_minimum_atomic_distance,
            field_name=(
                "maximum_minimum_atomic_distance"
            ),
        )
        if maximum_minimum_atomic_distance
        is not None
        else None
    )

    candidates: List[
        Tuple[
            PiAmideGroup,
            PiRing,
            Dict[str, Any],
        ]
    ] = []

    for group in amide_groups:
        if not group.valid:
            continue

        for ring in rings:
            if not ring.valid:
                continue

            geometry = (
                calculate_amide_group_ring_geometry(
                    group,
                    ring,
                    config=config,
                    strict=False,
                )
            )

            if geometry is None:
                continue

            centroid_distance = (
                geometry[
                    "centroid_distance"
                ]
            )

            if (
                centroid_distance
                > centroid_limit
            ):
                continue

            minimum_distance = (
                geometry.get(
                    "minimum_atomic_distance"
                )
            )

            if (
                atomic_limit is not None
                and minimum_distance is not None
                and minimum_distance
                > atomic_limit
            ):
                continue

            candidates.append(
                (
                    group,
                    ring,
                    geometry,
                )
            )

    candidates.sort(
        key=lambda item: (
            item[2][
                "centroid_distance"
            ],
            (
                item[2].get(
                    "minimum_atomic_distance"
                )
                if item[2].get(
                    "minimum_atomic_distance"
                )
                is not None
                else float("inf")
            ),
        )
    )

    return candidates


# -----------------------------------------------------------------------------
# 7.25. Preparação integrada
# -----------------------------------------------------------------------------

def prepare_amide_groups(
    molecular_input: Any,
    *,
    config: Optional[PiAnalysisConfig] = None,
    participant_type: Optional[str] = None,
    include_peptide_amides: bool = True,
) -> List[PiAmideGroup]:
    """
    Run the complete amide-group preparation pipeline.
    """

    groups = detect_amide_groups(
        molecular_input,
        config=config,
        participant_type=participant_type,
        include_peptide_amides=(
            include_peptide_amides
        ),
    )

    groups = deduplicate_amide_groups(
        groups
    )

    analysis_config = (
        config
        if config is not None
        else create_default_pi_config()
    )

    maximum_planarity_rmsd = getattr(
        analysis_config,
        "maximum_amide_planarity_rmsd",
        DEFAULT_MAXIMUM_AMIDE_PLANARITY_RMSD,
    )

    maximum_atom_deviation = getattr(
        analysis_config,
        "maximum_amide_atom_deviation",
        DEFAULT_MAXIMUM_AMIDE_ATOM_DEVIATION,
    )

    return validate_amide_groups(
        groups,
        maximum_planarity_rmsd=(
            maximum_planarity_rmsd
        ),
        maximum_atom_deviation=(
            maximum_atom_deviation
        ),
        remove_invalid=True,
    )


def prepare_pi_analysis_amide_groups(
    normalized_input: PiNormalizedInput,
    *,
    config: Optional[PiAnalysisConfig] = None,
) -> Dict[str, List[PiAmideGroup]]:
    """
    Prepare receptor and ligand amide groups.
    """

    receptor_groups, ligand_groups = (
        detect_pi_analysis_amide_groups(
            normalized_input,
            config=config,
        )
    )

    return {
        "receptor_amide_groups": (
            receptor_groups
        ),
        "ligand_amide_groups": (
            ligand_groups
        ),
        "all_amide_groups": (
            receptor_groups
            + ligand_groups
        ),
    }


# -----------------------------------------------------------------------------
# 7.26. Resumo de grupos amida
# -----------------------------------------------------------------------------

def summarize_amide_groups(
    groups: Iterable[PiAmideGroup],
) -> Dict[str, Any]:
    """
    Generate a serializable summary of detected amide groups.
    """

    group_list = list(groups)

    valid_groups = [
        group
        for group in group_list
        if group.valid
    ]

    planarity_values = [
        group.planarity_rmsd
        for group in group_list
        if group.planarity_rmsd is not None
    ]

    maximum_deviations = [
        group.maximum_plane_deviation
        for group in group_list
        if (
            group.maximum_plane_deviation
            is not None
        )
    ]

    carbonyl_distances = [
        group.carbonyl_distance
        for group in group_list
        if group.carbonyl_distance is not None
    ]

    cn_distances = [
        group.cn_distance
        for group in group_list
        if group.cn_distance is not None
    ]

    def summarize_numeric_values(
        values: Sequence[float],
    ) -> Dict[str, Optional[float]]:
        if not values:
            return {
                "minimum": None,
                "mean": None,
                "maximum": None,
            }

        return {
            "minimum": min(values),
            "mean": (
                sum(values)
                / len(values)
            ),
            "maximum": max(values),
        }

    group_type_distribution = Counter(
        group.group_type
        for group in group_list
    )

    participant_distribution = Counter(
        group.participant_type
        for group in group_list
    )

    residue_distribution = Counter(
        group.residue_name or "UNK"
        for group in group_list
    )

    detection_method_distribution = Counter(
        str(
            group.metadata.get(
                "detection_method",
                "unknown",
            )
        )
        for group in group_list
    )

    planarity_distribution = Counter(
        classify_amide_planarity(
            group.planarity_rmsd
        )
        for group in group_list
    )

    return {
        "total_groups": len(group_list),
        "valid_groups": len(valid_groups),
        "invalid_groups": (
            len(group_list)
            - len(valid_groups)
        ),
        "peptide_amides": sum(
            1
            for group in group_list
            if group.is_peptide
        ),
        "cyclic_amides": sum(
            1
            for group in group_list
            if group.is_cyclic
        ),
        "group_type_distribution": dict(
            group_type_distribution
        ),
        "participant_distribution": dict(
            participant_distribution
        ),
        "residue_distribution": dict(
            residue_distribution
        ),
        "detection_method_distribution": dict(
            detection_method_distribution
        ),
        "planarity_distribution": dict(
            planarity_distribution
        ),
        "planarity_rmsd": (
            summarize_numeric_values(
                planarity_values
            )
        ),
        "maximum_plane_deviation": (
            summarize_numeric_values(
                maximum_deviations
            )
        ),
        "carbonyl_distance": (
            summarize_numeric_values(
                carbonyl_distances
            )
        ),
        "cn_distance": (
            summarize_numeric_values(
                cn_distances
            )
        ),
        "group_ids": [
            group.group_id
            for group in group_list
        ],
    }



_validate_module_constants()



# =============================================================================
# 8. DETECÇÃO DE INTERAÇÕES π–π
# =============================================================================

# -----------------------------------------------------------------------------
# 8.1. Constantes
# -----------------------------------------------------------------------------

PI_PI_INTERACTION_TYPE: Final[str] = "pi-pi"

PI_PI_GEOMETRY_FACE_TO_FACE: Final[str] = "face-to-face"
PI_PI_GEOMETRY_PARALLEL: Final[str] = "parallel-stacking"
PI_PI_GEOMETRY_DISPLACED: Final[str] = "displaced-stacking"
PI_PI_GEOMETRY_EDGE_TO_FACE: Final[str] = "edge-to-face"
PI_PI_GEOMETRY_T_SHAPED: Final[str] = "t-shaped"
PI_PI_GEOMETRY_BORDERLINE: Final[str] = "borderline-aromatic-contact"
PI_PI_GEOMETRY_REJECTED: Final[str] = "rejected"

SUPPORTED_PI_PI_GEOMETRIES: Final[FrozenSet[str]] = frozenset(
    {
        PI_PI_GEOMETRY_FACE_TO_FACE,
        PI_PI_GEOMETRY_PARALLEL,
        PI_PI_GEOMETRY_DISPLACED,
        PI_PI_GEOMETRY_EDGE_TO_FACE,
        PI_PI_GEOMETRY_T_SHAPED,
        PI_PI_GEOMETRY_BORDERLINE,
        PI_PI_GEOMETRY_REJECTED,
    }
)

PI_PI_FAMILY_PARALLEL: Final[str] = "parallel"
PI_PI_FAMILY_PERPENDICULAR: Final[str] = "perpendicular"
PI_PI_FAMILY_BORDERLINE: Final[str] = "borderline"
PI_PI_FAMILY_REJECTED: Final[str] = "rejected"

PI_PI_DEFAULT_CENTROID_DISTANCE: Final[float] = 4.5
PI_PI_DEFAULT_MAXIMUM_CENTROID_DISTANCE: Final[float] = 6.5

PI_PI_DEFAULT_ATOMIC_CONTACT_DISTANCE: Final[float] = 4.5
PI_PI_DEFAULT_MAXIMUM_ATOMIC_DISTANCE: Final[float] = 5.0

PI_PI_DEFAULT_PARALLEL_ANGLE: Final[float] = 30.0
PI_PI_DEFAULT_FACE_TO_FACE_ANGLE: Final[float] = 15.0

PI_PI_DEFAULT_T_SHAPED_MINIMUM_ANGLE: Final[float] = 60.0
PI_PI_DEFAULT_T_SHAPED_OPTIMAL_ANGLE: Final[float] = 90.0

PI_PI_DEFAULT_FACE_TO_FACE_OFFSET: Final[float] = 1.5
PI_PI_DEFAULT_PARALLEL_OFFSET: Final[float] = 2.5
PI_PI_DEFAULT_DISPLACED_OFFSET: Final[float] = 3.5
PI_PI_DEFAULT_MAXIMUM_OFFSET: Final[float] = 4.5

PI_PI_DEFAULT_MAXIMUM_PLANARITY_RMSD: Final[float] = 0.20
PI_PI_DEFAULT_BORDERLINE_PLANARITY_RMSD: Final[float] = 0.35

PI_PI_EPSILON: Final[float] = 1.0e-12


# -----------------------------------------------------------------------------
# 8.2. Exceções
# -----------------------------------------------------------------------------

class PiPiDetectionError(RuntimeError):
    """
    Base exception for π–π interaction detection.
    """


class PiPiGeometryError(PiPiDetectionError):
    """
    Raised when ring geometry is missing, malformed or degenerate.
    """


class PiPiValidationError(PiPiDetectionError):
    """
    Raised when π–π detection configuration or input is invalid.
    """


# -----------------------------------------------------------------------------
# 8.3. Configuração específica
# -----------------------------------------------------------------------------

@dataclass(slots=True)
class PiPiDetectionConfig:
    """
    Geometric thresholds used for π–π interaction detection.

    Notes
    -----
    Plane angles are normalized to the interval [0, 90] degrees. Therefore,
    antiparallel ring normals are geometrically equivalent to parallel normals.
    """

    # Centroid distances
    optimal_centroid_distance: float = PI_PI_DEFAULT_CENTROID_DISTANCE
    maximum_centroid_distance: float = PI_PI_DEFAULT_MAXIMUM_CENTROID_DISTANCE

    # Atomic contacts
    atomic_contact_distance: float = PI_PI_DEFAULT_ATOMIC_CONTACT_DISTANCE
    maximum_minimum_atomic_distance: float = (
        PI_PI_DEFAULT_MAXIMUM_ATOMIC_DISTANCE
    )

    # Parallel geometries
    face_to_face_maximum_angle: float = PI_PI_DEFAULT_FACE_TO_FACE_ANGLE
    parallel_maximum_angle: float = PI_PI_DEFAULT_PARALLEL_ANGLE

    face_to_face_maximum_offset: float = PI_PI_DEFAULT_FACE_TO_FACE_OFFSET
    parallel_maximum_offset: float = PI_PI_DEFAULT_PARALLEL_OFFSET
    displaced_maximum_offset: float = PI_PI_DEFAULT_DISPLACED_OFFSET

    # Perpendicular geometries
    t_shaped_minimum_angle: float = PI_PI_DEFAULT_T_SHAPED_MINIMUM_ANGLE
    t_shaped_optimal_angle: float = PI_PI_DEFAULT_T_SHAPED_OPTIMAL_ANGLE

    edge_to_face_minimum_offset: float = 0.8
    t_shaped_maximum_offset: float = 2.5
    edge_to_face_maximum_offset: float = PI_PI_DEFAULT_MAXIMUM_OFFSET

    # Planarity
    maximum_planarity_rmsd: float = PI_PI_DEFAULT_MAXIMUM_PLANARITY_RMSD
    borderline_planarity_rmsd: float = (
        PI_PI_DEFAULT_BORDERLINE_PLANARITY_RMSD
    )

    # Borderline aromatic contacts
    allow_borderline_contacts: bool = True
    borderline_maximum_centroid_distance: float = 7.0
    borderline_maximum_atomic_distance: float = 5.0
    borderline_maximum_offset: float = PI_PI_DEFAULT_MAXIMUM_OFFSET

    # Detection behavior
    require_atomic_contact: bool = True
    include_atomic_contacts: bool = True
    include_rejected: bool = False
    deduplicate_results: bool = True

    minimum_ring_atom_count: int = 5
    maximum_ring_atom_count: int = 12

    numeric_tolerance: float = 1.0e-8

    def __post_init__(self) -> None:
        numeric_fields = (
            "optimal_centroid_distance",
            "maximum_centroid_distance",
            "atomic_contact_distance",
            "maximum_minimum_atomic_distance",
            "face_to_face_maximum_angle",
            "parallel_maximum_angle",
            "face_to_face_maximum_offset",
            "parallel_maximum_offset",
            "displaced_maximum_offset",
            "t_shaped_minimum_angle",
            "t_shaped_optimal_angle",
            "edge_to_face_minimum_offset",
            "t_shaped_maximum_offset",
            "edge_to_face_maximum_offset",
            "maximum_planarity_rmsd",
            "borderline_planarity_rmsd",
            "borderline_maximum_centroid_distance",
            "borderline_maximum_atomic_distance",
            "borderline_maximum_offset",
            "numeric_tolerance",
        )

        for field_name in numeric_fields:
            value = getattr(self, field_name)

            try:
                normalized_value = float(value)

            except (TypeError, ValueError) as exc:
                raise PiPiValidationError(
                    f"{field_name} must be numeric."
                ) from exc

            if not math.isfinite(normalized_value):
                raise PiPiValidationError(
                    f"{field_name} must be finite."
                )

            if normalized_value < 0.0:
                raise PiPiValidationError(
                    f"{field_name} cannot be negative."
                )

            setattr(
                self,
                field_name,
                normalized_value,
            )

        if self.optimal_centroid_distance > self.maximum_centroid_distance:
            raise PiPiValidationError(
                "optimal_centroid_distance cannot exceed "
                "maximum_centroid_distance."
            )

        if self.atomic_contact_distance > self.maximum_minimum_atomic_distance:
            raise PiPiValidationError(
                "atomic_contact_distance cannot exceed "
                "maximum_minimum_atomic_distance."
            )

        if self.face_to_face_maximum_angle > self.parallel_maximum_angle:
            raise PiPiValidationError(
                "face_to_face_maximum_angle cannot exceed "
                "parallel_maximum_angle."
            )

        if self.parallel_maximum_angle > 90.0:
            raise PiPiValidationError(
                "parallel_maximum_angle cannot exceed 90 degrees."
            )

        if self.t_shaped_minimum_angle > 90.0:
            raise PiPiValidationError(
                "t_shaped_minimum_angle cannot exceed 90 degrees."
            )

        if self.t_shaped_optimal_angle > 90.0:
            raise PiPiValidationError(
                "t_shaped_optimal_angle cannot exceed 90 degrees."
            )

        if self.face_to_face_maximum_offset > self.parallel_maximum_offset:
            raise PiPiValidationError(
                "face_to_face_maximum_offset cannot exceed "
                "parallel_maximum_offset."
            )

        if self.parallel_maximum_offset > self.displaced_maximum_offset:
            raise PiPiValidationError(
                "parallel_maximum_offset cannot exceed "
                "displaced_maximum_offset."
            )

        if self.maximum_planarity_rmsd > self.borderline_planarity_rmsd:
            raise PiPiValidationError(
                "maximum_planarity_rmsd cannot exceed "
                "borderline_planarity_rmsd."
            )

        if self.minimum_ring_atom_count < 3:
            raise PiPiValidationError(
                "minimum_ring_atom_count must be at least 3."
            )

        if self.maximum_ring_atom_count < self.minimum_ring_atom_count:
            raise PiPiValidationError(
                "maximum_ring_atom_count cannot be lower than "
                "minimum_ring_atom_count."
            )


def create_default_pi_pi_detection_config() -> PiPiDetectionConfig:
    """
    Return the canonical π–π detection configuration.
    """

    return PiPiDetectionConfig()


# -----------------------------------------------------------------------------
# 8.4. Resultado da avaliação geométrica
# -----------------------------------------------------------------------------

@dataclass(slots=True)
class PiPiGeometryEvaluation:
    """
    Complete geometric evaluation of a pair of aromatic systems.
    """

    geometry: str
    geometry_family: str

    centroid_distance: float
    plane_angle: float
    lateral_offset: float
    lateral_offset_ring_1: float
    lateral_offset_ring_2: float
    minimum_atomic_distance: float

    ring_1_planarity_rmsd: float
    ring_2_planarity_rmsd: float
    maximum_planarity_rmsd: float

    centroid_distance_valid: bool
    atomic_distance_valid: bool
    angle_valid: bool
    offset_valid: bool
    planarity_valid: bool

    accepted: bool
    borderline: bool = False

    confidence: float = 0.0
    reasons: Tuple[str, ...] = ()
    warnings: Tuple[str, ...] = ()

    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if self.geometry not in SUPPORTED_PI_PI_GEOMETRIES:
            raise PiPiValidationError(
                f"Unsupported π–π geometry: {self.geometry!r}."
            )

        self.confidence = max(
            0.0,
            min(1.0, float(self.confidence)),
        )

        self.reasons = tuple(
            str(reason)
            for reason in self.reasons
        )

        self.warnings = tuple(
            str(warning)
            for warning in self.warnings
        )

    def to_dict(self) -> Dict[str, Any]:
        return {
            "geometry": self.geometry,
            "geometry_family": self.geometry_family,
            "centroid_distance": self.centroid_distance,
            "plane_angle": self.plane_angle,
            "lateral_offset": self.lateral_offset,
            "lateral_offset_ring_1": self.lateral_offset_ring_1,
            "lateral_offset_ring_2": self.lateral_offset_ring_2,
            "minimum_atomic_distance": self.minimum_atomic_distance,
            "ring_1_planarity_rmsd": self.ring_1_planarity_rmsd,
            "ring_2_planarity_rmsd": self.ring_2_planarity_rmsd,
            "maximum_planarity_rmsd": self.maximum_planarity_rmsd,
            "centroid_distance_valid": self.centroid_distance_valid,
            "atomic_distance_valid": self.atomic_distance_valid,
            "angle_valid": self.angle_valid,
            "offset_valid": self.offset_valid,
            "planarity_valid": self.planarity_valid,
            "accepted": self.accepted,
            "borderline": self.borderline,
            "confidence": self.confidence,
            "reasons": list(self.reasons),
            "warnings": list(self.warnings),
            "metadata": dict(self.metadata),
        }


# -----------------------------------------------------------------------------
# 8.5. Acesso seguro aos objetos das seções anteriores
# -----------------------------------------------------------------------------

def _pi_pi_get_first_attribute(
    object_: Any,
    names: Sequence[str],
    default: Any = None,
) -> Any:
    """
    Return the first existing non-None attribute or mapping value.
    """

    if object_ is None:
        return default

    for name in names:
        if isinstance(object_, Mapping):
            value = object_.get(name, None)

        else:
            value = getattr(object_, name, None)

        if value is not None:
            return value

    return default


def _pi_pi_as_vector3(
    value: Any,
    *,
    field_name: str,
) -> Tuple[float, float, float]:
    """
    Normalize a coordinate-like value to a finite three-dimensional vector.
    """

    if value is None:
        raise PiPiGeometryError(
            f"Missing {field_name}."
        )

    try:
        values = tuple(float(component) for component in value)

    except (TypeError, ValueError) as exc:
        raise PiPiGeometryError(
            f"{field_name} must contain three numeric values."
        ) from exc

    if len(values) != 3:
        raise PiPiGeometryError(
            f"{field_name} must contain exactly three values."
        )

    if not all(math.isfinite(component) for component in values):
        raise PiPiGeometryError(
            f"{field_name} must contain only finite values."
        )

    return values


def _pi_pi_get_ring_centroid(
    ring: Any,
) -> Tuple[float, float, float]:
    value = _pi_pi_get_first_attribute(
        ring,
        (
            "centroid",
            "center",
            "centre",
            "geometric_center",
        ),
    )

    return _pi_pi_as_vector3(
        value,
        field_name="ring centroid",
    )


def _pi_pi_get_ring_normal(
    ring: Any,
) -> Tuple[float, float, float]:
    value = _pi_pi_get_first_attribute(
        ring,
        (
            "normal",
            "plane_normal",
            "normal_vector",
            "unit_normal",
        ),
    )

    normal = _pi_pi_as_vector3(
        value,
        field_name="ring normal",
    )

    return _pi_pi_normalize_vector(
        normal
    )


def _pi_pi_get_ring_planarity(
    ring: Any,
) -> float:
    value = _pi_pi_get_first_attribute(
        ring,
        (
            "planarity_rmsd",
            "plane_rmsd",
            "rmsd_to_plane",
            "planarity",
        ),
        0.0,
    )

    try:
        normalized_value = float(value)

    except (TypeError, ValueError) as exc:
        raise PiPiGeometryError(
            "Ring planarity RMSD must be numeric."
        ) from exc

    if not math.isfinite(normalized_value):
        raise PiPiGeometryError(
            "Ring planarity RMSD must be finite."
        )

    return max(0.0, normalized_value)


def _pi_pi_get_ring_atoms(
    ring: Any,
) -> Tuple[Any, ...]:
    atoms = _pi_pi_get_first_attribute(
        ring,
        (
            "atoms",
            "atom_references",
            "ring_atoms",
        ),
        (),
    )

    try:
        return tuple(atoms)

    except TypeError as exc:
        raise PiPiGeometryError(
            "Ring atoms must be iterable."
        ) from exc


def _pi_pi_get_atom_coordinates(
    atom: Any,
) -> Tuple[float, float, float]:
    value = _pi_pi_get_first_attribute(
        atom,
        (
            "coordinates",
            "coordinate",
            "coords",
            "position",
        ),
    )

    if value is None:
        x = _pi_pi_get_first_attribute(atom, ("x",))
        y = _pi_pi_get_first_attribute(atom, ("y",))
        z = _pi_pi_get_first_attribute(atom, ("z",))

        if x is not None and y is not None and z is not None:
            value = (x, y, z)

    return _pi_pi_as_vector3(
        value,
        field_name="atom coordinates",
    )


def _pi_pi_get_ring_id(
    ring: Any,
    fallback: str,
) -> str:
    value = _pi_pi_get_first_attribute(
        ring,
        (
            "ring_id",
            "system_id",
            "aromatic_system_id",
            "id",
            "identifier",
        ),
        fallback,
    )

    return str(value)


def _pi_pi_get_ring_participant_type(
    ring: Any,
    fallback: Optional[str] = None,
) -> Optional[str]:
    value = _pi_pi_get_first_attribute(
        ring,
        (
            "participant_type",
            "source_type",
            "molecule_type",
            "role",
        ),
        fallback,
    )

    return None if value is None else str(value)


def _pi_pi_get_ring_residue_id(
    ring: Any,
) -> Optional[str]:
    residue_id = _pi_pi_get_first_attribute(
        ring,
        (
            "residue_id",
            "residue_key",
        ),
    )

    if residue_id is not None:
        return str(residue_id)

    chain_id = _pi_pi_get_first_attribute(
        ring,
        ("chain_id", "chain"),
        "",
    )

    residue_name = _pi_pi_get_first_attribute(
        ring,
        ("residue_name", "resname"),
        "",
    )

    residue_number = _pi_pi_get_first_attribute(
        ring,
        (
            "residue_number",
            "residue_index",
            "resid",
        ),
        "",
    )

    if not any(
        value not in (None, "")
        for value in (
            chain_id,
            residue_name,
            residue_number,
        )
    ):
        return None

    return (
        f"{chain_id}:"
        f"{residue_name}:"
        f"{residue_number}"
    )


# -----------------------------------------------------------------------------
# 8.6. Operações vetoriais
# -----------------------------------------------------------------------------

def _pi_pi_vector_subtract(
    vector_1: Sequence[float],
    vector_2: Sequence[float],
) -> Tuple[float, float, float]:
    return (
        float(vector_1[0]) - float(vector_2[0]),
        float(vector_1[1]) - float(vector_2[1]),
        float(vector_1[2]) - float(vector_2[2]),
    )


def _pi_pi_dot(
    vector_1: Sequence[float],
    vector_2: Sequence[float],
) -> float:
    return (
        float(vector_1[0]) * float(vector_2[0])
        + float(vector_1[1]) * float(vector_2[1])
        + float(vector_1[2]) * float(vector_2[2])
    )


def _pi_pi_norm(
    vector: Sequence[float],
) -> float:
    return math.sqrt(
        _pi_pi_dot(vector, vector)
    )


def _pi_pi_normalize_vector(
    vector: Sequence[float],
) -> Tuple[float, float, float]:
    magnitude = _pi_pi_norm(vector)

    if magnitude <= PI_PI_EPSILON:
        raise PiPiGeometryError(
            "Cannot normalize a zero-length vector."
        )

    return (
        float(vector[0]) / magnitude,
        float(vector[1]) / magnitude,
        float(vector[2]) / magnitude,
    )


def _pi_pi_distance(
    point_1: Sequence[float],
    point_2: Sequence[float],
) -> float:
    return _pi_pi_norm(
        _pi_pi_vector_subtract(
            point_1,
            point_2,
        )
    )


def _pi_pi_project_onto_plane(
    vector: Sequence[float],
    normal: Sequence[float],
) -> Tuple[float, float, float]:
    """
    Project a vector onto a plane defined by a unit normal.
    """

    normalized_normal = _pi_pi_normalize_vector(
        normal
    )

    parallel_component = _pi_pi_dot(
        vector,
        normalized_normal,
    )

    return (
        float(vector[0])
        - parallel_component * normalized_normal[0],
        float(vector[1])
        - parallel_component * normalized_normal[1],
        float(vector[2])
        - parallel_component * normalized_normal[2],
    )


def _pi_pi_plane_angle(
    normal_1: Sequence[float],
    normal_2: Sequence[float],
) -> float:
    """
    Calculate the acute angle between two planes in degrees.

    Ring normals pointing in opposite directions still represent parallel
    planes, so the absolute dot product is used.
    """

    unit_1 = _pi_pi_normalize_vector(
        normal_1
    )

    unit_2 = _pi_pi_normalize_vector(
        normal_2
    )

    cosine = abs(
        _pi_pi_dot(
            unit_1,
            unit_2,
        )
    )

    cosine = max(
        -1.0,
        min(1.0, cosine),
    )

    return math.degrees(
        math.acos(cosine)
    )


def _pi_pi_lateral_offsets(
    centroid_1: Sequence[float],
    centroid_2: Sequence[float],
    normal_1: Sequence[float],
    normal_2: Sequence[float],
) -> Tuple[float, float, float]:
    """
    Calculate centroid displacement projected onto each ring plane.

    Returns
    -------
    tuple
        offset_ring_1, offset_ring_2, symmetric_offset.

    The symmetric offset is the arithmetic mean of both projections. This
    avoids assigning a privileged orientation to either aromatic system.
    """

    centroid_vector = _pi_pi_vector_subtract(
        centroid_2,
        centroid_1,
    )

    offset_ring_1 = _pi_pi_norm(
        _pi_pi_project_onto_plane(
            centroid_vector,
            normal_1,
        )
    )

    reverse_vector = (
        -centroid_vector[0],
        -centroid_vector[1],
        -centroid_vector[2],
    )

    offset_ring_2 = _pi_pi_norm(
        _pi_pi_project_onto_plane(
            reverse_vector,
            normal_2,
        )
    )

    symmetric_offset = (
        offset_ring_1 + offset_ring_2
    ) / 2.0

    return (
        offset_ring_1,
        offset_ring_2,
        symmetric_offset,
    )


# -----------------------------------------------------------------------------
# 8.7. Distâncias atômicas e contatos
# -----------------------------------------------------------------------------

def calculate_pi_pi_minimum_atomic_distance(
    ring_1: Any,
    ring_2: Any,
) -> float:
    """
    Calculate the minimum interatomic distance between two aromatic systems.
    """

    atoms_1 = _pi_pi_get_ring_atoms(ring_1)
    atoms_2 = _pi_pi_get_ring_atoms(ring_2)

    if not atoms_1 or not atoms_2:
        raise PiPiGeometryError(
            "Both aromatic systems must contain atoms."
        )

    minimum_distance = math.inf

    for atom_1 in atoms_1:
        coordinates_1 = _pi_pi_get_atom_coordinates(
            atom_1
        )

        for atom_2 in atoms_2:
            coordinates_2 = _pi_pi_get_atom_coordinates(
                atom_2
            )

            distance = _pi_pi_distance(
                coordinates_1,
                coordinates_2,
            )

            if distance < minimum_distance:
                minimum_distance = distance

    if not math.isfinite(minimum_distance):
        raise PiPiGeometryError(
            "Could not calculate minimum atomic distance."
        )

    return minimum_distance


def _pi_pi_construct_atomic_contact(
    atom_1: Any,
    atom_2: Any,
    distance: float,
    *,
    contact_index: int,
    ring_1_id: str,
    ring_2_id: str,
) -> Any:
    """
    Construct a PiAtomicContact while tolerating minor dataclass variations.
    """

    contact_id = (
        f"pi-pi-contact:"
        f"{ring_1_id}:"
        f"{ring_2_id}:"
        f"{contact_index}"
    )

    candidate_values: Dict[str, Any] = {
        "contact_id": contact_id,
        "id": contact_id,
        "interaction_type": PI_PI_INTERACTION_TYPE,
        "atom_1": atom_1,
        "atom_2": atom_2,
        "distance": float(distance),
        "valid": True,
        "metadata": {
            "ring_1_id": ring_1_id,
            "ring_2_id": ring_2_id,
        },
    }

    if is_dataclass(PiAtomicContact):
        supported_fields = {
            field_definition.name
            for field_definition in fields(PiAtomicContact)
        }

        candidate_values = {
            key: value
            for key, value in candidate_values.items()
            if key in supported_fields
        }

    return PiAtomicContact(
        **candidate_values
    )


def find_pi_pi_atomic_contacts(
    ring_1: Any,
    ring_2: Any,
    *,
    maximum_distance: float = PI_PI_DEFAULT_ATOMIC_CONTACT_DISTANCE,
) -> Tuple[Any, ...]:
    """
    Return all atom pairs separated by at most `maximum_distance`.
    """

    maximum_distance = float(maximum_distance)

    if maximum_distance <= 0.0:
        raise PiPiValidationError(
            "maximum_distance must be greater than zero."
        )

    atoms_1 = _pi_pi_get_ring_atoms(ring_1)
    atoms_2 = _pi_pi_get_ring_atoms(ring_2)

    ring_1_id = _pi_pi_get_ring_id(
        ring_1,
        "ring_1",
    )

    ring_2_id = _pi_pi_get_ring_id(
        ring_2,
        "ring_2",
    )

    contacts: List[Any] = []

    for atom_1 in atoms_1:
        coordinates_1 = _pi_pi_get_atom_coordinates(
            atom_1
        )

        for atom_2 in atoms_2:
            coordinates_2 = _pi_pi_get_atom_coordinates(
                atom_2
            )

            distance = _pi_pi_distance(
                coordinates_1,
                coordinates_2,
            )

            if distance <= maximum_distance:
                contacts.append(
                    _pi_pi_construct_atomic_contact(
                        atom_1,
                        atom_2,
                        distance,
                        contact_index=len(contacts) + 1,
                        ring_1_id=ring_1_id,
                        ring_2_id=ring_2_id,
                    )
                )

    contacts.sort(
        key=lambda contact: float(
            _pi_pi_get_first_attribute(
                contact,
                ("distance",),
                math.inf,
            )
        )
    )

    return tuple(contacts)


# -----------------------------------------------------------------------------
# 8.8. Qualidade geométrica
# -----------------------------------------------------------------------------

def _pi_pi_inverse_linear_quality(
    value: float,
    *,
    optimal: float,
    maximum: float,
) -> float:
    if value <= optimal:
        return 1.0

    if value >= maximum:
        return 0.0

    denominator = maximum - optimal

    if denominator <= PI_PI_EPSILON:
        return 0.0

    return 1.0 - (
        (value - optimal)
        / denominator
    )


def _pi_pi_angle_quality(
    angle: float,
    *,
    target: float,
    maximum_deviation: float,
) -> float:
    deviation = abs(
        float(angle) - float(target)
    )

    if deviation >= maximum_deviation:
        return 0.0

    return 1.0 - (
        deviation / maximum_deviation
    )


def calculate_pi_pi_geometry_confidence(
    *,
    geometry: str,
    centroid_distance: float,
    plane_angle: float,
    lateral_offset: float,
    minimum_atomic_distance: float,
    maximum_planarity_rmsd: float,
    config: PiPiDetectionConfig,
) -> float:
    """
    Calculate a normalized geometric confidence score.

    This value represents geometric confidence only. It is not the final
    interaction score from Section 11.
    """

    distance_quality = _pi_pi_inverse_linear_quality(
        centroid_distance,
        optimal=config.optimal_centroid_distance,
        maximum=config.borderline_maximum_centroid_distance,
    )

    atomic_quality = _pi_pi_inverse_linear_quality(
        minimum_atomic_distance,
        optimal=config.atomic_contact_distance,
        maximum=config.borderline_maximum_atomic_distance,
    )

    planarity_quality = _pi_pi_inverse_linear_quality(
        maximum_planarity_rmsd,
        optimal=0.0,
        maximum=config.borderline_planarity_rmsd,
    )

    if geometry in {
        PI_PI_GEOMETRY_FACE_TO_FACE,
        PI_PI_GEOMETRY_PARALLEL,
        PI_PI_GEOMETRY_DISPLACED,
    }:
        angle_quality = _pi_pi_angle_quality(
            plane_angle,
            target=0.0,
            maximum_deviation=max(
                config.parallel_maximum_angle,
                PI_PI_EPSILON,
            ),
        )

        offset_quality = _pi_pi_inverse_linear_quality(
            lateral_offset,
            optimal=config.face_to_face_maximum_offset,
            maximum=config.borderline_maximum_offset,
        )

    elif geometry in {
        PI_PI_GEOMETRY_T_SHAPED,
        PI_PI_GEOMETRY_EDGE_TO_FACE,
    }:
        angle_quality = _pi_pi_angle_quality(
            plane_angle,
            target=config.t_shaped_optimal_angle,
            maximum_deviation=max(
                90.0 - config.t_shaped_minimum_angle,
                PI_PI_EPSILON,
            ),
        )

        if lateral_offset < config.edge_to_face_minimum_offset:
            offset_quality = (
                lateral_offset
                / max(
                    config.edge_to_face_minimum_offset,
                    PI_PI_EPSILON,
                )
            )

        else:
            offset_quality = _pi_pi_inverse_linear_quality(
                lateral_offset,
                optimal=config.t_shaped_maximum_offset,
                maximum=config.edge_to_face_maximum_offset,
            )

    else:
        angle_quality = 0.25
        offset_quality = _pi_pi_inverse_linear_quality(
            lateral_offset,
            optimal=config.displaced_maximum_offset,
            maximum=config.borderline_maximum_offset,
        )

    weighted_sum = (
        0.25 * distance_quality
        + 0.20 * atomic_quality
        + 0.20 * angle_quality
        + 0.20 * offset_quality
        + 0.15 * planarity_quality
    )

    return max(
        0.0,
        min(1.0, weighted_sum),
    )


# -----------------------------------------------------------------------------
# 8.9. Avaliação de empilhamento paralelo
# -----------------------------------------------------------------------------

def evaluate_parallel_stacking(
    *,
    centroid_distance: float,
    plane_angle: float,
    lateral_offset: float,
    minimum_atomic_distance: float,
    maximum_planarity_rmsd: float,
    config: Optional[PiPiDetectionConfig] = None,
) -> PiPiGeometryEvaluation:
    """
    Evaluate face-to-face, parallel and displaced π-stacking geometries.

    Classification order
    --------------------
    1. face-to-face;
    2. parallel stacking;
    3. displaced stacking;
    4. borderline aromatic contact;
    5. rejected.
    """

    if config is None:
        config = create_default_pi_pi_detection_config()

    centroid_valid = (
        centroid_distance
        <= config.maximum_centroid_distance
    )

    atomic_valid = (
        minimum_atomic_distance
        <= config.maximum_minimum_atomic_distance
    )

    angle_valid = (
        plane_angle
        <= config.parallel_maximum_angle
    )

    planarity_valid = (
        maximum_planarity_rmsd
        <= config.maximum_planarity_rmsd
    )

    reasons: List[str] = []
    warnings: List[str] = []

    geometry = PI_PI_GEOMETRY_REJECTED
    family = PI_PI_FAMILY_REJECTED

    accepted = False
    borderline = False
    offset_valid = False

    base_requirements = (
        centroid_valid
        and angle_valid
        and planarity_valid
        and (
            atomic_valid
            or not config.require_atomic_contact
        )
    )

    if (
        base_requirements
        and plane_angle
        <= config.face_to_face_maximum_angle
        and lateral_offset
        <= config.face_to_face_maximum_offset
    ):
        geometry = PI_PI_GEOMETRY_FACE_TO_FACE
        family = PI_PI_FAMILY_PARALLEL
        accepted = True
        offset_valid = True

        reasons.append(
            "Low interplanar angle and small lateral displacement."
        )

    elif (
        base_requirements
        and lateral_offset
        <= config.parallel_maximum_offset
    ):
        geometry = PI_PI_GEOMETRY_PARALLEL
        family = PI_PI_FAMILY_PARALLEL
        accepted = True
        offset_valid = True

        reasons.append(
            "Parallel aromatic planes with moderate centroid displacement."
        )

    elif (
        base_requirements
        and lateral_offset
        <= config.displaced_maximum_offset
    ):
        geometry = PI_PI_GEOMETRY_DISPLACED
        family = PI_PI_FAMILY_PARALLEL
        accepted = True
        offset_valid = True

        reasons.append(
            "Parallel aromatic planes with pronounced lateral displacement."
        )

    else:
        borderline_requirements = (
            config.allow_borderline_contacts
            and centroid_distance
            <= config.borderline_maximum_centroid_distance
            and minimum_atomic_distance
            <= config.borderline_maximum_atomic_distance
            and lateral_offset
            <= config.borderline_maximum_offset
            and maximum_planarity_rmsd
            <= config.borderline_planarity_rmsd
        )

        if borderline_requirements:
            geometry = PI_PI_GEOMETRY_BORDERLINE
            family = PI_PI_FAMILY_BORDERLINE
            accepted = True
            borderline = True
            offset_valid = True

            reasons.append(
                "Aromatic systems form a limiting contact outside the "
                "canonical parallel-stacking geometry."
            )

        else:
            if not centroid_valid:
                warnings.append(
                    "Centroid distance exceeds the canonical π–π limit."
                )

            if not atomic_valid:
                warnings.append(
                    "Minimum atomic distance exceeds the contact limit."
                )

            if not angle_valid:
                warnings.append(
                    "Plane angle is incompatible with parallel stacking."
                )

            if not planarity_valid:
                warnings.append(
                    "At least one aromatic system has insufficient planarity."
                )

            if lateral_offset > config.displaced_maximum_offset:
                warnings.append(
                    "Lateral displacement exceeds the displaced-stacking "
                    "limit."
                )

    confidence = calculate_pi_pi_geometry_confidence(
        geometry=geometry,
        centroid_distance=centroid_distance,
        plane_angle=plane_angle,
        lateral_offset=lateral_offset,
        minimum_atomic_distance=minimum_atomic_distance,
        maximum_planarity_rmsd=maximum_planarity_rmsd,
        config=config,
    )

    return PiPiGeometryEvaluation(
        geometry=geometry,
        geometry_family=family,
        centroid_distance=centroid_distance,
        plane_angle=plane_angle,
        lateral_offset=lateral_offset,
        lateral_offset_ring_1=lateral_offset,
        lateral_offset_ring_2=lateral_offset,
        minimum_atomic_distance=minimum_atomic_distance,
        ring_1_planarity_rmsd=maximum_planarity_rmsd,
        ring_2_planarity_rmsd=maximum_planarity_rmsd,
        maximum_planarity_rmsd=maximum_planarity_rmsd,
        centroid_distance_valid=centroid_valid,
        atomic_distance_valid=atomic_valid,
        angle_valid=angle_valid,
        offset_valid=offset_valid,
        planarity_valid=planarity_valid,
        accepted=accepted,
        borderline=borderline,
        confidence=confidence,
        reasons=tuple(reasons),
        warnings=tuple(warnings),
    )


# -----------------------------------------------------------------------------
# 8.10. Avaliação T-shaped e edge-to-face
# -----------------------------------------------------------------------------

def evaluate_t_shaped_stacking(
    *,
    centroid_distance: float,
    plane_angle: float,
    lateral_offset: float,
    minimum_atomic_distance: float,
    maximum_planarity_rmsd: float,
    config: Optional[PiPiDetectionConfig] = None,
) -> PiPiGeometryEvaluation:
    """
    Evaluate T-shaped and edge-to-face aromatic geometries.

    T-shaped interactions require a near-perpendicular orientation and a
    centroid projection compatible with one aromatic edge approaching the
    face of the second aromatic system.
    """

    if config is None:
        config = create_default_pi_pi_detection_config()

    centroid_valid = (
        centroid_distance
        <= config.maximum_centroid_distance
    )

    atomic_valid = (
        minimum_atomic_distance
        <= config.maximum_minimum_atomic_distance
    )

    angle_valid = (
        plane_angle
        >= config.t_shaped_minimum_angle
    )

    planarity_valid = (
        maximum_planarity_rmsd
        <= config.maximum_planarity_rmsd
    )

    base_requirements = (
        centroid_valid
        and angle_valid
        and planarity_valid
        and (
            atomic_valid
            or not config.require_atomic_contact
        )
    )

    geometry = PI_PI_GEOMETRY_REJECTED
    family = PI_PI_FAMILY_REJECTED

    accepted = False
    borderline = False
    offset_valid = False

    reasons: List[str] = []
    warnings: List[str] = []

    if (
        base_requirements
        and config.edge_to_face_minimum_offset
        <= lateral_offset
        <= config.t_shaped_maximum_offset
    ):
        geometry = PI_PI_GEOMETRY_T_SHAPED
        family = PI_PI_FAMILY_PERPENDICULAR
        accepted = True
        offset_valid = True

        reasons.append(
            "Near-perpendicular aromatic planes with a canonical "
            "T-shaped centroid displacement."
        )

    elif (
        base_requirements
        and lateral_offset
        <= config.edge_to_face_maximum_offset
    ):
        geometry = PI_PI_GEOMETRY_EDGE_TO_FACE
        family = PI_PI_FAMILY_PERPENDICULAR
        accepted = True
        offset_valid = True

        reasons.append(
            "An aromatic edge approaches the face of the second system."
        )

    else:
        borderline_requirements = (
            config.allow_borderline_contacts
            and centroid_distance
            <= config.borderline_maximum_centroid_distance
            and minimum_atomic_distance
            <= config.borderline_maximum_atomic_distance
            and maximum_planarity_rmsd
            <= config.borderline_planarity_rmsd
            and lateral_offset
            <= config.borderline_maximum_offset
        )

        if borderline_requirements:
            geometry = PI_PI_GEOMETRY_BORDERLINE
            family = PI_PI_FAMILY_BORDERLINE
            accepted = True
            borderline = True
            offset_valid = True

            reasons.append(
                "Near-perpendicular aromatic contact outside the canonical "
                "T-shaped or edge-to-face region."
            )

        else:
            if not centroid_valid:
                warnings.append(
                    "Centroid distance exceeds the canonical π–π limit."
                )

            if not atomic_valid:
                warnings.append(
                    "Minimum atomic distance exceeds the contact limit."
                )

            if not angle_valid:
                warnings.append(
                    "Plane angle is incompatible with perpendicular stacking."
                )

            if not planarity_valid:
                warnings.append(
                    "At least one aromatic system has insufficient planarity."
                )

            if lateral_offset > config.edge_to_face_maximum_offset:
                warnings.append(
                    "Lateral displacement exceeds the edge-to-face limit."
                )

    confidence = calculate_pi_pi_geometry_confidence(
        geometry=geometry,
        centroid_distance=centroid_distance,
        plane_angle=plane_angle,
        lateral_offset=lateral_offset,
        minimum_atomic_distance=minimum_atomic_distance,
        maximum_planarity_rmsd=maximum_planarity_rmsd,
        config=config,
    )

    return PiPiGeometryEvaluation(
        geometry=geometry,
        geometry_family=family,
        centroid_distance=centroid_distance,
        plane_angle=plane_angle,
        lateral_offset=lateral_offset,
        lateral_offset_ring_1=lateral_offset,
        lateral_offset_ring_2=lateral_offset,
        minimum_atomic_distance=minimum_atomic_distance,
        ring_1_planarity_rmsd=maximum_planarity_rmsd,
        ring_2_planarity_rmsd=maximum_planarity_rmsd,
        maximum_planarity_rmsd=maximum_planarity_rmsd,
        centroid_distance_valid=centroid_valid,
        atomic_distance_valid=atomic_valid,
        angle_valid=angle_valid,
        offset_valid=offset_valid,
        planarity_valid=planarity_valid,
        accepted=accepted,
        borderline=borderline,
        confidence=confidence,
        reasons=tuple(reasons),
        warnings=tuple(warnings),
    )


# -----------------------------------------------------------------------------
# 8.11. Classificação conjunta da geometria
# -----------------------------------------------------------------------------

def classify_pi_pi_geometry(
    *,
    centroid_distance: float,
    plane_angle: float,
    lateral_offset: float,
    minimum_atomic_distance: float,
    ring_1_planarity_rmsd: float,
    ring_2_planarity_rmsd: float,
    lateral_offset_ring_1: Optional[float] = None,
    lateral_offset_ring_2: Optional[float] = None,
    config: Optional[PiPiDetectionConfig] = None,
) -> PiPiGeometryEvaluation:
    """
    Classify one aromatic-system pair using all relevant geometric variables.

    The function independently evaluates the parallel and perpendicular
    hypotheses and retains the accepted geometry with the highest geometric
    confidence.
    """

    if config is None:
        config = create_default_pi_pi_detection_config()

    numeric_values = {
        "centroid_distance": centroid_distance,
        "plane_angle": plane_angle,
        "lateral_offset": lateral_offset,
        "minimum_atomic_distance": minimum_atomic_distance,
        "ring_1_planarity_rmsd": ring_1_planarity_rmsd,
        "ring_2_planarity_rmsd": ring_2_planarity_rmsd,
    }

    normalized_values: Dict[str, float] = {}

    for field_name, value in numeric_values.items():
        try:
            normalized_value = float(value)

        except (TypeError, ValueError) as exc:
            raise PiPiValidationError(
                f"{field_name} must be numeric."
            ) from exc

        if not math.isfinite(normalized_value):
            raise PiPiValidationError(
                f"{field_name} must be finite."
            )

        if normalized_value < 0.0:
            raise PiPiValidationError(
                f"{field_name} cannot be negative."
            )

        normalized_values[field_name] = normalized_value

    plane_angle = min(
        90.0,
        normalized_values["plane_angle"],
    )

    maximum_planarity = max(
        normalized_values["ring_1_planarity_rmsd"],
        normalized_values["ring_2_planarity_rmsd"],
    )

    parallel_evaluation = evaluate_parallel_stacking(
        centroid_distance=normalized_values["centroid_distance"],
        plane_angle=plane_angle,
        lateral_offset=normalized_values["lateral_offset"],
        minimum_atomic_distance=normalized_values[
            "minimum_atomic_distance"
        ],
        maximum_planarity_rmsd=maximum_planarity,
        config=config,
    )

    perpendicular_evaluation = evaluate_t_shaped_stacking(
        centroid_distance=normalized_values["centroid_distance"],
        plane_angle=plane_angle,
        lateral_offset=normalized_values["lateral_offset"],
        minimum_atomic_distance=normalized_values[
            "minimum_atomic_distance"
        ],
        maximum_planarity_rmsd=maximum_planarity,
        config=config,
    )

    candidates = (
        parallel_evaluation,
        perpendicular_evaluation,
    )

    accepted_candidates = [
        evaluation
        for evaluation in candidates
        if evaluation.accepted
        and not evaluation.borderline
    ]

    if accepted_candidates:
        selected = max(
            accepted_candidates,
            key=lambda evaluation: (
                evaluation.confidence,
                evaluation.geometry
                == PI_PI_GEOMETRY_FACE_TO_FACE,
                evaluation.geometry
                == PI_PI_GEOMETRY_T_SHAPED,
            ),
        )

    else:
        borderline_candidates = [
            evaluation
            for evaluation in candidates
            if evaluation.accepted
            and evaluation.borderline
        ]

        if borderline_candidates:
            selected = max(
                borderline_candidates,
                key=lambda evaluation: evaluation.confidence,
            )

        else:
            selected = max(
                candidates,
                key=lambda evaluation: evaluation.confidence,
            )

    selected.ring_1_planarity_rmsd = normalized_values[
        "ring_1_planarity_rmsd"
    ]

    selected.ring_2_planarity_rmsd = normalized_values[
        "ring_2_planarity_rmsd"
    ]

    selected.maximum_planarity_rmsd = maximum_planarity

    selected.lateral_offset_ring_1 = (
        normalized_values["lateral_offset"]
        if lateral_offset_ring_1 is None
        else float(lateral_offset_ring_1)
    )

    selected.lateral_offset_ring_2 = (
        normalized_values["lateral_offset"]
        if lateral_offset_ring_2 is None
        else float(lateral_offset_ring_2)
    )

    selected.metadata.update(
        {
            "parallel_evaluation": parallel_evaluation.to_dict(),
            "perpendicular_evaluation": perpendicular_evaluation.to_dict(),
            "selection_rule": "highest_accepted_geometric_confidence",
        }
    )

    return selected


# -----------------------------------------------------------------------------
# 8.12. Avaliação completa de dois sistemas aromáticos
# -----------------------------------------------------------------------------

def evaluate_pi_pi_ring_pair(
    ring_1: Any,
    ring_2: Any,
    *,
    config: Optional[PiPiDetectionConfig] = None,
) -> PiPiGeometryEvaluation:
    """
    Calculate and classify the complete geometry of two aromatic systems.
    """

    if config is None:
        config = create_default_pi_pi_detection_config()

    atoms_1 = _pi_pi_get_ring_atoms(ring_1)
    atoms_2 = _pi_pi_get_ring_atoms(ring_2)

    if not (
        config.minimum_ring_atom_count
        <= len(atoms_1)
        <= config.maximum_ring_atom_count
    ):
        raise PiPiGeometryError(
            "The first aromatic system has an unsupported atom count: "
            f"{len(atoms_1)}."
        )

    if not (
        config.minimum_ring_atom_count
        <= len(atoms_2)
        <= config.maximum_ring_atom_count
    ):
        raise PiPiGeometryError(
            "The second aromatic system has an unsupported atom count: "
            f"{len(atoms_2)}."
        )

    centroid_1 = _pi_pi_get_ring_centroid(
        ring_1
    )

    centroid_2 = _pi_pi_get_ring_centroid(
        ring_2
    )

    normal_1 = _pi_pi_get_ring_normal(
        ring_1
    )

    normal_2 = _pi_pi_get_ring_normal(
        ring_2
    )

    centroid_distance = _pi_pi_distance(
        centroid_1,
        centroid_2,
    )

    plane_angle = _pi_pi_plane_angle(
        normal_1,
        normal_2,
    )

    (
        offset_ring_1,
        offset_ring_2,
        symmetric_offset,
    ) = _pi_pi_lateral_offsets(
        centroid_1,
        centroid_2,
        normal_1,
        normal_2,
    )

    minimum_atomic_distance = (
        calculate_pi_pi_minimum_atomic_distance(
            ring_1,
            ring_2,
        )
    )

    planarity_1 = _pi_pi_get_ring_planarity(
        ring_1
    )

    planarity_2 = _pi_pi_get_ring_planarity(
        ring_2
    )

    evaluation = classify_pi_pi_geometry(
        centroid_distance=centroid_distance,
        plane_angle=plane_angle,
        lateral_offset=symmetric_offset,
        lateral_offset_ring_1=offset_ring_1,
        lateral_offset_ring_2=offset_ring_2,
        minimum_atomic_distance=minimum_atomic_distance,
        ring_1_planarity_rmsd=planarity_1,
        ring_2_planarity_rmsd=planarity_2,
        config=config,
    )

    evaluation.metadata.update(
        {
            "ring_1_id": _pi_pi_get_ring_id(
                ring_1,
                "ring_1",
            ),
            "ring_2_id": _pi_pi_get_ring_id(
                ring_2,
                "ring_2",
            ),
            "ring_1_centroid": centroid_1,
            "ring_2_centroid": centroid_2,
            "ring_1_normal": normal_1,
            "ring_2_normal": normal_2,
        }
    )

    return evaluation


# -----------------------------------------------------------------------------
# 8.13. Construção da interação
# -----------------------------------------------------------------------------

def _pi_pi_construct_interaction(
    ring_1: Any,
    ring_2: Any,
    evaluation: PiPiGeometryEvaluation,
    *,
    interaction_index: int,
    config: PiPiDetectionConfig,
) -> Any:
    """
    Construct a canonical PiInteraction from a geometric evaluation.
    """

    ring_1_id = _pi_pi_get_ring_id(
        ring_1,
        f"ring_1_{interaction_index}",
    )

    ring_2_id = _pi_pi_get_ring_id(
        ring_2,
        f"ring_2_{interaction_index}",
    )

    interaction_id = (
        f"pi-pi:"
        f"{ring_1_id}:"
        f"{ring_2_id}"
    )

    atomic_contacts: Tuple[Any, ...] = ()

    if config.include_atomic_contacts:
        atomic_contacts = find_pi_pi_atomic_contacts(
            ring_1,
            ring_2,
            maximum_distance=config.atomic_contact_distance,
        )

    residue_1_id = _pi_pi_get_ring_residue_id(
        ring_1
    )

    residue_2_id = _pi_pi_get_ring_residue_id(
        ring_2
    )

    candidate_values: Dict[str, Any] = {
        "interaction_id": interaction_id,
        "id": interaction_id,
        "interaction_type": PI_PI_INTERACTION_TYPE,
        "subtype": evaluation.geometry,
        "geometry_class": evaluation.geometry,
        "geometry_family": evaluation.geometry_family,
        "ring_1": ring_1,
        "ring_2": ring_2,
        "aromatic_system_1": ring_1,
        "aromatic_system_2": ring_2,
        "participant_1_type": _pi_pi_get_ring_participant_type(
            ring_1
        ),
        "participant_2_type": _pi_pi_get_ring_participant_type(
            ring_2
        ),
        "centroid_distance": evaluation.centroid_distance,
        "plane_angle": evaluation.plane_angle,
        "normal_angle": evaluation.plane_angle,
        "lateral_offset": evaluation.lateral_offset,
        "lateral_offset_ring_1": evaluation.lateral_offset_ring_1,
        "lateral_offset_ring_2": evaluation.lateral_offset_ring_2,
        "minimum_atomic_distance": evaluation.minimum_atomic_distance,
        "ring_1_planarity": evaluation.ring_1_planarity_rmsd,
        "ring_2_planarity": evaluation.ring_2_planarity_rmsd,
        "planarity_quality": (
            1.0
            - min(
                1.0,
                evaluation.maximum_planarity_rmsd
                / max(
                    config.borderline_planarity_rmsd,
                    PI_PI_EPSILON,
                ),
            )
        ),
        "geometry_confidence": evaluation.confidence,
        "atomic_contacts": atomic_contacts,
        "valid": evaluation.accepted,
        "borderline": evaluation.borderline,
        "warnings": list(evaluation.warnings),
        "metadata": {
            "schema": "pi-pi-interaction",
            "geometry_reasons": list(evaluation.reasons),
            "geometry_evaluation": evaluation.to_dict(),
            "ring_1_id": ring_1_id,
            "ring_2_id": ring_2_id,
            "residue_1_id": residue_1_id,
            "residue_2_id": residue_2_id,
            "atomic_contact_count": len(atomic_contacts),
        },
    }

    if is_dataclass(PiInteraction):
        supported_fields = {
            field_definition.name
            for field_definition in fields(PiInteraction)
        }

        candidate_values = {
            key: value
            for key, value in candidate_values.items()
            if key in supported_fields
        }

    try:
        return PiInteraction(
            **candidate_values
        )

    except TypeError as exc:
        raise PiPiDetectionError(
            "Could not construct PiInteraction. Ensure that the dataclass "
            "defined in Section 2 contains the fields required by the "
            "π-interaction architecture."
        ) from exc


# -----------------------------------------------------------------------------
# 8.14. Validação de pares
# -----------------------------------------------------------------------------

def _pi_pi_same_aromatic_system(
    ring_1: Any,
    ring_2: Any,
) -> bool:
    if ring_1 is ring_2:
        return True

    ring_1_id = _pi_pi_get_ring_id(
        ring_1,
        "",
    )

    ring_2_id = _pi_pi_get_ring_id(
        ring_2,
        "",
    )

    return bool(
        ring_1_id
        and ring_2_id
        and ring_1_id == ring_2_id
    )


def _pi_pi_same_residue(
    ring_1: Any,
    ring_2: Any,
) -> bool:
    residue_1 = _pi_pi_get_ring_residue_id(
        ring_1
    )

    residue_2 = _pi_pi_get_ring_residue_id(
        ring_2
    )

    return bool(
        residue_1
        and residue_2
        and residue_1 == residue_2
    )


def _pi_pi_pair_key(
    ring_1: Any,
    ring_2: Any,
) -> Tuple[str, str]:
    identifier_1 = _pi_pi_get_ring_id(
        ring_1,
        str(id(ring_1)),
    )

    identifier_2 = _pi_pi_get_ring_id(
        ring_2,
        str(id(ring_2)),
    )

    return tuple(
        sorted(
            (
                identifier_1,
                identifier_2,
            )
        )
    )


# -----------------------------------------------------------------------------
# 8.15. Detecção principal
# -----------------------------------------------------------------------------

def detect_pi_pi_interactions(
    aromatic_systems_1: Iterable[Any],
    aromatic_systems_2: Optional[Iterable[Any]] = None,
    *,
    config: Optional[PiPiDetectionConfig] = None,
    exclude_same_system: bool = True,
    exclude_same_residue: bool = True,
    cross_collection_only: bool = True,
    strict: bool = False,
) -> List[Any]:
    """
    Detect π–π interactions between aromatic systems.

    Parameters
    ----------
    aromatic_systems_1:
        First collection of aromatic systems, usually receptor rings.
    aromatic_systems_2:
        Second collection, usually ligand rings. When omitted, all unique
        combinations from `aromatic_systems_1` are evaluated.
    config:
        π–π detection thresholds.
    exclude_same_system:
        Ignore comparisons of a system with itself.
    exclude_same_residue:
        Ignore interactions between aromatic systems assigned to the same
        residue. This is useful for fused systems represented by multiple
        component rings.
    cross_collection_only:
        When two collections are supplied, only intercollection pairs are
        generated.
    strict:
        Raise geometry errors immediately. When False, malformed pairs are
        skipped.
    """

    if config is None:
        config = create_default_pi_pi_detection_config()

    systems_1 = tuple(aromatic_systems_1)

    if aromatic_systems_2 is None:
        systems_2 = systems_1
        same_collection = True

    else:
        systems_2 = tuple(aromatic_systems_2)
        same_collection = False

    interactions: List[Any] = []
    evaluated_pairs: Set[Tuple[str, str]] = set()

    if same_collection:
        pair_iterator = (
            (systems_1[index_1], systems_1[index_2])
            for index_1 in range(len(systems_1))
            for index_2 in range(index_1 + 1, len(systems_1))
        )

    else:
        pair_iterator = (
            (ring_1, ring_2)
            for ring_1 in systems_1
            for ring_2 in systems_2
        )

    for ring_1, ring_2 in pair_iterator:
        if exclude_same_system and _pi_pi_same_aromatic_system(
            ring_1,
            ring_2,
        ):
            continue

        if exclude_same_residue and _pi_pi_same_residue(
            ring_1,
            ring_2,
        ):
            continue

        pair_key = _pi_pi_pair_key(
            ring_1,
            ring_2,
        )

        if (
            config.deduplicate_results
            and pair_key in evaluated_pairs
        ):
            continue

        evaluated_pairs.add(
            pair_key
        )

        try:
            evaluation = evaluate_pi_pi_ring_pair(
                ring_1,
                ring_2,
                config=config,
            )

        except (
            PiPiGeometryError,
            PiPiValidationError,
            TypeError,
            ValueError,
        ):
            if strict:
                raise

            continue

        if (
            not evaluation.accepted
            and not config.include_rejected
        ):
            continue

        interaction = _pi_pi_construct_interaction(
            ring_1,
            ring_2,
            evaluation,
            interaction_index=len(interactions) + 1,
            config=config,
        )

        interactions.append(
            interaction
        )

    interactions.sort(
        key=lambda interaction: (
            not bool(
                _pi_pi_get_first_attribute(
                    interaction,
                    ("valid",),
                    False,
                )
            ),
            -float(
                _pi_pi_get_first_attribute(
                    interaction,
                    (
                        "geometry_confidence",
                        "confidence",
                    ),
                    0.0,
                )
            ),
            float(
                _pi_pi_get_first_attribute(
                    interaction,
                    ("centroid_distance",),
                    math.inf,
                )
            ),
            str(
                _pi_pi_get_first_attribute(
                    interaction,
                    (
                        "interaction_id",
                        "id",
                    ),
                    "",
                )
            ),
        )
    )

    return interactions


# -----------------------------------------------------------------------------
# 8.16. API auxiliar para uma única dupla
# -----------------------------------------------------------------------------

def detect_single_pi_pi_interaction(
    ring_1: Any,
    ring_2: Any,
    *,
    config: Optional[PiPiDetectionConfig] = None,
    include_rejected: bool = False,
) -> Optional[Any]:
    """
    Detect one π–π interaction between two aromatic systems.
    """

    if config is None:
        config = create_default_pi_pi_detection_config()

    evaluation = evaluate_pi_pi_ring_pair(
        ring_1,
        ring_2,
        config=config,
    )

    if (
        not evaluation.accepted
        and not include_rejected
    ):
        return None

    return _pi_pi_construct_interaction(
        ring_1,
        ring_2,
        evaluation,
        interaction_index=1,
        config=config,
    )


# -----------------------------------------------------------------------------
# 8.17. Filtros e resumos locais
# -----------------------------------------------------------------------------

def filter_pi_pi_interactions_by_geometry(
    interactions: Iterable[Any],
    geometries: Collection[str],
) -> List[Any]:
    """
    Select π–π interactions matching one or more geometric subtypes.
    """

    normalized_geometries = {
        str(geometry).strip().lower()
        for geometry in geometries
    }

    unsupported = (
        normalized_geometries
        - SUPPORTED_PI_PI_GEOMETRIES
    )

    if unsupported:
        raise PiPiValidationError(
            "Unsupported π–π geometries: "
            f"{sorted(unsupported)!r}."
        )

    return [
        interaction
        for interaction in interactions
        if str(
            _pi_pi_get_first_attribute(
                interaction,
                (
                    "geometry_class",
                    "subtype",
                ),
                "",
            )
        ).strip().lower()
        in normalized_geometries
    ]


def summarize_pi_pi_detection(
    interactions: Iterable[Any],
) -> Dict[str, Any]:
    """
    Produce a lightweight summary specific to Section 8.

    Full statistics are generated later in Section 13.
    """

    interaction_list = list(
        interactions
    )

    geometry_distribution: Dict[str, int] = defaultdict(int)

    centroid_distances: List[float] = []
    atomic_distances: List[float] = []
    plane_angles: List[float] = []
    lateral_offsets: List[float] = []

    borderline_count = 0

    for interaction in interaction_list:
        geometry = str(
            _pi_pi_get_first_attribute(
                interaction,
                (
                    "geometry_class",
                    "subtype",
                ),
                PI_PI_GEOMETRY_REJECTED,
            )
        )

        geometry_distribution[
            geometry
        ] += 1

        if bool(
            _pi_pi_get_first_attribute(
                interaction,
                ("borderline",),
                False,
            )
        ):
            borderline_count += 1

        for collection, attribute_names in (
            (
                centroid_distances,
                ("centroid_distance",),
            ),
            (
                atomic_distances,
                ("minimum_atomic_distance",),
            ),
            (
                plane_angles,
                ("plane_angle", "normal_angle"),
            ),
            (
                lateral_offsets,
                ("lateral_offset",),
            ),
        ):
            value = _pi_pi_get_first_attribute(
                interaction,
                attribute_names,
            )

            if value is None:
                continue

            try:
                normalized_value = float(value)

            except (TypeError, ValueError):
                continue

            if math.isfinite(normalized_value):
                collection.append(
                    normalized_value
                )

    def numeric_summary(
        values: Sequence[float],
    ) -> Dict[str, Optional[float]]:
        if not values:
            return {
                "mean": None,
                "minimum": None,
                "maximum": None,
            }

        return {
            "mean": sum(values) / len(values),
            "minimum": min(values),
            "maximum": max(values),
        }

    return {
        "total_interactions": len(interaction_list),
        "geometry_distribution": dict(
            sorted(
                geometry_distribution.items()
            )
        ),
        "borderline_interactions": borderline_count,
        "centroid_distance": numeric_summary(
            centroid_distances
        ),
        "minimum_atomic_distance": numeric_summary(
            atomic_distances
        ),
        "plane_angle": numeric_summary(
            plane_angles
        ),
        "lateral_offset": numeric_summary(
            lateral_offsets
        ),
    }


# =============================================================================
# 9. DETECÇÃO DE INTERAÇÕES CÁTION–π
# =============================================================================

# -----------------------------------------------------------------------------
# 9.1. Constantes
# -----------------------------------------------------------------------------

CATION_PI_INTERACTION_TYPE: Final[str] = "cation-pi"

CATION_PI_GEOMETRY_FACE_CENTERED: Final[str] = "face-centered"
CATION_PI_GEOMETRY_FACE_OFFSET: Final[str] = "face-offset"
CATION_PI_GEOMETRY_EDGE_ASSOCIATED: Final[str] = "edge-associated"
CATION_PI_GEOMETRY_BORDERLINE: Final[str] = "borderline-cation-pi"
CATION_PI_GEOMETRY_REJECTED: Final[str] = "rejected"

SUPPORTED_CATION_PI_GEOMETRIES: Final[FrozenSet[str]] = frozenset(
    {
        CATION_PI_GEOMETRY_FACE_CENTERED,
        CATION_PI_GEOMETRY_FACE_OFFSET,
        CATION_PI_GEOMETRY_EDGE_ASSOCIATED,
        CATION_PI_GEOMETRY_BORDERLINE,
        CATION_PI_GEOMETRY_REJECTED,
    }
)

CATION_PI_FACE_POSITIVE: Final[str] = "positive-normal-face"
CATION_PI_FACE_NEGATIVE: Final[str] = "negative-normal-face"
CATION_PI_FACE_IN_PLANE: Final[str] = "approximately-in-plane"

SUPPORTED_CATION_PI_FACES: Final[FrozenSet[str]] = frozenset(
    {
        CATION_PI_FACE_POSITIVE,
        CATION_PI_FACE_NEGATIVE,
        CATION_PI_FACE_IN_PLANE,
    }
)

CATION_PI_CHARGE_SOURCE_FORMAL: Final[str] = "formal"
CATION_PI_CHARGE_SOURCE_PARTIAL: Final[str] = "partial"
CATION_PI_CHARGE_SOURCE_INFERRED: Final[str] = "inferred"
CATION_PI_CHARGE_SOURCE_GROUP: Final[str] = "group"
CATION_PI_CHARGE_SOURCE_UNKNOWN: Final[str] = "unknown"

SUPPORTED_CATION_PI_CHARGE_SOURCES: Final[FrozenSet[str]] = frozenset(
    {
        CATION_PI_CHARGE_SOURCE_FORMAL,
        CATION_PI_CHARGE_SOURCE_PARTIAL,
        CATION_PI_CHARGE_SOURCE_INFERRED,
        CATION_PI_CHARGE_SOURCE_GROUP,
        CATION_PI_CHARGE_SOURCE_UNKNOWN,
    }
)

CATION_PI_DEFAULT_OPTIMAL_CENTROID_DISTANCE: Final[float] = 4.5
CATION_PI_DEFAULT_MAXIMUM_CENTROID_DISTANCE: Final[float] = 6.0
CATION_PI_DEFAULT_BORDERLINE_CENTROID_DISTANCE: Final[float] = 7.0

CATION_PI_DEFAULT_MINIMUM_HEIGHT: Final[float] = 1.5
CATION_PI_DEFAULT_OPTIMAL_HEIGHT: Final[float] = 3.5
CATION_PI_DEFAULT_MAXIMUM_HEIGHT: Final[float] = 5.5
CATION_PI_DEFAULT_BORDERLINE_HEIGHT: Final[float] = 6.5

CATION_PI_DEFAULT_CENTERED_RADIAL_OFFSET: Final[float] = 1.5
CATION_PI_DEFAULT_OFFSET_RADIAL_LIMIT: Final[float] = 2.8
CATION_PI_DEFAULT_EDGE_RADIAL_LIMIT: Final[float] = 4.0
CATION_PI_DEFAULT_BORDERLINE_RADIAL_LIMIT: Final[float] = 4.8

CATION_PI_DEFAULT_ATOMIC_CONTACT_DISTANCE: Final[float] = 4.5
CATION_PI_DEFAULT_MAXIMUM_ATOMIC_DISTANCE: Final[float] = 5.0

CATION_PI_DEFAULT_MINIMUM_POSITIVE_CHARGE: Final[float] = 0.25
CATION_PI_DEFAULT_STRONG_POSITIVE_CHARGE: Final[float] = 0.75

CATION_PI_DEFAULT_MAXIMUM_PLANARITY_RMSD: Final[float] = 0.20
CATION_PI_DEFAULT_BORDERLINE_PLANARITY_RMSD: Final[float] = 0.35

CATION_PI_EPSILON: Final[float] = 1.0e-12


# -----------------------------------------------------------------------------
# 9.2. Exceções
# -----------------------------------------------------------------------------

class CationPiDetectionError(RuntimeError):
    """
    Base exception for cation–π interaction detection.
    """


class CationPiGeometryError(CationPiDetectionError):
    """
    Raised when geometric data are absent or invalid.
    """


class CationPiValidationError(CationPiDetectionError):
    """
    Raised when cation–π input or configuration is invalid.
    """


# -----------------------------------------------------------------------------
# 9.3. Configuração
# -----------------------------------------------------------------------------

@dataclass(slots=True)
class CationPiDetectionConfig:
    """
    Geometric and chemical thresholds for cation–π detection.
    """

    # Charge–centroid distance
    optimal_centroid_distance: float = (
        CATION_PI_DEFAULT_OPTIMAL_CENTROID_DISTANCE
    )

    maximum_centroid_distance: float = (
        CATION_PI_DEFAULT_MAXIMUM_CENTROID_DISTANCE
    )

    borderline_maximum_centroid_distance: float = (
        CATION_PI_DEFAULT_BORDERLINE_CENTROID_DISTANCE
    )

    # Perpendicular height above the aromatic plane
    minimum_height: float = CATION_PI_DEFAULT_MINIMUM_HEIGHT
    optimal_height: float = CATION_PI_DEFAULT_OPTIMAL_HEIGHT
    maximum_height: float = CATION_PI_DEFAULT_MAXIMUM_HEIGHT

    borderline_maximum_height: float = (
        CATION_PI_DEFAULT_BORDERLINE_HEIGHT
    )

    # Radial displacement from the ring center
    centered_maximum_radial_offset: float = (
        CATION_PI_DEFAULT_CENTERED_RADIAL_OFFSET
    )

    offset_maximum_radial_offset: float = (
        CATION_PI_DEFAULT_OFFSET_RADIAL_LIMIT
    )

    edge_maximum_radial_offset: float = (
        CATION_PI_DEFAULT_EDGE_RADIAL_LIMIT
    )

    borderline_maximum_radial_offset: float = (
        CATION_PI_DEFAULT_BORDERLINE_RADIAL_LIMIT
    )

    # Atomic distances
    atomic_contact_distance: float = (
        CATION_PI_DEFAULT_ATOMIC_CONTACT_DISTANCE
    )

    maximum_minimum_atomic_distance: float = (
        CATION_PI_DEFAULT_MAXIMUM_ATOMIC_DISTANCE
    )

    # Charge
    minimum_positive_charge: float = (
        CATION_PI_DEFAULT_MINIMUM_POSITIVE_CHARGE
    )

    strong_positive_charge: float = (
        CATION_PI_DEFAULT_STRONG_POSITIVE_CHARGE
    )

    allow_inferred_charge: bool = True
    allow_partial_charge: bool = True
    require_positive_charge: bool = True

    # Planarity
    maximum_planarity_rmsd: float = (
        CATION_PI_DEFAULT_MAXIMUM_PLANARITY_RMSD
    )

    borderline_planarity_rmsd: float = (
        CATION_PI_DEFAULT_BORDERLINE_PLANARITY_RMSD
    )

    # Orientation
    use_group_orientation: bool = True
    favorable_orientation_maximum_angle: float = 45.0
    acceptable_orientation_maximum_angle: float = 75.0
    orientation_weight: float = 0.10

    # Detection behavior
    require_atomic_contact: bool = False
    include_atomic_contacts: bool = True
    include_borderline: bool = True
    include_rejected: bool = False
    deduplicate_results: bool = True

    exclude_intramolecular_same_residue: bool = True

    numeric_tolerance: float = 1.0e-8

    def __post_init__(self) -> None:
        numeric_fields = (
            "optimal_centroid_distance",
            "maximum_centroid_distance",
            "borderline_maximum_centroid_distance",
            "minimum_height",
            "optimal_height",
            "maximum_height",
            "borderline_maximum_height",
            "centered_maximum_radial_offset",
            "offset_maximum_radial_offset",
            "edge_maximum_radial_offset",
            "borderline_maximum_radial_offset",
            "atomic_contact_distance",
            "maximum_minimum_atomic_distance",
            "minimum_positive_charge",
            "strong_positive_charge",
            "maximum_planarity_rmsd",
            "borderline_planarity_rmsd",
            "favorable_orientation_maximum_angle",
            "acceptable_orientation_maximum_angle",
            "orientation_weight",
            "numeric_tolerance",
        )

        for field_name in numeric_fields:
            value = getattr(self, field_name)

            try:
                normalized_value = float(value)

            except (TypeError, ValueError) as exc:
                raise CationPiValidationError(
                    f"{field_name} must be numeric."
                ) from exc

            if not math.isfinite(normalized_value):
                raise CationPiValidationError(
                    f"{field_name} must be finite."
                )

            if normalized_value < 0.0:
                raise CationPiValidationError(
                    f"{field_name} cannot be negative."
                )

            setattr(
                self,
                field_name,
                normalized_value,
            )

        if (
            self.optimal_centroid_distance
            > self.maximum_centroid_distance
        ):
            raise CationPiValidationError(
                "optimal_centroid_distance cannot exceed "
                "maximum_centroid_distance."
            )

        if (
            self.maximum_centroid_distance
            > self.borderline_maximum_centroid_distance
        ):
            raise CationPiValidationError(
                "maximum_centroid_distance cannot exceed "
                "borderline_maximum_centroid_distance."
            )

        if self.minimum_height > self.optimal_height:
            raise CationPiValidationError(
                "minimum_height cannot exceed optimal_height."
            )

        if self.optimal_height > self.maximum_height:
            raise CationPiValidationError(
                "optimal_height cannot exceed maximum_height."
            )

        if self.maximum_height > self.borderline_maximum_height:
            raise CationPiValidationError(
                "maximum_height cannot exceed "
                "borderline_maximum_height."
            )

        radial_limits = (
            self.centered_maximum_radial_offset,
            self.offset_maximum_radial_offset,
            self.edge_maximum_radial_offset,
            self.borderline_maximum_radial_offset,
        )

        if tuple(sorted(radial_limits)) != radial_limits:
            raise CationPiValidationError(
                "Radial-offset limits must be monotonically increasing."
            )

        if (
            self.atomic_contact_distance
            > self.maximum_minimum_atomic_distance
        ):
            raise CationPiValidationError(
                "atomic_contact_distance cannot exceed "
                "maximum_minimum_atomic_distance."
            )

        if (
            self.minimum_positive_charge
            > self.strong_positive_charge
        ):
            raise CationPiValidationError(
                "minimum_positive_charge cannot exceed "
                "strong_positive_charge."
            )

        if (
            self.maximum_planarity_rmsd
            > self.borderline_planarity_rmsd
        ):
            raise CationPiValidationError(
                "maximum_planarity_rmsd cannot exceed "
                "borderline_planarity_rmsd."
            )

        if (
            self.favorable_orientation_maximum_angle
            > self.acceptable_orientation_maximum_angle
        ):
            raise CationPiValidationError(
                "favorable_orientation_maximum_angle cannot exceed "
                "acceptable_orientation_maximum_angle."
            )

        if self.acceptable_orientation_maximum_angle > 90.0:
            raise CationPiValidationError(
                "acceptable_orientation_maximum_angle cannot exceed "
                "90 degrees."
            )

        if self.orientation_weight > 1.0:
            raise CationPiValidationError(
                "orientation_weight cannot exceed 1.0."
            )


def create_default_cation_pi_detection_config() -> CationPiDetectionConfig:
    """
    Return the canonical cation–π detection configuration.
    """

    return CationPiDetectionConfig()


# -----------------------------------------------------------------------------
# 9.4. Resultado da avaliação
# -----------------------------------------------------------------------------

@dataclass(slots=True)
class CationPiGeometryEvaluation:
    """
    Complete geometric and chemical evaluation of one cation–ring pair.
    """

    geometry: str

    centroid_distance: float
    signed_height: float
    absolute_height: float
    radial_offset: float
    minimum_atomic_distance: float

    face: str

    effective_charge: float
    charge_source: str
    charge_valid: bool
    strongly_charged: bool

    orientation_angle: Optional[float]
    orientation_valid: Optional[bool]
    orientation_available: bool

    ring_planarity_rmsd: float

    centroid_distance_valid: bool
    height_valid: bool
    radial_offset_valid: bool
    atomic_distance_valid: bool
    planarity_valid: bool

    accepted: bool
    borderline: bool = False

    confidence: float = 0.0

    reasons: Tuple[str, ...] = ()
    warnings: Tuple[str, ...] = ()

    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if self.geometry not in SUPPORTED_CATION_PI_GEOMETRIES:
            raise CationPiValidationError(
                f"Unsupported cation–π geometry: {self.geometry!r}."
            )

        if self.face not in SUPPORTED_CATION_PI_FACES:
            raise CationPiValidationError(
                f"Unsupported aromatic face: {self.face!r}."
            )

        if self.charge_source not in SUPPORTED_CATION_PI_CHARGE_SOURCES:
            raise CationPiValidationError(
                f"Unsupported charge source: {self.charge_source!r}."
            )

        self.confidence = max(
            0.0,
            min(1.0, float(self.confidence)),
        )

        self.reasons = tuple(
            str(reason)
            for reason in self.reasons
        )

        self.warnings = tuple(
            str(warning)
            for warning in self.warnings
        )

    def to_dict(self) -> Dict[str, Any]:
        return {
            "geometry": self.geometry,
            "centroid_distance": self.centroid_distance,
            "signed_height": self.signed_height,
            "absolute_height": self.absolute_height,
            "radial_offset": self.radial_offset,
            "minimum_atomic_distance": self.minimum_atomic_distance,
            "face": self.face,
            "effective_charge": self.effective_charge,
            "charge_source": self.charge_source,
            "charge_valid": self.charge_valid,
            "strongly_charged": self.strongly_charged,
            "orientation_angle": self.orientation_angle,
            "orientation_valid": self.orientation_valid,
            "orientation_available": self.orientation_available,
            "ring_planarity_rmsd": self.ring_planarity_rmsd,
            "centroid_distance_valid": self.centroid_distance_valid,
            "height_valid": self.height_valid,
            "radial_offset_valid": self.radial_offset_valid,
            "atomic_distance_valid": self.atomic_distance_valid,
            "planarity_valid": self.planarity_valid,
            "accepted": self.accepted,
            "borderline": self.borderline,
            "confidence": self.confidence,
            "reasons": list(self.reasons),
            "warnings": list(self.warnings),
            "metadata": dict(self.metadata),
        }


# -----------------------------------------------------------------------------
# 9.5. Acesso seguro
# -----------------------------------------------------------------------------

def _cation_pi_get_first_attribute(
    object_: Any,
    names: Sequence[str],
    default: Any = None,
) -> Any:
    """
    Return the first existing non-None attribute or mapping value.
    """

    if object_ is None:
        return default

    for name in names:
        if isinstance(object_, Mapping):
            value = object_.get(name)

        else:
            value = getattr(object_, name, None)

        if value is not None:
            return value

    return default


def _cation_pi_as_vector3(
    value: Any,
    *,
    field_name: str,
) -> Tuple[float, float, float]:
    """
    Normalize a coordinate-like value.
    """

    if value is None:
        raise CationPiGeometryError(
            f"Missing {field_name}."
        )

    try:
        vector = tuple(
            float(component)
            for component in value
        )

    except (TypeError, ValueError) as exc:
        raise CationPiGeometryError(
            f"{field_name} must contain numeric values."
        ) from exc

    if len(vector) != 3:
        raise CationPiGeometryError(
            f"{field_name} must contain exactly three values."
        )

    if not all(math.isfinite(component) for component in vector):
        raise CationPiGeometryError(
            f"{field_name} must contain finite values."
        )

    return vector


def _cation_pi_vector_subtract(
    vector_1: Sequence[float],
    vector_2: Sequence[float],
) -> Tuple[float, float, float]:
    return (
        float(vector_1[0]) - float(vector_2[0]),
        float(vector_1[1]) - float(vector_2[1]),
        float(vector_1[2]) - float(vector_2[2]),
    )


def _cation_pi_dot(
    vector_1: Sequence[float],
    vector_2: Sequence[float],
) -> float:
    return (
        float(vector_1[0]) * float(vector_2[0])
        + float(vector_1[1]) * float(vector_2[1])
        + float(vector_1[2]) * float(vector_2[2])
    )


def _cation_pi_norm(
    vector: Sequence[float],
) -> float:
    return math.sqrt(
        _cation_pi_dot(
            vector,
            vector,
        )
    )


def _cation_pi_normalize_vector(
    vector: Sequence[float],
) -> Tuple[float, float, float]:
    magnitude = _cation_pi_norm(vector)

    if magnitude <= CATION_PI_EPSILON:
        raise CationPiGeometryError(
            "Cannot normalize a zero-length vector."
        )

    return (
        float(vector[0]) / magnitude,
        float(vector[1]) / magnitude,
        float(vector[2]) / magnitude,
    )


def _cation_pi_distance(
    point_1: Sequence[float],
    point_2: Sequence[float],
) -> float:
    return _cation_pi_norm(
        _cation_pi_vector_subtract(
            point_1,
            point_2,
        )
    )


def _cation_pi_get_ring_centroid(
    ring: Any,
) -> Tuple[float, float, float]:
    value = _cation_pi_get_first_attribute(
        ring,
        (
            "centroid",
            "center",
            "centre",
            "geometric_center",
        ),
    )

    return _cation_pi_as_vector3(
        value,
        field_name="aromatic-system centroid",
    )


def _cation_pi_get_ring_normal(
    ring: Any,
) -> Tuple[float, float, float]:
    value = _cation_pi_get_first_attribute(
        ring,
        (
            "normal",
            "plane_normal",
            "normal_vector",
            "unit_normal",
        ),
    )

    return _cation_pi_normalize_vector(
        _cation_pi_as_vector3(
            value,
            field_name="aromatic-system normal",
        )
    )


def _cation_pi_get_ring_planarity(
    ring: Any,
) -> float:
    value = _cation_pi_get_first_attribute(
        ring,
        (
            "planarity_rmsd",
            "plane_rmsd",
            "rmsd_to_plane",
            "planarity",
        ),
        0.0,
    )

    try:
        planarity = float(value)

    except (TypeError, ValueError) as exc:
        raise CationPiGeometryError(
            "Aromatic-system planarity must be numeric."
        ) from exc

    if not math.isfinite(planarity):
        raise CationPiGeometryError(
            "Aromatic-system planarity must be finite."
        )

    return max(0.0, planarity)


def _cation_pi_get_ring_atoms(
    ring: Any,
) -> Tuple[Any, ...]:
    atoms = _cation_pi_get_first_attribute(
        ring,
        (
            "atoms",
            "atom_references",
            "ring_atoms",
        ),
        (),
    )

    try:
        return tuple(atoms)

    except TypeError as exc:
        raise CationPiGeometryError(
            "Aromatic-system atoms must be iterable."
        ) from exc


def _cation_pi_get_atom_coordinates(
    atom: Any,
) -> Tuple[float, float, float]:
    coordinates = _cation_pi_get_first_attribute(
        atom,
        (
            "coordinates",
            "coordinate",
            "coords",
            "position",
        ),
    )

    if coordinates is None:
        x = _cation_pi_get_first_attribute(atom, ("x",))
        y = _cation_pi_get_first_attribute(atom, ("y",))
        z = _cation_pi_get_first_attribute(atom, ("z",))

        if x is not None and y is not None and z is not None:
            coordinates = (x, y, z)

    return _cation_pi_as_vector3(
        coordinates,
        field_name="atom coordinates",
    )


def _cation_pi_get_group_atoms(
    charged_group: Any,
) -> Tuple[Any, ...]:
    atoms = _cation_pi_get_first_attribute(
        charged_group,
        (
            "atoms",
            "atom_references",
            "group_atoms",
            "charged_atoms",
        ),
        (),
    )

    try:
        return tuple(atoms)

    except TypeError as exc:
        raise CationPiGeometryError(
            "Charged-group atoms must be iterable."
        ) from exc


def _cation_pi_get_group_center(
    charged_group: Any,
) -> Tuple[float, float, float]:
    """
    Return the charge center or geometric group center.

    Preference order:
    1. explicit charge center;
    2. explicit centroid;
    3. weighted/representative atom position;
    4. average of group atoms.
    """

    explicit_center = _cation_pi_get_first_attribute(
        charged_group,
        (
            "charge_center",
            "center_of_charge",
            "centroid",
            "center",
            "centre",
            "coordinates",
            "coordinate",
            "position",
        ),
    )

    if explicit_center is not None:
        return _cation_pi_as_vector3(
            explicit_center,
            field_name="cation center",
        )

    representative_atom = _cation_pi_get_first_attribute(
        charged_group,
        (
            "central_atom",
            "representative_atom",
            "charged_atom",
        ),
    )

    if representative_atom is not None:
        return _cation_pi_get_atom_coordinates(
            representative_atom
        )

    atoms = _cation_pi_get_group_atoms(
        charged_group
    )

    if not atoms:
        raise CationPiGeometryError(
            "Charged group has no defined center or atoms."
        )

    coordinates = [
        _cation_pi_get_atom_coordinates(atom)
        for atom in atoms
    ]

    atom_count = float(len(coordinates))

    return (
        sum(coordinate[0] for coordinate in coordinates) / atom_count,
        sum(coordinate[1] for coordinate in coordinates) / atom_count,
        sum(coordinate[2] for coordinate in coordinates) / atom_count,
    )


def _cation_pi_get_group_orientation(
    charged_group: Any,
) -> Optional[Tuple[float, float, float]]:
    """
    Return a normalized orientation vector when available.

    The vector may describe the principal axis, charge direction, molecular
    axis or direction from a neighboring atom toward the charged center.
    """

    orientation = _cation_pi_get_first_attribute(
        charged_group,
        (
            "orientation_vector",
            "direction_vector",
            "axis_vector",
            "principal_axis",
            "normal",
            "charge_direction",
        ),
    )

    if orientation is None:
        return None

    try:
        return _cation_pi_normalize_vector(
            _cation_pi_as_vector3(
                orientation,
                field_name="charged-group orientation",
            )
        )

    except CationPiGeometryError:
        return None


def _cation_pi_get_identifier(
    object_: Any,
    fallback: str,
) -> str:
    value = _cation_pi_get_first_attribute(
        object_,
        (
            "group_id",
            "ring_id",
            "system_id",
            "aromatic_system_id",
            "id",
            "identifier",
        ),
        fallback,
    )

    return str(value)


def _cation_pi_get_participant_type(
    object_: Any,
) -> Optional[str]:
    value = _cation_pi_get_first_attribute(
        object_,
        (
            "participant_type",
            "source_type",
            "molecule_type",
            "role",
        ),
    )

    return None if value is None else str(value)


def _cation_pi_get_residue_id(
    object_: Any,
) -> Optional[str]:
    residue_id = _cation_pi_get_first_attribute(
        object_,
        (
            "residue_id",
            "residue_key",
        ),
    )

    if residue_id is not None:
        return str(residue_id)

    chain_id = _cation_pi_get_first_attribute(
        object_,
        ("chain_id", "chain"),
        "",
    )

    residue_name = _cation_pi_get_first_attribute(
        object_,
        ("residue_name", "resname"),
        "",
    )

    residue_number = _cation_pi_get_first_attribute(
        object_,
        (
            "residue_number",
            "residue_index",
            "resid",
        ),
        "",
    )

    if not any(
        value not in ("", None)
        for value in (
            chain_id,
            residue_name,
            residue_number,
        )
    ):
        return None

    return (
        f"{chain_id}:"
        f"{residue_name}:"
        f"{residue_number}"
    )


# -----------------------------------------------------------------------------
# 9.6. Determinação da carga positiva
# -----------------------------------------------------------------------------

def _cation_pi_numeric_charge(
    value: Any,
) -> Optional[float]:
    if value is None:
        return None

    try:
        charge = float(value)

    except (TypeError, ValueError):
        return None

    if not math.isfinite(charge):
        return None

    return charge


def infer_cation_pi_charge(
    charged_group: Any,
    *,
    config: Optional[CationPiDetectionConfig] = None,
) -> Tuple[float, str]:
    """
    Determine the effective positive charge of a group.

    Priority
    --------
    1. explicit group charge;
    2. formal charge;
    3. sum of atomic formal charges;
    4. partial charge;
    5. sum of atomic partial charges;
    6. positively charged/cationic annotation;
    7. inferred charge from a known charged-group classification.
    """

    if config is None:
        config = create_default_cation_pi_detection_config()

    explicit_group_charge = _cation_pi_numeric_charge(
        _cation_pi_get_first_attribute(
            charged_group,
            (
                "effective_charge",
                "group_charge",
                "net_charge",
                "charge",
            ),
        )
    )

    if explicit_group_charge is not None:
        return (
            explicit_group_charge,
            CATION_PI_CHARGE_SOURCE_GROUP,
        )

    formal_charge = _cation_pi_numeric_charge(
        _cation_pi_get_first_attribute(
            charged_group,
            (
                "formal_charge",
                "formal_net_charge",
            ),
        )
    )

    if formal_charge is not None:
        return (
            formal_charge,
            CATION_PI_CHARGE_SOURCE_FORMAL,
        )

    atoms = _cation_pi_get_group_atoms(
        charged_group
    )

    atomic_formal_charges = [
        charge
        for atom in atoms
        if (
            charge := _cation_pi_numeric_charge(
                _cation_pi_get_first_attribute(
                    atom,
                    ("formal_charge",),
                )
            )
        )
        is not None
    ]

    if atomic_formal_charges:
        formal_sum = sum(
            atomic_formal_charges
        )

        if abs(formal_sum) > CATION_PI_EPSILON:
            return (
                formal_sum,
                CATION_PI_CHARGE_SOURCE_FORMAL,
            )

    if config.allow_partial_charge:
        partial_charge = _cation_pi_numeric_charge(
            _cation_pi_get_first_attribute(
                charged_group,
                (
                    "partial_charge",
                    "partial_net_charge",
                ),
            )
        )

        if partial_charge is not None:
            return (
                partial_charge,
                CATION_PI_CHARGE_SOURCE_PARTIAL,
            )

        atomic_partial_charges = [
            charge
            for atom in atoms
            if (
                charge := _cation_pi_numeric_charge(
                    _cation_pi_get_first_attribute(
                        atom,
                        (
                            "partial_charge",
                            "charge",
                        ),
                    )
                )
            )
            is not None
        ]

        if atomic_partial_charges:
            partial_sum = sum(
                atomic_partial_charges
            )

            if abs(partial_sum) > CATION_PI_EPSILON:
                return (
                    partial_sum,
                    CATION_PI_CHARGE_SOURCE_PARTIAL,
                )

    positive_annotation = _cation_pi_get_first_attribute(
        charged_group,
        (
            "is_positive",
            "positively_charged",
            "is_cation",
            "cationic",
        ),
    )

    if positive_annotation is True and config.allow_inferred_charge:
        return (
            1.0,
            CATION_PI_CHARGE_SOURCE_INFERRED,
        )

    group_type = str(
        _cation_pi_get_first_attribute(
            charged_group,
            (
                "group_type",
                "charge_type",
                "chemical_type",
                "classification",
            ),
            "",
        )
    ).strip().lower()

    known_positive_groups = {
        "cation",
        "cationic",
        "positive",
        "positively-charged",
        "protonated-amine",
        "protonated_amine",
        "ammonium",
        "guanidinium",
        "imidazolium",
        "pyridinium",
        "quaternary-ammonium",
        "quaternary_ammonium",
        "metal-cation",
        "metal_cation",
    }

    if (
        config.allow_inferred_charge
        and group_type in known_positive_groups
    ):
        return (
            1.0,
            CATION_PI_CHARGE_SOURCE_INFERRED,
        )

    return (
        0.0,
        CATION_PI_CHARGE_SOURCE_UNKNOWN,
    )


def is_positive_cation_pi_group(
    charged_group: Any,
    *,
    config: Optional[CationPiDetectionConfig] = None,
) -> bool:
    """
    Return whether a charged group satisfies the positive-charge threshold.
    """

    if config is None:
        config = create_default_cation_pi_detection_config()

    charge, _ = infer_cation_pi_charge(
        charged_group,
        config=config,
    )

    return charge >= config.minimum_positive_charge


# -----------------------------------------------------------------------------
# 9.7. Geometria carga–anel
# -----------------------------------------------------------------------------

def calculate_cation_pi_position(
    ring: Any,
    charged_group: Any,
) -> Dict[str, Any]:
    """
    Calculate the cation position relative to the aromatic plane.

    The cation-to-centroid vector is decomposed into:

    - a perpendicular component: signed height;
    - a component parallel to the plane: radial offset.
    """

    centroid = _cation_pi_get_ring_centroid(
        ring
    )

    normal = _cation_pi_get_ring_normal(
        ring
    )

    charge_center = _cation_pi_get_group_center(
        charged_group
    )

    centroid_to_charge = _cation_pi_vector_subtract(
        charge_center,
        centroid,
    )

    signed_height = _cation_pi_dot(
        centroid_to_charge,
        normal,
    )

    absolute_height = abs(
        signed_height
    )

    centroid_distance = _cation_pi_norm(
        centroid_to_charge
    )

    radial_squared = max(
        0.0,
        centroid_distance ** 2
        - absolute_height ** 2,
    )

    radial_offset = math.sqrt(
        radial_squared
    )

    if signed_height > CATION_PI_EPSILON:
        face = CATION_PI_FACE_POSITIVE

    elif signed_height < -CATION_PI_EPSILON:
        face = CATION_PI_FACE_NEGATIVE

    else:
        face = CATION_PI_FACE_IN_PLANE

    return {
        "ring_centroid": centroid,
        "ring_normal": normal,
        "charge_center": charge_center,
        "centroid_to_charge_vector": centroid_to_charge,
        "centroid_distance": centroid_distance,
        "signed_height": signed_height,
        "absolute_height": absolute_height,
        "radial_offset": radial_offset,
        "face": face,
    }


def calculate_cation_pi_orientation_angle(
    ring: Any,
    charged_group: Any,
) -> Optional[float]:
    """
    Calculate the acute angle between group orientation and ring normal.

    An orientation vector is optional. Its absence does not invalidate the
    interaction because many monatomic or approximately spherical cations do
    not have a meaningful orientation.
    """

    orientation = _cation_pi_get_group_orientation(
        charged_group
    )

    if orientation is None:
        return None

    ring_normal = _cation_pi_get_ring_normal(
        ring
    )

    cosine = abs(
        _cation_pi_dot(
            orientation,
            ring_normal,
        )
    )

    cosine = max(
        -1.0,
        min(1.0, cosine),
    )

    return math.degrees(
        math.acos(cosine)
    )


def calculate_cation_pi_minimum_atomic_distance(
    ring: Any,
    charged_group: Any,
) -> float:
    """
    Calculate the minimum distance between ring and charged-group atoms.

    This distance supplements the centroid/plane analysis and does not replace
    it.
    """

    ring_atoms = _cation_pi_get_ring_atoms(
        ring
    )

    group_atoms = _cation_pi_get_group_atoms(
        charged_group
    )

    if not ring_atoms:
        raise CationPiGeometryError(
            "The aromatic system contains no atoms."
        )

    if not group_atoms:
        charge_center = _cation_pi_get_group_center(
            charged_group
        )

        return min(
            _cation_pi_distance(
                _cation_pi_get_atom_coordinates(atom),
                charge_center,
            )
            for atom in ring_atoms
        )

    minimum_distance = math.inf

    for ring_atom in ring_atoms:
        ring_coordinates = _cation_pi_get_atom_coordinates(
            ring_atom
        )

        for group_atom in group_atoms:
            group_coordinates = _cation_pi_get_atom_coordinates(
                group_atom
            )

            distance = _cation_pi_distance(
                ring_coordinates,
                group_coordinates,
            )

            if distance < minimum_distance:
                minimum_distance = distance

    if not math.isfinite(minimum_distance):
        raise CationPiGeometryError(
            "Could not calculate the minimum atomic distance."
        )

    return minimum_distance


# -----------------------------------------------------------------------------
# 9.8. Contatos atômicos auxiliares
# -----------------------------------------------------------------------------

def _cation_pi_construct_atomic_contact(
    ring_atom: Any,
    group_atom: Any,
    distance: float,
    *,
    contact_index: int,
    ring_id: str,
    group_id: str,
) -> Any:
    contact_id = (
        f"cation-pi-contact:"
        f"{ring_id}:"
        f"{group_id}:"
        f"{contact_index}"
    )

    candidate_values: Dict[str, Any] = {
        "contact_id": contact_id,
        "id": contact_id,
        "interaction_type": CATION_PI_INTERACTION_TYPE,
        "atom_1": ring_atom,
        "atom_2": group_atom,
        "distance": float(distance),
        "valid": True,
        "metadata": {
            "ring_id": ring_id,
            "charged_group_id": group_id,
            "auxiliary_contact": True,
        },
    }

    if is_dataclass(PiAtomicContact):
        supported_fields = {
            field_definition.name
            for field_definition in fields(PiAtomicContact)
        }

        candidate_values = {
            key: value
            for key, value in candidate_values.items()
            if key in supported_fields
        }

    return PiAtomicContact(
        **candidate_values
    )


def find_cation_pi_atomic_contacts(
    ring: Any,
    charged_group: Any,
    *,
    maximum_distance: float = CATION_PI_DEFAULT_ATOMIC_CONTACT_DISTANCE,
) -> Tuple[Any, ...]:
    """
    Return auxiliary atom–atom contacts for a cation–π interaction.
    """

    maximum_distance = float(
        maximum_distance
    )

    if maximum_distance <= 0.0:
        raise CationPiValidationError(
            "maximum_distance must be greater than zero."
        )

    ring_atoms = _cation_pi_get_ring_atoms(
        ring
    )

    group_atoms = _cation_pi_get_group_atoms(
        charged_group
    )

    if not group_atoms:
        return ()

    ring_id = _cation_pi_get_identifier(
        ring,
        "ring",
    )

    group_id = _cation_pi_get_identifier(
        charged_group,
        "cation",
    )

    contacts: List[Any] = []

    for ring_atom in ring_atoms:
        ring_coordinates = _cation_pi_get_atom_coordinates(
            ring_atom
        )

        for group_atom in group_atoms:
            group_coordinates = _cation_pi_get_atom_coordinates(
                group_atom
            )

            distance = _cation_pi_distance(
                ring_coordinates,
                group_coordinates,
            )

            if distance <= maximum_distance:
                contacts.append(
                    _cation_pi_construct_atomic_contact(
                        ring_atom,
                        group_atom,
                        distance,
                        contact_index=len(contacts) + 1,
                        ring_id=ring_id,
                        group_id=group_id,
                    )
                )

    contacts.sort(
        key=lambda contact: float(
            _cation_pi_get_first_attribute(
                contact,
                ("distance",),
                math.inf,
            )
        )
    )

    return tuple(
        contacts
    )


# -----------------------------------------------------------------------------
# 9.9. Funções de qualidade geométrica
# -----------------------------------------------------------------------------

def _cation_pi_clamp(
    value: float,
    minimum: float = 0.0,
    maximum: float = 1.0,
) -> float:
    return max(
        minimum,
        min(maximum, float(value)),
    )


def _cation_pi_inverse_linear_quality(
    value: float,
    *,
    optimal: float,
    maximum: float,
) -> float:
    if value <= optimal:
        return 1.0

    if value >= maximum:
        return 0.0

    denominator = maximum - optimal

    if denominator <= CATION_PI_EPSILON:
        return 0.0

    return _cation_pi_clamp(
        1.0
        - (
            (value - optimal)
            / denominator
        )
    )


def _cation_pi_window_quality(
    value: float,
    *,
    minimum: float,
    optimal: float,
    maximum: float,
) -> float:
    """
    Score a value whose optimum lies between two limiting values.
    """

    value = float(value)

    if value < minimum or value > maximum:
        return 0.0

    if value == optimal:
        return 1.0

    if value < optimal:
        denominator = optimal - minimum

        if denominator <= CATION_PI_EPSILON:
            return 1.0

        return _cation_pi_clamp(
            (value - minimum)
            / denominator
        )

    denominator = maximum - optimal

    if denominator <= CATION_PI_EPSILON:
        return 1.0

    return _cation_pi_clamp(
        1.0
        - (
            (value - optimal)
            / denominator
        )
    )


def calculate_cation_pi_geometry_confidence(
    *,
    geometry: str,
    centroid_distance: float,
    absolute_height: float,
    radial_offset: float,
    minimum_atomic_distance: float,
    ring_planarity_rmsd: float,
    effective_charge: float,
    orientation_angle: Optional[float],
    config: CationPiDetectionConfig,
) -> float:
    """
    Calculate geometric confidence for a cation–π candidate.

    This is not the final Section 11 interaction score.
    """

    distance_quality = _cation_pi_inverse_linear_quality(
        centroid_distance,
        optimal=config.optimal_centroid_distance,
        maximum=config.borderline_maximum_centroid_distance,
    )

    height_quality = _cation_pi_window_quality(
        absolute_height,
        minimum=config.minimum_height,
        optimal=config.optimal_height,
        maximum=config.borderline_maximum_height,
    )

    radial_quality = _cation_pi_inverse_linear_quality(
        radial_offset,
        optimal=config.centered_maximum_radial_offset,
        maximum=config.borderline_maximum_radial_offset,
    )

    atomic_quality = _cation_pi_inverse_linear_quality(
        minimum_atomic_distance,
        optimal=config.atomic_contact_distance,
        maximum=max(
            config.maximum_minimum_atomic_distance,
            config.atomic_contact_distance
            + CATION_PI_EPSILON,
        ),
    )

    planarity_quality = _cation_pi_inverse_linear_quality(
        ring_planarity_rmsd,
        optimal=0.0,
        maximum=config.borderline_planarity_rmsd,
    )

    if effective_charge <= 0.0:
        charge_quality = 0.0

    elif effective_charge >= config.strong_positive_charge:
        charge_quality = 1.0

    else:
        charge_quality = _cation_pi_clamp(
            effective_charge
            / max(
                config.strong_positive_charge,
                CATION_PI_EPSILON,
            )
        )

    if orientation_angle is None:
        orientation_quality = 0.5

    else:
        orientation_quality = _cation_pi_inverse_linear_quality(
            orientation_angle,
            optimal=config.favorable_orientation_maximum_angle,
            maximum=config.acceptable_orientation_maximum_angle,
        )

    orientation_weight = (
        config.orientation_weight
        if config.use_group_orientation
        else 0.0
    )

    remaining_weight = 1.0 - orientation_weight

    base_quality = (
        0.24 * distance_quality
        + 0.22 * height_quality
        + 0.20 * radial_quality
        + 0.10 * atomic_quality
        + 0.10 * planarity_quality
        + 0.14 * charge_quality
    )

    confidence = (
        remaining_weight * base_quality
        + orientation_weight * orientation_quality
    )

    if geometry == CATION_PI_GEOMETRY_BORDERLINE:
        confidence *= 0.75

    elif geometry == CATION_PI_GEOMETRY_EDGE_ASSOCIATED:
        confidence *= 0.90

    elif geometry == CATION_PI_GEOMETRY_REJECTED:
        confidence *= 0.25

    return _cation_pi_clamp(
        confidence
    )


# -----------------------------------------------------------------------------
# 9.10. Avaliação da geometria cátion–π
# -----------------------------------------------------------------------------

def evaluate_cation_pi_geometry(
    *,
    centroid_distance: float,
    signed_height: float,
    radial_offset: float,
    minimum_atomic_distance: float,
    ring_planarity_rmsd: float,
    effective_charge: float,
    charge_source: str = CATION_PI_CHARGE_SOURCE_UNKNOWN,
    orientation_angle: Optional[float] = None,
    config: Optional[CationPiDetectionConfig] = None,
) -> CationPiGeometryEvaluation:
    """
    Evaluate one cation relative to an aromatic system.

    The classification depends primarily on the decomposition of the
    charge–centroid vector into perpendicular height and radial displacement.
    Atom–atom contacts are supplementary and are not sufficient by themselves.
    """

    if config is None:
        config = create_default_cation_pi_detection_config()

    numeric_values = {
        "centroid_distance": centroid_distance,
        "signed_height": signed_height,
        "radial_offset": radial_offset,
        "minimum_atomic_distance": minimum_atomic_distance,
        "ring_planarity_rmsd": ring_planarity_rmsd,
        "effective_charge": effective_charge,
    }

    normalized: Dict[str, float] = {}

    for field_name, value in numeric_values.items():
        try:
            normalized_value = float(value)

        except (TypeError, ValueError) as exc:
            raise CationPiValidationError(
                f"{field_name} must be numeric."
            ) from exc

        if not math.isfinite(normalized_value):
            raise CationPiValidationError(
                f"{field_name} must be finite."
            )

        normalized[field_name] = normalized_value

    for nonnegative_field in (
        "centroid_distance",
        "radial_offset",
        "minimum_atomic_distance",
        "ring_planarity_rmsd",
    ):
        if normalized[nonnegative_field] < 0.0:
            raise CationPiValidationError(
                f"{nonnegative_field} cannot be negative."
            )

    if charge_source not in SUPPORTED_CATION_PI_CHARGE_SOURCES:
        charge_source = CATION_PI_CHARGE_SOURCE_UNKNOWN

    if orientation_angle is not None:
        try:
            orientation_angle = float(
                orientation_angle
            )

        except (TypeError, ValueError) as exc:
            raise CationPiValidationError(
                "orientation_angle must be numeric or None."
            ) from exc

        if not math.isfinite(orientation_angle):
            raise CationPiValidationError(
                "orientation_angle must be finite."
            )

        orientation_angle = min(
            90.0,
            abs(orientation_angle),
        )

    signed_height = normalized[
        "signed_height"
    ]

    absolute_height = abs(
        signed_height
    )

    if signed_height > CATION_PI_EPSILON:
        face = CATION_PI_FACE_POSITIVE

    elif signed_height < -CATION_PI_EPSILON:
        face = CATION_PI_FACE_NEGATIVE

    else:
        face = CATION_PI_FACE_IN_PLANE

    centroid_distance_valid = (
        normalized["centroid_distance"]
        <= config.maximum_centroid_distance
    )

    height_valid = (
        config.minimum_height
        <= absolute_height
        <= config.maximum_height
    )

    atomic_distance_valid = (
        normalized["minimum_atomic_distance"]
        <= config.maximum_minimum_atomic_distance
    )

    planarity_valid = (
        normalized["ring_planarity_rmsd"]
        <= config.maximum_planarity_rmsd
    )

    charge_valid = (
        normalized["effective_charge"]
        >= config.minimum_positive_charge
    )

    strongly_charged = (
        normalized["effective_charge"]
        >= config.strong_positive_charge
    )

    orientation_available = (
        orientation_angle is not None
    )

    if orientation_angle is None:
        orientation_valid: Optional[bool] = None

    else:
        orientation_valid = (
            orientation_angle
            <= config.acceptable_orientation_maximum_angle
        )

    geometry = CATION_PI_GEOMETRY_REJECTED
    accepted = False
    borderline = False
    radial_offset_valid = False

    reasons: List[str] = []
    warnings: List[str] = []

    core_requirements = (
        centroid_distance_valid
        and height_valid
        and planarity_valid
        and (
            charge_valid
            or not config.require_positive_charge
        )
        and (
            atomic_distance_valid
            or not config.require_atomic_contact
        )
    )

    if (
        core_requirements
        and normalized["radial_offset"]
        <= config.centered_maximum_radial_offset
    ):
        geometry = CATION_PI_GEOMETRY_FACE_CENTERED
        accepted = True
        radial_offset_valid = True

        reasons.append(
            "The positive charge lies above an aromatic face near the "
            "ring center."
        )

    elif (
        core_requirements
        and normalized["radial_offset"]
        <= config.offset_maximum_radial_offset
    ):
        geometry = CATION_PI_GEOMETRY_FACE_OFFSET
        accepted = True
        radial_offset_valid = True

        reasons.append(
            "The positive charge lies above the aromatic face with a "
            "moderate radial displacement."
        )

    elif (
        core_requirements
        and normalized["radial_offset"]
        <= config.edge_maximum_radial_offset
    ):
        geometry = CATION_PI_GEOMETRY_EDGE_ASSOCIATED
        accepted = True
        radial_offset_valid = True

        reasons.append(
            "The positive charge is associated with the peripheral region "
            "of the aromatic face."
        )

    else:
        borderline_requirements = (
            config.include_borderline
            and normalized["centroid_distance"]
            <= config.borderline_maximum_centroid_distance
            and absolute_height
            <= config.borderline_maximum_height
            and normalized["radial_offset"]
            <= config.borderline_maximum_radial_offset
            and normalized["ring_planarity_rmsd"]
            <= config.borderline_planarity_rmsd
            and (
                normalized["effective_charge"]
                >= config.minimum_positive_charge
                or not config.require_positive_charge
            )
        )

        if borderline_requirements:
            geometry = CATION_PI_GEOMETRY_BORDERLINE
            accepted = True
            borderline = True
            radial_offset_valid = True

            reasons.append(
                "The cation and aromatic system form a limiting geometry "
                "outside the canonical face-centered region."
            )

        else:
            if not centroid_distance_valid:
                warnings.append(
                    "Charge–centroid distance exceeds the canonical limit."
                )

            if not height_valid:
                if absolute_height < config.minimum_height:
                    warnings.append(
                        "The charge is too close to the aromatic plane or "
                        "approximately coplanar with the ring."
                    )

                else:
                    warnings.append(
                        "The charge lies too far above the aromatic plane."
                    )

            if (
                normalized["radial_offset"]
                > config.edge_maximum_radial_offset
            ):
                warnings.append(
                    "Radial displacement exceeds the aromatic-face limit."
                )

            if not atomic_distance_valid:
                warnings.append(
                    "Minimum atom–atom distance exceeds the auxiliary "
                    "contact limit."
                )

            if not planarity_valid:
                warnings.append(
                    "The aromatic system has insufficient planar quality."
                )

            if not charge_valid:
                warnings.append(
                    "The group does not satisfy the minimum positive-charge "
                    "criterion."
                )

    if (
        config.use_group_orientation
        and orientation_available
        and orientation_valid is False
    ):
        warnings.append(
            "The charged-group orientation is geometrically unfavorable."
        )

    confidence = calculate_cation_pi_geometry_confidence(
        geometry=geometry,
        centroid_distance=normalized["centroid_distance"],
        absolute_height=absolute_height,
        radial_offset=normalized["radial_offset"],
        minimum_atomic_distance=normalized[
            "minimum_atomic_distance"
        ],
        ring_planarity_rmsd=normalized[
            "ring_planarity_rmsd"
        ],
        effective_charge=normalized[
            "effective_charge"
        ],
        orientation_angle=orientation_angle,
        config=config,
    )

    return CationPiGeometryEvaluation(
        geometry=geometry,
        centroid_distance=normalized["centroid_distance"],
        signed_height=signed_height,
        absolute_height=absolute_height,
        radial_offset=normalized["radial_offset"],
        minimum_atomic_distance=normalized[
            "minimum_atomic_distance"
        ],
        face=face,
        effective_charge=normalized[
            "effective_charge"
        ],
        charge_source=charge_source,
        charge_valid=charge_valid,
        strongly_charged=strongly_charged,
        orientation_angle=orientation_angle,
        orientation_valid=orientation_valid,
        orientation_available=orientation_available,
        ring_planarity_rmsd=normalized[
            "ring_planarity_rmsd"
        ],
        centroid_distance_valid=centroid_distance_valid,
        height_valid=height_valid,
        radial_offset_valid=radial_offset_valid,
        atomic_distance_valid=atomic_distance_valid,
        planarity_valid=planarity_valid,
        accepted=accepted,
        borderline=borderline,
        confidence=confidence,
        reasons=tuple(reasons),
        warnings=tuple(warnings),
    )


# -----------------------------------------------------------------------------
# 9.11. Avaliação completa de um par
# -----------------------------------------------------------------------------

def evaluate_cation_pi_pair(
    ring: Any,
    charged_group: Any,
    *,
    config: Optional[CationPiDetectionConfig] = None,
) -> CationPiGeometryEvaluation:
    """
    Calculate and classify one aromatic-system/cation pair.
    """

    if config is None:
        config = create_default_cation_pi_detection_config()

    position = calculate_cation_pi_position(
        ring,
        charged_group,
    )

    minimum_atomic_distance = (
        calculate_cation_pi_minimum_atomic_distance(
            ring,
            charged_group,
        )
    )

    planarity = _cation_pi_get_ring_planarity(
        ring
    )

    effective_charge, charge_source = infer_cation_pi_charge(
        charged_group,
        config=config,
    )

    orientation_angle = calculate_cation_pi_orientation_angle(
        ring,
        charged_group,
    )

    evaluation = evaluate_cation_pi_geometry(
        centroid_distance=position[
            "centroid_distance"
        ],
        signed_height=position[
            "signed_height"
        ],
        radial_offset=position[
            "radial_offset"
        ],
        minimum_atomic_distance=minimum_atomic_distance,
        ring_planarity_rmsd=planarity,
        effective_charge=effective_charge,
        charge_source=charge_source,
        orientation_angle=orientation_angle,
        config=config,
    )

    evaluation.metadata.update(
        {
            "ring_id": _cation_pi_get_identifier(
                ring,
                "ring",
            ),
            "charged_group_id": _cation_pi_get_identifier(
                charged_group,
                "cation",
            ),
            "ring_centroid": position[
                "ring_centroid"
            ],
            "ring_normal": position[
                "ring_normal"
            ],
            "charge_center": position[
                "charge_center"
            ],
            "centroid_to_charge_vector": position[
                "centroid_to_charge_vector"
            ],
            "geometry_model": (
                "charge-center relative to aromatic centroid and plane"
            ),
        }
    )

    return evaluation


# -----------------------------------------------------------------------------
# 9.12. Construção de PiInteraction
# -----------------------------------------------------------------------------

def _cation_pi_construct_interaction(
    ring: Any,
    charged_group: Any,
    evaluation: CationPiGeometryEvaluation,
    *,
    interaction_index: int,
    config: CationPiDetectionConfig,
) -> Any:
    ring_id = _cation_pi_get_identifier(
        ring,
        f"ring_{interaction_index}",
    )

    charged_group_id = _cation_pi_get_identifier(
        charged_group,
        f"cation_{interaction_index}",
    )

    interaction_id = (
        f"cation-pi:"
        f"{charged_group_id}:"
        f"{ring_id}"
    )

    atomic_contacts: Tuple[Any, ...] = ()

    if config.include_atomic_contacts:
        atomic_contacts = find_cation_pi_atomic_contacts(
            ring,
            charged_group,
            maximum_distance=config.atomic_contact_distance,
        )

    ring_residue_id = _cation_pi_get_residue_id(
        ring
    )

    group_residue_id = _cation_pi_get_residue_id(
        charged_group
    )

    candidate_values: Dict[str, Any] = {
        "interaction_id": interaction_id,
        "id": interaction_id,
        "interaction_type": CATION_PI_INTERACTION_TYPE,
        "subtype": evaluation.geometry,
        "geometry_class": evaluation.geometry,
        "aromatic_system": ring,
        "ring": ring,
        "ring_1": ring,
        "charged_group": charged_group,
        "cation_group": charged_group,
        "participant_1_type": _cation_pi_get_participant_type(
            ring
        ),
        "participant_2_type": _cation_pi_get_participant_type(
            charged_group
        ),
        "centroid_distance": evaluation.centroid_distance,
        "signed_height": evaluation.signed_height,
        "height": evaluation.absolute_height,
        "absolute_height": evaluation.absolute_height,
        "radial_offset": evaluation.radial_offset,
        "lateral_offset": evaluation.radial_offset,
        "minimum_atomic_distance": evaluation.minimum_atomic_distance,
        "face": evaluation.face,
        "effective_charge": evaluation.effective_charge,
        "charge_source": evaluation.charge_source,
        "orientation_angle": evaluation.orientation_angle,
        "ring_planarity": evaluation.ring_planarity_rmsd,
        "geometry_confidence": evaluation.confidence,
        "atomic_contacts": atomic_contacts,
        "valid": evaluation.accepted,
        "borderline": evaluation.borderline,
        "warnings": list(evaluation.warnings),
        "metadata": {
            "schema": "cation-pi-interaction",
            "geometry_reasons": list(evaluation.reasons),
            "geometry_evaluation": evaluation.to_dict(),
            "ring_id": ring_id,
            "charged_group_id": charged_group_id,
            "ring_residue_id": ring_residue_id,
            "charged_group_residue_id": group_residue_id,
            "atomic_contact_count": len(atomic_contacts),
            "center_plane_based_detection": True,
        },
    }

    if is_dataclass(PiInteraction):
        supported_fields = {
            field_definition.name
            for field_definition in fields(PiInteraction)
        }

        candidate_values = {
            key: value
            for key, value in candidate_values.items()
            if key in supported_fields
        }

    try:
        return PiInteraction(
            **candidate_values
        )

    except TypeError as exc:
        raise CationPiDetectionError(
            "Could not construct PiInteraction for the cation–π pair. "
            "Verify the PiInteraction dataclass defined in Section 2."
        ) from exc


# -----------------------------------------------------------------------------
# 9.13. Validação e deduplicação
# -----------------------------------------------------------------------------

def _cation_pi_same_residue(
    ring: Any,
    charged_group: Any,
) -> bool:
    ring_residue = _cation_pi_get_residue_id(
        ring
    )

    group_residue = _cation_pi_get_residue_id(
        charged_group
    )

    return bool(
        ring_residue
        and group_residue
        and ring_residue == group_residue
    )


def _cation_pi_pair_key(
    ring: Any,
    charged_group: Any,
) -> Tuple[str, str]:
    return (
        _cation_pi_get_identifier(
            ring,
            str(id(ring)),
        ),
        _cation_pi_get_identifier(
            charged_group,
            str(id(charged_group)),
        ),
    )


# -----------------------------------------------------------------------------
# 9.14. Detecção principal
# -----------------------------------------------------------------------------

def detect_cation_pi_interactions(
    aromatic_systems: Iterable[Any],
    positive_groups: Iterable[Any],
    *,
    config: Optional[CationPiDetectionConfig] = None,
    exclude_same_residue: Optional[bool] = None,
    strict: bool = False,
) -> List[Any]:
    """
    Detect cation–π interactions between aromatic systems and positive groups.

    Detection is based on the position of the charge center relative to the
    aromatic centroid and plane. Direct nitrogen–carbon contacts are neither
    necessary nor sufficient by themselves.

    Parameters
    ----------
    aromatic_systems:
        Aromatic systems identified in Section 4.
    positive_groups:
        Charged groups identified in Section 6.
    config:
        Cation–π geometric and chemical thresholds.
    exclude_same_residue:
        Prevent interactions between a ring and a charged group belonging to
        the same residue. When None, the configuration value is used.
    strict:
        Raise errors for malformed pairs instead of skipping them.
    """

    if config is None:
        config = create_default_cation_pi_detection_config()

    if exclude_same_residue is None:
        exclude_same_residue = (
            config.exclude_intramolecular_same_residue
        )

    rings = tuple(
        aromatic_systems
    )

    groups = tuple(
        positive_groups
    )

    interactions: List[Any] = []
    evaluated_pairs: Set[
        Tuple[str, str]
    ] = set()

    for ring in rings:
        for charged_group in groups:
            if (
                exclude_same_residue
                and _cation_pi_same_residue(
                    ring,
                    charged_group,
                )
            ):
                continue

            pair_key = _cation_pi_pair_key(
                ring,
                charged_group,
            )

            if (
                config.deduplicate_results
                and pair_key in evaluated_pairs
            ):
                continue

            evaluated_pairs.add(
                pair_key
            )

            try:
                effective_charge, _ = infer_cation_pi_charge(
                    charged_group,
                    config=config,
                )

                if (
                    config.require_positive_charge
                    and effective_charge
                    < config.minimum_positive_charge
                ):
                    continue

                evaluation = evaluate_cation_pi_pair(
                    ring,
                    charged_group,
                    config=config,
                )

            except (
                CationPiGeometryError,
                CationPiValidationError,
                TypeError,
                ValueError,
            ):
                if strict:
                    raise

                continue

            if (
                not evaluation.accepted
                and not config.include_rejected
            ):
                continue

            interaction = _cation_pi_construct_interaction(
                ring,
                charged_group,
                evaluation,
                interaction_index=len(interactions) + 1,
                config=config,
            )

            interactions.append(
                interaction
            )

    interactions.sort(
        key=lambda interaction: (
            not bool(
                _cation_pi_get_first_attribute(
                    interaction,
                    ("valid",),
                    False,
                )
            ),
            -float(
                _cation_pi_get_first_attribute(
                    interaction,
                    (
                        "geometry_confidence",
                        "confidence",
                    ),
                    0.0,
                )
            ),
            float(
                _cation_pi_get_first_attribute(
                    interaction,
                    ("centroid_distance",),
                    math.inf,
                )
            ),
            float(
                _cation_pi_get_first_attribute(
                    interaction,
                    (
                        "radial_offset",
                        "lateral_offset",
                    ),
                    math.inf,
                )
            ),
            str(
                _cation_pi_get_first_attribute(
                    interaction,
                    (
                        "interaction_id",
                        "id",
                    ),
                    "",
                )
            ),
        )
    )

    return interactions


# -----------------------------------------------------------------------------
# 9.15. Detecção de uma única interação
# -----------------------------------------------------------------------------

def detect_single_cation_pi_interaction(
    ring: Any,
    charged_group: Any,
    *,
    config: Optional[CationPiDetectionConfig] = None,
    include_rejected: bool = False,
) -> Optional[Any]:
    """
    Detect one cation–π interaction.
    """

    if config is None:
        config = create_default_cation_pi_detection_config()

    effective_charge, _ = infer_cation_pi_charge(
        charged_group,
        config=config,
    )

    if (
        config.require_positive_charge
        and effective_charge
        < config.minimum_positive_charge
        and not include_rejected
    ):
        return None

    evaluation = evaluate_cation_pi_pair(
        ring,
        charged_group,
        config=config,
    )

    if (
        not evaluation.accepted
        and not include_rejected
    ):
        return None

    return _cation_pi_construct_interaction(
        ring,
        charged_group,
        evaluation,
        interaction_index=1,
        config=config,
    )


# -----------------------------------------------------------------------------
# 9.16. Filtros
# -----------------------------------------------------------------------------

def filter_cation_pi_interactions_by_geometry(
    interactions: Iterable[Any],
    geometries: Collection[str],
) -> List[Any]:
    """
    Select cation–π interactions by geometric subtype.
    """

    normalized_geometries = {
        str(geometry).strip().lower()
        for geometry in geometries
    }

    unsupported = (
        normalized_geometries
        - SUPPORTED_CATION_PI_GEOMETRIES
    )

    if unsupported:
        raise CationPiValidationError(
            "Unsupported cation–π geometries: "
            f"{sorted(unsupported)!r}."
        )

    return [
        interaction
        for interaction in interactions
        if str(
            _cation_pi_get_first_attribute(
                interaction,
                (
                    "geometry_class",
                    "subtype",
                ),
                "",
            )
        ).strip().lower()
        in normalized_geometries
    ]


def filter_cation_pi_interactions_by_face(
    interactions: Iterable[Any],
    faces: Collection[str],
) -> List[Any]:
    """
    Select interactions according to the approached aromatic face.
    """

    normalized_faces = {
        str(face).strip().lower()
        for face in faces
    }

    unsupported = (
        normalized_faces
        - SUPPORTED_CATION_PI_FACES
    )

    if unsupported:
        raise CationPiValidationError(
            "Unsupported aromatic faces: "
            f"{sorted(unsupported)!r}."
        )

    return [
        interaction
        for interaction in interactions
        if str(
            _cation_pi_get_first_attribute(
                interaction,
                ("face",),
                "",
            )
        ).strip().lower()
        in normalized_faces
    ]


# -----------------------------------------------------------------------------
# 9.17. Resumo local
# -----------------------------------------------------------------------------

def summarize_cation_pi_detection(
    interactions: Iterable[Any],
) -> Dict[str, Any]:
    """
    Produce a lightweight cation–π summary.

    Full module statistics are produced in Section 13.
    """

    interaction_list = list(
        interactions
    )

    geometry_distribution: Dict[str, int] = defaultdict(int)
    face_distribution: Dict[str, int] = defaultdict(int)
    charge_source_distribution: Dict[str, int] = defaultdict(int)

    centroid_distances: List[float] = []
    heights: List[float] = []
    radial_offsets: List[float] = []
    atomic_distances: List[float] = []
    effective_charges: List[float] = []
    orientation_angles: List[float] = []

    borderline_count = 0

    for interaction in interaction_list:
        geometry = str(
            _cation_pi_get_first_attribute(
                interaction,
                (
                    "geometry_class",
                    "subtype",
                ),
                CATION_PI_GEOMETRY_REJECTED,
            )
        )

        face = str(
            _cation_pi_get_first_attribute(
                interaction,
                ("face",),
                CATION_PI_FACE_IN_PLANE,
            )
        )

        charge_source = str(
            _cation_pi_get_first_attribute(
                interaction,
                ("charge_source",),
                CATION_PI_CHARGE_SOURCE_UNKNOWN,
            )
        )

        geometry_distribution[
            geometry
        ] += 1

        face_distribution[
            face
        ] += 1

        charge_source_distribution[
            charge_source
        ] += 1

        if bool(
            _cation_pi_get_first_attribute(
                interaction,
                ("borderline",),
                False,
            )
        ):
            borderline_count += 1

        value_mappings = (
            (
                centroid_distances,
                ("centroid_distance",),
            ),
            (
                heights,
                (
                    "absolute_height",
                    "height",
                ),
            ),
            (
                radial_offsets,
                (
                    "radial_offset",
                    "lateral_offset",
                ),
            ),
            (
                atomic_distances,
                ("minimum_atomic_distance",),
            ),
            (
                effective_charges,
                ("effective_charge",),
            ),
            (
                orientation_angles,
                ("orientation_angle",),
            ),
        )

        for collection, attribute_names in value_mappings:
            value = _cation_pi_get_first_attribute(
                interaction,
                attribute_names,
            )

            if value is None:
                continue

            try:
                numeric_value = float(value)

            except (TypeError, ValueError):
                continue

            if math.isfinite(numeric_value):
                collection.append(
                    numeric_value
                )

    def numeric_summary(
        values: Sequence[float],
    ) -> Dict[str, Optional[float]]:
        if not values:
            return {
                "mean": None,
                "minimum": None,
                "maximum": None,
            }

        return {
            "mean": sum(values) / len(values),
            "minimum": min(values),
            "maximum": max(values),
        }

    return {
        "total_interactions": len(
            interaction_list
        ),
        "geometry_distribution": dict(
            sorted(
                geometry_distribution.items()
            )
        ),
        "face_distribution": dict(
            sorted(
                face_distribution.items()
            )
        ),
        "charge_source_distribution": dict(
            sorted(
                charge_source_distribution.items()
            )
        ),
        "borderline_interactions": borderline_count,
        "centroid_distance": numeric_summary(
            centroid_distances
        ),
        "height": numeric_summary(
            heights
        ),
        "radial_offset": numeric_summary(
            radial_offsets
        ),
        "minimum_atomic_distance": numeric_summary(
            atomic_distances
        ),
        "effective_charge": numeric_summary(
            effective_charges
        ),
        "orientation_angle": numeric_summary(
            orientation_angles
        ),
    }

