# -----------------------------------------------------------------------------
# 15.16. Resolução de grupos por DockModel
# -----------------------------------------------------------------------------

def _dock_model_pi_resolve_feature_source(
    source: Optional[
        Union[
            Mapping[Any, Iterable[Any]],
            Sequence[Iterable[Any]],
            Callable[[int, Any], Iterable[Any]],
        ]
    ],
    *,
    index: int,
    dock_model: Any,
    pose_id: Optional[str],
) -> Optional[Iterable[Any]]:
    if source is None:
        return None

    if callable(source):
        return source(
            index,
            dock_model,
        )

    if isinstance(source, Mapping):
        keys = (
            pose_id,
            index,
            str(index),
        )

        for key in keys:
            if key is not None and key in source:
                return source[key]

        return None

    if index < len(source):
        return source[index]

    return None


# -----------------------------------------------------------------------------
# 15.17. Análise de múltiplos DockModels
# -----------------------------------------------------------------------------

def analyze_multiple_dock_models_pi(
    dock_models: Iterable[Any],
    *,
    analysis_config: Optional[PiAnalysisConfig] = None,
    integration_config: Optional[
        DockModelPiIntegrationConfig
    ] = None,
    aromatic_systems: Optional[
        Union[
            Mapping[Any, Iterable[Any]],
            Sequence[Iterable[Any]],
            Callable[[int, Any], Iterable[Any]],
        ]
    ] = None,
    positive_groups: Optional[
        Union[
            Mapping[Any, Iterable[Any]],
            Sequence[Iterable[Any]],
            Callable[[int, Any], Iterable[Any]],
        ]
    ] = None,
    negative_groups: Optional[
        Union[
            Mapping[Any, Iterable[Any]],
            Sequence[Iterable[Any]],
            Callable[[int, Any], Iterable[Any]],
        ]
    ] = None,
    amide_groups: Optional[
        Union[
            Mapping[Any, Iterable[Any]],
            Sequence[Iterable[Any]],
            Callable[[int, Any], Iterable[Any]],
        ]
    ] = None,
    continue_on_error: bool = True,
    run_global_multipose_analysis: bool = True,
) -> DockModelPiMultipleIntegrationResult:
    """
    Analyze multiple DockModel objects and update each object independently.

    A global multipose report can also be generated from the resulting models.
    """

    if analysis_config is None:
        analysis_config = create_default_pi_analysis_config()

    if integration_config is None:
        integration_config = create_default_dock_model_pi_config()

    model_list = list(
        dock_models
    )

    model_results: List[
        DockModelPiIntegrationResult
    ] = []

    errors: List[str] = []
    warnings: List[str] = []

    successful_models: List[Any] = []
    successful_pose_map: Dict[str, Any] = {}

    for index, dock_model in enumerate(
        model_list
    ):
        pose_id = resolve_dock_model_pose_id(
            dock_model,
            config=integration_config,
            fallback=str(index + 1),
        )

        model_aromatic_systems = (
            _dock_model_pi_resolve_feature_source(
                aromatic_systems,
                index=index,
                dock_model=dock_model,
                pose_id=pose_id,
            )
        )

        model_positive_groups = (
            _dock_model_pi_resolve_feature_source(
                positive_groups,
                index=index,
                dock_model=dock_model,
                pose_id=pose_id,
            )
        )

        model_negative_groups = (
            _dock_model_pi_resolve_feature_source(
                negative_groups,
                index=index,
                dock_model=dock_model,
                pose_id=pose_id,
            )
        )

        model_amide_groups = (
            _dock_model_pi_resolve_feature_source(
                amide_groups,
                index=index,
                dock_model=dock_model,
                pose_id=pose_id,
            )
        )

        try:
            integration_result = analyze_dock_model_pi(
                dock_model,
                analysis_config=analysis_config,
                integration_config=integration_config,
                aromatic_systems=model_aromatic_systems,
                positive_groups=model_positive_groups,
                negative_groups=model_negative_groups,
                amide_groups=model_amide_groups,
                pose_id=pose_id,
            )

        except Exception as exc:
            error_message = (
                f"DockModel {index} failed during π analysis: {exc}"
            )

            errors.append(
                error_message
            )

            if not continue_on_error:
                raise

            continue

        model_results.append(
            integration_result
        )

        successful_models.append(
            integration_result.dock_model
        )

        successful_pose_map[
            str(pose_id)
        ] = resolve_dock_model_structure(
            integration_result.dock_model
        )

    multipose_result: Optional[
        PiMultiplePoseAnalysisResult
    ] = None

    if (
        run_global_multipose_analysis
        and successful_pose_map
    ):
        try:
            multipose_result = analyze_multiple_poses_pi(
                successful_pose_map,
                config=analysis_config,
                continue_on_error=continue_on_error,
            )

        except Exception as exc:
            warning_message = (
                "Global multipose π analysis failed: "
                f"{exc}"
            )

            warnings.append(
                warning_message
            )

            if not continue_on_error:
                raise

    best_result: Optional[
        DockModelPiIntegrationResult
    ] = None

    if model_results:
        best_result = max(
            model_results,
            key=lambda result: (
                result.analysis_result.normalized_score,
                result.analysis_result.total_score,
                result.analysis_result.total_interactions,
            ),
        )

    best_model = (
        None
        if best_result is None
        else best_result.dock_model
    )

    best_model_index: Optional[int] = None

    if best_model is not None:
        for index, candidate_model in enumerate(
            model_list
        ):
            if candidate_model is best_model:
                best_model_index = index
                break

    best_pose_id = (
        None
        if best_result is None
        else best_result.analysis_result.pose_id
    )

    successful_model_count = len(
        model_results
    )

    failed_model_count = (
        len(model_list)
        - successful_model_count
    )

    return DockModelPiMultipleIntegrationResult(
        model_results=model_results,
        multipose_result=multipose_result,
        model_count=len(model_list),
        successful_model_count=successful_model_count,
        failed_model_count=failed_model_count,
        best_model=best_model,
        best_model_index=best_model_index,
        best_pose_id=best_pose_id,
        success=(
            successful_model_count > 0
            and failed_model_count == 0
        ),
        warnings=warnings,
        errors=errors,
        metadata={
            "schema": "dock-model-pi-multiple-integration",
            "schema_version": (
                DOCK_MODEL_PI_INTEGRATION_SCHEMA_VERSION
            ),
            "global_multipose_analysis": (
                run_global_multipose_analysis
            ),
        },
    )


# -----------------------------------------------------------------------------
# 15.18. Reanexação sem nova análise
# -----------------------------------------------------------------------------

def reattach_existing_pi_analysis(
    dock_model: Any,
    *,
    integration_config: Optional[
        DockModelPiIntegrationConfig
    ] = None,
) -> DockModelPiIntegrationResult:
    """
    Reattach an existing PiAnalysisResult already stored in DockModel.
    """

    if integration_config is None:
        integration_config = create_default_dock_model_pi_config()

    analysis_result = _dock_model_pi_get(
        dock_model,
        (
            integration_config.analysis_result_attribute,
            DOCK_MODEL_PI_RESULT_ATTRIBUTE,
        ),
    )

    if not isinstance(
        analysis_result,
        PiAnalysisResult,
    ):
        raise DockModelPiIntegrationError(
            "DockModel does not contain a valid PiAnalysisResult."
        )

    return attach_pi_results(
        dock_model,
        analysis_result,
        config=integration_config,
    )


# -----------------------------------------------------------------------------
# 15.19. Remoção segura dos resultados ativos
# -----------------------------------------------------------------------------

def clear_dock_model_pi_results(
    dock_model: Any,
    *,
    config: Optional[DockModelPiIntegrationConfig] = None,
    preserve_history: bool = True,
) -> Any:
    """
    Clear active π interactions while optionally preserving them as history.
    """

    if config is None:
        config = create_default_dock_model_pi_config()

    pi_attribute = resolve_dock_model_pi_attribute(
        dock_model,
        config=config,
    )

    previous_interactions = get_dock_model_pi_interactions(
        dock_model,
        config=config,
    )

    updates: Dict[str, Any] = {
        pi_attribute: [],
    }

    if preserve_history and previous_interactions:
        summary = _dock_model_pi_get(
            dock_model,
            (
                config.serializable_summary_attribute,
            ),
            {},
        )

        if not isinstance(summary, Mapping):
            summary = {}

        summary = dict(summary)

        summary["cleared_previous_pi_interactions"] = (
            _make_pi_value_serializable(
                previous_interactions
            )
        )

        updates[
            config.serializable_summary_attribute
        ] = summary

    return _dock_model_pi_update(
        dock_model,
        updates,
        allow_new_attributes=True,
    )


# -----------------------------------------------------------------------------
# 15.20. Resumo da integração
# -----------------------------------------------------------------------------

def summarize_dock_model_pi_integration(
    result: Union[
        DockModelPiIntegrationResult,
        DockModelPiMultipleIntegrationResult,
    ],
) -> Dict[str, Any]:
    """
    Produce a compact summary of DockModel π integration.
    """

    if isinstance(
        result,
        DockModelPiMultipleIntegrationResult,
    ):
        return {
            "model_count": result.model_count,
            "successful_model_count": (
                result.successful_model_count
            ),
            "failed_model_count": (
                result.failed_model_count
            ),
            "best_model_index": (
                result.best_model_index
            ),
            "best_pose_id": result.best_pose_id,
            "multipose_analysis_available": (
                result.multipose_result is not None
            ),
            "warnings": list(
                result.warnings
            ),
            "errors": list(
                result.errors
            ),
        }

    return {
        "success": result.success,
        "pi_attribute": result.pi_attribute,
        "previous_interaction_count": (
            result.previous_interaction_count
        ),
        "new_interaction_count": (
            result.new_interaction_count
        ),
        "attached_interaction_count": (
            result.attached_interaction_count
        ),
        "updated_score": result.updated_score,
        "preserved_previous_results": (
            result.preserved_previous_results
        ),
        "analysis": summarize_pi_analysis_result(
            result.analysis_result
        ),
        "warnings": list(
            result.warnings
        ),
    }


# =============================================================================
# 16. SERIALIZAÇÃO E EXPORTAÇÃO
# =============================================================================

# -----------------------------------------------------------------------------
# 16.1. Imports adicionais
# -----------------------------------------------------------------------------

import csv
import json
from pathlib import Path


# -----------------------------------------------------------------------------
# 16.2. Constantes
# -----------------------------------------------------------------------------

PI_SERIALIZATION_SCHEMA_VERSION: Final[str] = "1.0"

PI_SERIALIZATION_FORMAT_DICT: Final[str] = "dict"
PI_SERIALIZATION_FORMAT_JSON: Final[str] = "json"
PI_SERIALIZATION_FORMAT_TABLE: Final[str] = "table"
PI_SERIALIZATION_FORMAT_CSV: Final[str] = "csv"

SUPPORTED_PI_SERIALIZATION_FORMATS: Final[FrozenSet[str]] = frozenset(
    {
        PI_SERIALIZATION_FORMAT_DICT,
        PI_SERIALIZATION_FORMAT_JSON,
        PI_SERIALIZATION_FORMAT_TABLE,
        PI_SERIALIZATION_FORMAT_CSV,
    }
)

PI_TABLE_LEVEL_INTERACTION: Final[str] = "interaction"
PI_TABLE_LEVEL_RESIDUE: Final[str] = "residue"
PI_TABLE_LEVEL_POSE: Final[str] = "pose"
PI_TABLE_LEVEL_RING: Final[str] = "ring"
PI_TABLE_LEVEL_TYPE: Final[str] = "type"
PI_TABLE_LEVEL_HOTSPOT: Final[str] = "hotspot"

SUPPORTED_PI_TABLE_LEVELS: Final[FrozenSet[str]] = frozenset(
    {
        PI_TABLE_LEVEL_INTERACTION,
        PI_TABLE_LEVEL_RESIDUE,
        PI_TABLE_LEVEL_POSE,
        PI_TABLE_LEVEL_RING,
        PI_TABLE_LEVEL_TYPE,
        PI_TABLE_LEVEL_HOTSPOT,
    }
)

PI_SERIALIZATION_RECURSION_MARKER: Final[str] = "<recursive-reference>"
PI_SERIALIZATION_UNSUPPORTED_MARKER: Final[str] = "<unsupported-object>"


# -----------------------------------------------------------------------------
# 16.3. Exceções
# -----------------------------------------------------------------------------

class PiSerializationError(RuntimeError):
    """
    Base exception for π-result serialization and export.
    """


class PiSerializationValidationError(PiSerializationError):
    """
    Raised when serialization configuration is invalid.
    """


class PiExportError(PiSerializationError):
    """
    Raised when a serialized result cannot be exported.
    """


# -----------------------------------------------------------------------------
# 16.4. Configuração
# -----------------------------------------------------------------------------

@dataclass(slots=True)
class PiSerializationConfig:
    """
    Configuration for safe serialization and export.
    """

    include_interactions: bool = True
    include_atomic_contacts: bool = True
    include_score_components: bool = True
    include_metadata: bool = True
    include_intermediate_results: bool = False

    include_raw_objects: bool = False
    include_empty_values: bool = True
    include_private_attributes: bool = False

    convert_vectors_to_lists: bool = True
    convert_sets_to_lists: bool = True
    sort_mapping_keys: bool = False

    maximum_depth: int = 20
    numeric_precision: Optional[int] = 6

    json_indent: Optional[int] = 2
    json_sort_keys: bool = False
    json_ensure_ascii: bool = False
    json_allow_nan: bool = False

    table_flatten_nested_values: bool = True
    table_nested_value_separator: str = "; "
    table_sequence_separator: str = "; "

    csv_delimiter: str = ","
    csv_encoding: str = "utf-8"
    csv_line_terminator: str = "\n"

    def __post_init__(self) -> None:
        try:
            self.maximum_depth = int(
                self.maximum_depth
            )

        except (TypeError, ValueError) as exc:
            raise PiSerializationValidationError(
                "maximum_depth must be an integer."
            ) from exc

        if self.maximum_depth < 1:
            raise PiSerializationValidationError(
                "maximum_depth must be at least 1."
            )

        if self.numeric_precision is not None:
            try:
                self.numeric_precision = int(
                    self.numeric_precision
                )

            except (TypeError, ValueError) as exc:
                raise PiSerializationValidationError(
                    "numeric_precision must be an integer or None."
                ) from exc

            if self.numeric_precision < 0:
                raise PiSerializationValidationError(
                    "numeric_precision cannot be negative."
                )

        if self.json_indent is not None:
            try:
                self.json_indent = int(
                    self.json_indent
                )

            except (TypeError, ValueError) as exc:
                raise PiSerializationValidationError(
                    "json_indent must be an integer or None."
                ) from exc

            if self.json_indent < 0:
                raise PiSerializationValidationError(
                    "json_indent cannot be negative."
                )

        if not isinstance(
            self.csv_delimiter,
            str,
        ) or len(self.csv_delimiter) != 1:
            raise PiSerializationValidationError(
                "csv_delimiter must contain exactly one character."
            )


def create_default_pi_serialization_config() -> PiSerializationConfig:
    """
    Return the canonical serialization configuration.
    """

    return PiSerializationConfig()


# -----------------------------------------------------------------------------
# 16.5. Acesso seguro
# -----------------------------------------------------------------------------

def _pi_serialization_get(
    object_: Any,
    names: Sequence[str],
    default: Any = None,
) -> Any:
    if object_ is None:
        return default

    for name in names:
        if isinstance(object_, Mapping):
            value = object_.get(
                name
            )

        else:
            value = getattr(
                object_,
                name,
                None,
            )

        if value is not None:
            return value

    return default


def _pi_serialization_float(
    value: Any,
    default: Optional[float] = None,
) -> Optional[float]:
    if value is None:
        return default

    try:
        normalized_value = float(
            value
        )

    except (TypeError, ValueError):
        return default

    if not math.isfinite(
        normalized_value
    ):
        return default

    return normalized_value


def _pi_serialization_identifier(
    object_: Any,
    fallback: str,
) -> str:
    value = _pi_serialization_get(
        object_,
        (
            "interaction_id",
            "group_id",
            "hotspot_id",
            "ring_id",
            "system_id",
            "aromatic_system_id",
            "amide_id",
            "atom_id",
            "id",
            "identifier",
        ),
        fallback,
    )

    return str(
        value
    )


def _pi_serialization_interaction_type(
    interaction: Any,
) -> str:
    value = _pi_serialization_get(
        interaction,
        (
            "interaction_type",
            "type",
            "category",
        ),
        "unknown",
    )

    normalized = str(
        value
    ).strip().lower()

    aliases = {
        "pi_pi": "pi-pi",
        "pi–pi": "pi-pi",
        "π–π": "pi-pi",
        "cation_pi": "cation-pi",
        "cation–π": "cation-pi",
        "anion_pi": "anion-pi",
        "anion–π": "anion-pi",
        "amide_pi": "amide-pi",
        "amide–π": "amide-pi",
    }

    return aliases.get(
        normalized,
        normalized,
    )


# -----------------------------------------------------------------------------
# 16.6. Conversão de vetores e valores científicos
# -----------------------------------------------------------------------------

def _pi_serialization_is_numpy_scalar(
    value: Any,
) -> bool:
    module_name = type(
        value
    ).__module__

    return module_name.startswith(
        "numpy"
    ) and hasattr(
        value,
        "item",
    )


def _pi_serialization_is_array_like(
    value: Any,
) -> bool:
    if value is None:
        return False

    if isinstance(
        value,
        (
            str,
            bytes,
            bytearray,
            Mapping,
            list,
            tuple,
            set,
            frozenset,
        ),
    ):
        return False

    if hasattr(
        value,
        "tolist",
    ):
        return True

    module_name = type(
        value
    ).__module__

    return module_name.startswith(
        (
            "numpy",
            "torch",
            "jax",
        )
    )


def _pi_serialization_convert_array(
    value: Any,
) -> Any:
    tolist = getattr(
        value,
        "tolist",
        None,
    )

    if callable(
        tolist
    ):
        try:
            return tolist()

        except Exception:
            pass

    try:
        return list(
            value
        )

    except TypeError:
        return value


def _pi_serialization_round_float(
    value: float,
    *,
    precision: Optional[int],
) -> float:
    if precision is None:
        return float(
            value
        )

    return round(
        float(value),
        precision,
    )


# -----------------------------------------------------------------------------
# 16.7. Conversão recursiva segura
# -----------------------------------------------------------------------------

def make_pi_value_serializable(
    value: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
    _visited: Optional[Set[int]] = None,
    _depth: int = 0,
) -> Any:
    """
    Recursively convert a value into JSON-compatible Python objects.

    Supported conversions include:

    - dataclasses to dictionaries;
    - mappings to dictionaries;
    - tuples and sets to lists;
    - NumPy arrays and vectors to lists;
    - NumPy scalars to native Python scalars;
    - objects exposing ``to_dict()``;
    - regular objects exposing ``__dict__``;
    - Path objects to strings;
    - enums to their values.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    if _visited is None:
        _visited = set()

    if _depth > config.maximum_depth:
        return "<maximum-depth-reached>"

    if value is None:
        return None

    if isinstance(
        value,
        bool,
    ):
        return value

    if isinstance(
        value,
        int,
    ):
        return value

    if isinstance(
        value,
        float,
    ):
        if not math.isfinite(
            value
        ):
            if config.json_allow_nan:
                return value

            return None

        return _pi_serialization_round_float(
            value,
            precision=config.numeric_precision,
        )

    if isinstance(
        value,
        str,
    ):
        return value

    if isinstance(
        value,
        (
            bytes,
            bytearray,
        ),
    ):
        try:
            return value.decode(
                "utf-8"
            )

        except UnicodeDecodeError:
            return value.hex()

    if isinstance(
        value,
        Path,
    ):
        return str(
            value
        )

    if isinstance(
        value,
        Enum,
    ):
        return make_pi_value_serializable(
            value.value,
            config=config,
            _visited=_visited,
            _depth=_depth + 1,
        )

    if _pi_serialization_is_numpy_scalar(
        value
    ):
        try:
            native_value = value.item()

        except Exception:
            native_value = repr(
                value
            )

        return make_pi_value_serializable(
            native_value,
            config=config,
            _visited=_visited,
            _depth=_depth + 1,
        )

    object_id = id(
        value
    )

    if object_id in _visited:
        return PI_SERIALIZATION_RECURSION_MARKER

    if _pi_serialization_is_array_like(
        value
    ):
        converted_array = (
            _pi_serialization_convert_array(
                value
            )
        )

        return make_pi_value_serializable(
            converted_array,
            config=config,
            _visited=_visited,
            _depth=_depth + 1,
        )

    if isinstance(
        value,
        Mapping,
    ):
        _visited.add(
            object_id
        )

        items = value.items()

        if config.sort_mapping_keys:
            items = sorted(
                items,
                key=lambda item: str(
                    item[0]
                ),
            )

        result: Dict[str, Any] = {}

        for key, item in items:
            serialized_item = make_pi_value_serializable(
                item,
                config=config,
                _visited=_visited,
                _depth=_depth + 1,
            )

            if (
                serialized_item is None
                and not config.include_empty_values
            ):
                continue

            result[
                str(key)
            ] = serialized_item

        return result

    if isinstance(
        value,
        (
            list,
            tuple,
            set,
            frozenset,
        ),
    ):
        _visited.add(
            object_id
        )

        serialized_items = [
            make_pi_value_serializable(
                item,
                config=config,
                _visited=_visited,
                _depth=_depth + 1,
            )
            for item in value
        ]

        if not config.include_empty_values:
            serialized_items = [
                item
                for item in serialized_items
                if item is not None
            ]

        return serialized_items

    if is_dataclass(
        value
    ):
        _visited.add(
            object_id
        )

        result: Dict[str, Any] = {}

        for field_definition in fields(
            value
        ):
            field_name = field_definition.name

            if (
                field_name.startswith("_")
                and not config.include_private_attributes
            ):
                continue

            if (
                field_name == "interaction"
                and not config.include_raw_objects
            ):
                continue

            if (
                field_name == "interactions"
                and not config.include_interactions
            ):
                continue

            if (
                field_name == "atomic_contacts"
                and not config.include_atomic_contacts
            ):
                continue

            if (
                field_name == "score_components"
                and not config.include_score_components
            ):
                continue

            if (
                field_name == "metadata"
                and not config.include_metadata
            ):
                continue

            if (
                field_name == "intermediate_results"
                and not config.include_intermediate_results
            ):
                continue

            field_value = getattr(
                value,
                field_name,
            )

            serialized_value = make_pi_value_serializable(
                field_value,
                config=config,
                _visited=_visited,
                _depth=_depth + 1,
            )

            if (
                serialized_value is None
                and not config.include_empty_values
            ):
                continue

            result[
                field_name
            ] = serialized_value

        return result

    to_dict = getattr(
        value,
        "to_dict",
        None,
    )

    if callable(
        to_dict
    ):
        try:
            converted = to_dict()

        except TypeError:
            try:
                converted = to_dict(
                    include_interactions=(
                        config.include_interactions
                    )
                )

            except Exception:
                converted = None

        except Exception:
            converted = None

        if converted is not None:
            _visited.add(
                object_id
            )

            return make_pi_value_serializable(
                converted,
                config=config,
                _visited=_visited,
                _depth=_depth + 1,
            )

    if hasattr(
        value,
        "__dict__",
    ):
        _visited.add(
            object_id
        )

        object_mapping = {
            key: item
            for key, item in vars(
                value
            ).items()
            if (
                config.include_private_attributes
                or not str(key).startswith("_")
            )
        }

        return make_pi_value_serializable(
            object_mapping,
            config=config,
            _visited=_visited,
            _depth=_depth + 1,
        )

    return repr(
        value
    )


# -----------------------------------------------------------------------------
# 16.8. Serialização de átomos e contatos
# -----------------------------------------------------------------------------

def pi_atom_to_dict(
    atom: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> Dict[str, Any]:
    """
    Convert an atom-like object into a compact dictionary.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    coordinate = _pi_serialization_get(
        atom,
        (
            "coordinate",
            "coordinates",
            "coord",
            "position",
            "xyz",
        ),
    )

    result = {
        "atom_id": _pi_serialization_identifier(
            atom,
            str(id(atom)),
        ),
        "name": _pi_serialization_get(
            atom,
            (
                "name",
                "atom_name",
            ),
        ),
        "element": _pi_serialization_get(
            atom,
            (
                "element",
                "symbol",
            ),
        ),
        "index": _pi_serialization_get(
            atom,
            (
                "index",
                "atom_index",
                "serial",
            ),
        ),
        "residue_name": _pi_serialization_get(
            atom,
            (
                "residue_name",
                "resname",
            ),
        ),
        "residue_number": _pi_serialization_get(
            atom,
            (
                "residue_number",
                "resid",
                "residue_index",
            ),
        ),
        "chain_id": _pi_serialization_get(
            atom,
            (
                "chain_id",
                "chain",
            ),
        ),
        "formal_charge": _pi_serialization_get(
            atom,
            (
                "formal_charge",
                "charge",
            ),
        ),
        "partial_charge": _pi_serialization_get(
            atom,
            ("partial_charge",),
        ),
        "coordinates": make_pi_value_serializable(
            coordinate,
            config=config,
        ),
    }

    return {
        key: value
        for key, value in result.items()
        if (
            config.include_empty_values
            or value is not None
        )
    }


def pi_atomic_contact_to_dict(
    contact: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> Dict[str, Any]:
    """
    Convert an atomic-contact object into a dictionary.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    atom_1 = _pi_serialization_get(
        contact,
        ("atom_1",),
    )

    atom_2 = _pi_serialization_get(
        contact,
        ("atom_2",),
    )

    result = {
        "atom_1": (
            None
            if atom_1 is None
            else pi_atom_to_dict(
                atom_1,
                config=config,
            )
        ),
        "atom_2": (
            None
            if atom_2 is None
            else pi_atom_to_dict(
                atom_2,
                config=config,
            )
        ),
        "distance": _pi_serialization_float(
            _pi_serialization_get(
                contact,
                ("distance",),
            )
        ),
        "contact_type": _pi_serialization_get(
            contact,
            (
                "contact_type",
                "type",
            ),
        ),
        "metadata": (
            make_pi_value_serializable(
                _pi_serialization_get(
                    contact,
                    ("metadata",),
                    {},
                ),
                config=config,
            )
            if config.include_metadata
            else None
        ),
    }

    return {
        key: value
        for key, value in result.items()
        if (
            config.include_empty_values
            or value is not None
        )
    }


# -----------------------------------------------------------------------------
# 16.9. Serialização dos participantes
# -----------------------------------------------------------------------------

def pi_participant_to_dict(
    participant: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> Optional[Dict[str, Any]]:
    """
    Convert a ring, charged group or amide group into a compact dictionary.
    """

    if participant is None:
        return None

    if config is None:
        config = create_default_pi_serialization_config()

    atoms = _pi_serialization_get(
        participant,
        ("atoms",),
        (),
    )

    centroid = _pi_serialization_get(
        participant,
        (
            "centroid",
            "center",
            "geometric_center",
            "charge_center",
        ),
    )

    normal = _pi_serialization_get(
        participant,
        (
            "normal",
            "plane_normal",
            "normal_vector",
        ),
    )

    result = {
        "participant_id": _pi_serialization_identifier(
            participant,
            str(id(participant)),
        ),
        "participant_type": _pi_serialization_get(
            participant,
            (
                "participant_type",
                "source_type",
                "molecule_type",
                "role",
                "group_type",
                "chemical_type",
            ),
        ),
        "residue_id": _pi_serialization_get(
            participant,
            (
                "residue_id",
                "residue_key",
            ),
        ),
        "residue_name": _pi_serialization_get(
            participant,
            (
                "residue_name",
                "resname",
            ),
        ),
        "residue_number": _pi_serialization_get(
            participant,
            (
                "residue_number",
                "resid",
                "residue_index",
            ),
        ),
        "chain_id": _pi_serialization_get(
            participant,
            (
                "chain_id",
                "chain",
            ),
        ),
        "pose_id": _pi_serialization_get(
            participant,
            (
                "pose_id",
                "pose",
                "model_id",
                "state_id",
            ),
        ),
        "centroid": make_pi_value_serializable(
            centroid,
            config=config,
        ),
        "normal": make_pi_value_serializable(
            normal,
            config=config,
        ),
        "planarity": _pi_serialization_get(
            participant,
            (
                "planarity",
                "planarity_rmsd",
            ),
        ),
        "effective_charge": _pi_serialization_get(
            participant,
            (
                "effective_charge",
                "charge",
            ),
        ),
        "atom_count": (
            len(atoms)
            if atoms is not None
            else 0
        ),
        "atoms": (
            [
                pi_atom_to_dict(
                    atom,
                    config=config,
                )
                for atom in atoms
            ]
            if (
                config.include_raw_objects
                and atoms is not None
            )
            else None
        ),
        "metadata": (
            make_pi_value_serializable(
                _pi_serialization_get(
                    participant,
                    ("metadata",),
                    {},
                ),
                config=config,
            )
            if config.include_metadata
            else None
        ),
    }

    return {
        key: value
        for key, value in result.items()
        if (
            config.include_empty_values
            or value is not None
        )
    }


# -----------------------------------------------------------------------------
# 16.10. Serialização de uma interação
# -----------------------------------------------------------------------------

def pi_interaction_to_dict(
    interaction: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> Dict[str, Any]:
    """
    Convert one π interaction into a stable dictionary schema.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    interaction_type = _pi_serialization_interaction_type(
        interaction
    )

    if "_pi_statistics_participants" in globals():
        try:
            participant_1, participant_2 = (
                _pi_statistics_participants(
                    interaction
                )
            )

        except Exception:
            participant_1 = _pi_serialization_get(
                interaction,
                (
                    "ring_1",
                    "aromatic_system",
                    "ring",
                ),
            )

            participant_2 = _pi_serialization_get(
                interaction,
                (
                    "ring_2",
                    "charged_group",
                    "cation_group",
                    "anion_group",
                    "amide_group",
                ),
            )

    else:
        participant_1 = _pi_serialization_get(
            interaction,
            (
                "ring_1",
                "aromatic_system",
                "ring",
            ),
        )

        participant_2 = _pi_serialization_get(
            interaction,
            (
                "ring_2",
                "charged_group",
                "cation_group",
                "anion_group",
                "amide_group",
            ),
        )

    atomic_contacts = _pi_serialization_get(
        interaction,
        (
            "atomic_contacts",
            "contacts",
        ),
        (),
    )

    score_components = _pi_serialization_get(
        interaction,
        ("score_components",),
    )

    metadata = _pi_serialization_get(
        interaction,
        ("metadata",),
        {},
    )

    result = {
        "interaction_id": _pi_serialization_identifier(
            interaction,
            str(id(interaction)),
        ),
        "interaction_type": interaction_type,
        "geometry_subtype": _pi_serialization_get(
            interaction,
            (
                "geometry_subtype",
                "geometry",
                "subtype",
            ),
            "unclassified",
        ),
        "geometry_class": _pi_serialization_get(
            interaction,
            (
                "global_geometry_class",
                "geometry_quality",
            ),
            "unclassified",
        ),
        "strength_class": _pi_serialization_get(
            interaction,
            (
                "strength_class",
                "strength",
            ),
            "weak",
        ),
        "valid": _pi_serialization_get(
            interaction,
            ("valid",),
            True,
        ),
        "borderline": _pi_serialization_get(
            interaction,
            ("borderline",),
            False,
        ),
        "pose_id": _pi_serialization_get(
            interaction,
            (
                "pose_id",
                "pose",
                "model_id",
                "state_id",
            ),
        ),
        "rank": _pi_serialization_get(
            interaction,
            ("rank",),
        ),
        "score": _pi_serialization_float(
            _pi_serialization_get(
                interaction,
                (
                    "normalized_score",
                    "score",
                ),
            )
        ),
        "raw_score": _pi_serialization_float(
            _pi_serialization_get(
                interaction,
                ("raw_score",),
            )
        ),
        "geometry_confidence": _pi_serialization_float(
            _pi_serialization_get(
                interaction,
                (
                    "geometry_confidence",
                    "confidence",
                ),
            )
        ),
        "centroid_distance": _pi_serialization_float(
            _pi_serialization_get(
                interaction,
                ("centroid_distance",),
            )
        ),
        "minimum_atomic_distance": _pi_serialization_float(
            _pi_serialization_get(
                interaction,
                ("minimum_atomic_distance",),
            )
        ),
        "plane_angle": _pi_serialization_float(
            _pi_serialization_get(
                interaction,
                (
                    "plane_angle",
                    "normal_angle",
                ),
            )
        ),
        "orientation_angle": _pi_serialization_float(
            _pi_serialization_get(
                interaction,
                ("orientation_angle",),
            )
        ),
        "radial_offset": _pi_serialization_float(
            _pi_serialization_get(
                interaction,
                ("radial_offset",),
            )
        ),
        "lateral_offset": _pi_serialization_float(
            _pi_serialization_get(
                interaction,
                ("lateral_offset",),
            )
        ),
        "height": _pi_serialization_float(
            _pi_serialization_get(
                interaction,
                (
                    "height",
                    "absolute_height",
                    "signed_height",
                ),
            )
        ),
        "effective_charge": _pi_serialization_float(
            _pi_serialization_get(
                interaction,
                ("effective_charge",),
            )
        ),
        "charge_source": _pi_serialization_get(
            interaction,
            ("charge_source",),
        ),
        "participant_1": pi_participant_to_dict(
            participant_1,
            config=config,
        ),
        "participant_2": pi_participant_to_dict(
            participant_2,
            config=config,
        ),
        "atomic_contact_count": (
            len(atomic_contacts)
            if atomic_contacts is not None
            else 0
        ),
        "atomic_contacts": (
            [
                pi_atomic_contact_to_dict(
                    contact,
                    config=config,
                )
                for contact in atomic_contacts
            ]
            if (
                config.include_atomic_contacts
                and atomic_contacts is not None
            )
            else None
        ),
        "score_components": (
            make_pi_value_serializable(
                score_components,
                config=config,
            )
            if config.include_score_components
            else None
        ),
        "penalties": make_pi_value_serializable(
            _pi_serialization_get(
                interaction,
                ("penalties",),
                {},
            ),
            config=config,
        ),
        "warnings": make_pi_value_serializable(
            _pi_serialization_get(
                interaction,
                ("warnings",),
                (),
            ),
            config=config,
        ),
        "metadata": (
            make_pi_value_serializable(
                metadata,
                config=config,
            )
            if config.include_metadata
            else None
        ),
    }

    return {
        key: make_pi_value_serializable(
            value,
            config=config,
        )
        for key, value in result.items()
        if (
            config.include_empty_values
            or value is not None
        )
    }


# -----------------------------------------------------------------------------
# 16.11. Serialização do resultado completo
# -----------------------------------------------------------------------------

def pi_result_to_dict(
    result: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> Dict[str, Any]:
    """
    Convert a π-analysis, grouping, statistics or integration result to dict.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    if isinstance(
        result,
        PiAnalysisResult,
    ):
        interactions = (
            [
                pi_interaction_to_dict(
                    interaction,
                    config=config,
                )
                for interaction in result.interactions
            ]
            if config.include_interactions
            else None
        )

        serialized = {
            "schema": "pi-analysis-result",
            "schema_version": (
                PI_SERIALIZATION_SCHEMA_VERSION
            ),
            "analysis_id": result.analysis_id,
            "analysis_mode": result.analysis_mode,
            "pose_id": result.pose_id,
            "success": result.success,
            "completed_stage": result.completed_stage,
            "total_interactions": result.total_interactions,
            "total_score": result.total_score,
            "normalized_score": result.normalized_score,
            "recognized_features": (
                result.recognized_features.to_dict(
                    include_objects=False
                )
            ),
            "detected_interactions": (
                result.detected_interactions.to_dict(
                    include_objects=False
                )
            ),
            "interactions": interactions,
            "consolidation": make_pi_value_serializable(
                result.consolidated_result,
                config=config,
            ),
            "grouping": make_pi_value_serializable(
                result.grouping_result,
                config=config,
            ),
            "statistics": make_pi_value_serializable(
                result.statistics_report,
                config=config,
            ),
            "warnings": list(
                result.warnings
            ),
            "errors": list(
                result.errors
            ),
            "metadata": (
                make_pi_value_serializable(
                    result.metadata,
                    config=config,
                )
                if config.include_metadata
                else None
            ),
            "intermediate_results": (
                make_pi_value_serializable(
                    result.intermediate_results,
                    config=config,
                )
                if config.include_intermediate_results
                else None
            ),
        }

    elif isinstance(
        result,
        PiMultiplePoseAnalysisResult,
    ):
        serialized = {
            "schema": "pi-multipose-analysis-result",
            "schema_version": (
                PI_SERIALIZATION_SCHEMA_VERSION
            ),
            "analysis_id": result.analysis_id,
            "analysis_mode": "multipose",
            "success": result.success,
            "partial_success": result.partial_success,
            "pose_count": result.pose_count,
            "successful_pose_count": (
                result.successful_pose_count
            ),
            "failed_pose_count": result.failed_pose_count,
            "best_pose_id": result.best_pose_id,
            "total_interactions": result.total_interactions,
            "pose_results": [
                pi_result_to_dict(
                    pose_result,
                    config=config,
                )
                for pose_result in result.pose_results
            ],
            "interactions": (
                [
                    pi_interaction_to_dict(
                        interaction,
                        config=config,
                    )
                    for interaction in result.interactions
                ]
                if config.include_interactions
                else None
            ),
            "grouping": make_pi_value_serializable(
                result.grouping_result,
                config=config,
            ),
            "statistics": make_pi_value_serializable(
                result.statistics_report,
                config=config,
            ),
            "warnings": list(
                result.warnings
            ),
            "errors": list(
                result.errors
            ),
            "metadata": (
                make_pi_value_serializable(
                    result.metadata,
                    config=config,
                )
                if config.include_metadata
                else None
            ),
        }

    elif isinstance(
        result,
        DockModelPiIntegrationResult,
    ):
        serialized = {
            "schema": "dock-model-pi-integration-result",
            "schema_version": (
                PI_SERIALIZATION_SCHEMA_VERSION
            ),
            "success": result.success,
            "pi_attribute": result.pi_attribute,
            "previous_interaction_count": (
                result.previous_interaction_count
            ),
            "new_interaction_count": (
                result.new_interaction_count
            ),
            "attached_interaction_count": (
                result.attached_interaction_count
            ),
            "previous_score": make_pi_value_serializable(
                result.previous_score,
                config=config,
            ),
            "updated_score": make_pi_value_serializable(
                result.updated_score,
                config=config,
            ),
            "previous_statistics": (
                make_pi_value_serializable(
                    result.previous_statistics,
                    config=config,
                )
            ),
            "updated_statistics": (
                make_pi_value_serializable(
                    result.updated_statistics,
                    config=config,
                )
            ),
            "preserved_previous_results": (
                result.preserved_previous_results
            ),
            "analysis_result": pi_result_to_dict(
                result.analysis_result,
                config=config,
            ),
            "warnings": list(
                result.warnings
            ),
            "metadata": (
                make_pi_value_serializable(
                    result.metadata,
                    config=config,
                )
                if config.include_metadata
                else None
            ),
        }

    elif isinstance(
        result,
        DockModelPiMultipleIntegrationResult,
    ):
        serialized = {
            "schema": "dock-model-pi-multiple-integration-result",
            "schema_version": (
                PI_SERIALIZATION_SCHEMA_VERSION
            ),
            "success": result.success,
            "model_count": result.model_count,
            "successful_model_count": (
                result.successful_model_count
            ),
            "failed_model_count": result.failed_model_count,
            "best_model_index": result.best_model_index,
            "best_pose_id": result.best_pose_id,
            "model_results": [
                pi_result_to_dict(
                    model_result,
                    config=config,
                )
                for model_result in result.model_results
            ],
            "multipose_result": (
                None
                if result.multipose_result is None
                else pi_result_to_dict(
                    result.multipose_result,
                    config=config,
                )
            ),
            "warnings": list(
                result.warnings
            ),
            "errors": list(
                result.errors
            ),
            "metadata": (
                make_pi_value_serializable(
                    result.metadata,
                    config=config,
                )
                if config.include_metadata
                else None
            ),
        }

    elif isinstance(
        result,
        PiStatisticsReport,
    ):
        serialized = result.to_dict(
            include_interactions=False
        )

        serialized["schema"] = "pi-statistics-report"
        serialized["schema_version"] = (
            PI_SERIALIZATION_SCHEMA_VERSION
        )

    elif isinstance(
        result,
        PiGroupingResult,
    ):
        serialized = result.to_dict()

        serialized["schema"] = "pi-grouping-result"
        serialized["schema_version"] = (
            PI_SERIALIZATION_SCHEMA_VERSION
        )

    elif isinstance(
        result,
        PiConsolidationResult,
    ):
        serialized = result.to_dict()

        serialized["schema"] = "pi-consolidation-result"
        serialized["schema_version"] = (
            PI_SERIALIZATION_SCHEMA_VERSION
        )

    elif isinstance(
        result,
        PiInteractionGroup,
    ):
        serialized = result.to_dict()

    elif isinstance(
        result,
        PiHotspot,
    ):
        serialized = result.to_dict()

    elif _pi_serialization_interaction_type(
        result
    ) != "unknown":
        serialized = pi_interaction_to_dict(
            result,
            config=config,
        )

    else:
        converted = make_pi_value_serializable(
            result,
            config=config,
        )

        if isinstance(
            converted,
            Mapping,
        ):
            serialized = dict(
                converted
            )

        else:
            serialized = {
                "value": converted,
            }

    final_result = make_pi_value_serializable(
        serialized,
        config=config,
    )

    if not isinstance(
        final_result,
        Mapping,
    ):
        raise PiSerializationError(
            "Serialized π result did not produce a dictionary."
        )

    return dict(
        final_result
    )


# -----------------------------------------------------------------------------
# 16.12. Serialização para JSON
# -----------------------------------------------------------------------------

def serialize_pi_results(
    result: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> str:
    """
    Serialize π results into a JSON string.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    serialized_dict = pi_result_to_dict(
        result,
        config=config,
    )

    try:
        return json.dumps(
            serialized_dict,
            indent=config.json_indent,
            sort_keys=config.json_sort_keys,
            ensure_ascii=config.json_ensure_ascii,
            allow_nan=config.json_allow_nan,
        )

    except (
        TypeError,
        ValueError,
        OverflowError,
    ) as exc:
        raise PiSerializationError(
            f"Could not serialize π results to JSON: {exc}"
        ) from exc


def save_pi_results_json(
    result: Any,
    output_path: Union[str, Path],
    *,
    config: Optional[PiSerializationConfig] = None,
) -> Path:
    """
    Serialize π results and save them to a JSON file.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    path = Path(
        output_path
    )

    if path.suffix.lower() != ".json":
        path = path.with_suffix(
            ".json"
        )

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    serialized = serialize_pi_results(
        result,
        config=config,
    )

    try:
        path.write_text(
            serialized,
            encoding=config.csv_encoding,
        )

    except OSError as exc:
        raise PiExportError(
            f"Could not write π JSON file {path!s}: {exc}"
        ) from exc

    return path


# -----------------------------------------------------------------------------
# 16.13. Extração das interações
# -----------------------------------------------------------------------------

def extract_pi_interactions(
    result: Any,
) -> List[Any]:
    """
    Extract the active interaction list from any supported result object.
    """

    if result is None:
        return []

    if isinstance(
        result,
        PiAnalysisResult,
    ):
        return list(
            result.interactions
        )

    if isinstance(
        result,
        PiMultiplePoseAnalysisResult,
    ):
        return list(
            result.interactions
        )

    if isinstance(
        result,
        DockModelPiIntegrationResult,
    ):
        return list(
            result.analysis_result.interactions
        )

    if isinstance(
        result,
        DockModelPiMultipleIntegrationResult,
    ):
        if result.multipose_result is not None:
            return list(
                result.multipose_result.interactions
            )

        return [
            interaction
            for model_result in result.model_results
            for interaction in (
                model_result.analysis_result.interactions
            )
        ]

    interactions = _pi_serialization_get(
        result,
        ("interactions",),
    )

    if interactions is not None:
        try:
            return list(
                interactions
            )

        except TypeError:
            return [
                interactions
            ]

    if isinstance(
        result,
        Iterable,
    ) and not isinstance(
        result,
        (
            str,
            bytes,
            Mapping,
        ),
    ):
        return list(
            result
        )

    return []


# -----------------------------------------------------------------------------
# 16.14. Helpers tabulares
# -----------------------------------------------------------------------------

def _pi_table_join(
    value: Any,
    *,
    config: PiSerializationConfig,
) -> Any:
    if value is None:
        return None

    if isinstance(
        value,
        Mapping,
    ):
        if not config.table_flatten_nested_values:
            return json.dumps(
                make_pi_value_serializable(
                    value,
                    config=config,
                ),
                ensure_ascii=False,
                allow_nan=False,
            )

        return config.table_nested_value_separator.join(
            f"{key}={_pi_table_join(item, config=config)}"
            for key, item in value.items()
        )

    if isinstance(
        value,
        (
            list,
            tuple,
            set,
            frozenset,
        ),
    ):
        return config.table_sequence_separator.join(
            str(
                _pi_table_join(
                    item,
                    config=config,
                )
            )
            for item in value
        )

    return value


def _pi_table_participant_summary(
    participant: Any,
) -> Dict[str, Any]:
    if participant is None:
        return {
            "id": None,
            "role": None,
            "residue_id": None,
            "chain_id": None,
        }

    residue_id = _pi_serialization_get(
        participant,
        (
            "residue_id",
            "residue_key",
        ),
    )

    if (
        residue_id is None
        and "_pi_statistics_residue_id" in globals()
    ):
        try:
            residue_id = _pi_statistics_residue_id(
                participant
            )

        except Exception:
            residue_id = None

    return {
        "id": _pi_serialization_identifier(
            participant,
            str(id(participant)),
        ),
        "role": _pi_serialization_get(
            participant,
            (
                "participant_type",
                "source_type",
                "molecule_type",
                "role",
                "group_type",
            ),
        ),
        "residue_id": residue_id,
        "chain_id": _pi_serialization_get(
            participant,
            (
                "chain_id",
                "chain",
            ),
        ),
    }


# -----------------------------------------------------------------------------
# 16.15. Tabela de interações
# -----------------------------------------------------------------------------

def pi_interactions_to_table(
    interactions: Iterable[Any],
    *,
    config: Optional[PiSerializationConfig] = None,
) -> List[Dict[str, Any]]:
    """
    Convert interactions into one flat record per physical interaction.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    records: List[
        Dict[str, Any]
    ] = []

    for interaction in interactions:
        if "_pi_statistics_participants" in globals():
            try:
                participant_1, participant_2 = (
                    _pi_statistics_participants(
                        interaction
                    )
                )

            except Exception:
                participant_1 = None
                participant_2 = None

        else:
            participant_1 = _pi_serialization_get(
                interaction,
                (
                    "ring_1",
                    "aromatic_system",
                    "ring",
                ),
            )

            participant_2 = _pi_serialization_get(
                interaction,
                (
                    "ring_2",
                    "charged_group",
                    "cation_group",
                    "anion_group",
                    "amide_group",
                ),
            )

        participant_1_summary = (
            _pi_table_participant_summary(
                participant_1
            )
        )

        participant_2_summary = (
            _pi_table_participant_summary(
                participant_2
            )
        )

        contacts = _pi_serialization_get(
            interaction,
            (
                "atomic_contacts",
                "contacts",
            ),
            (),
        )

        penalties = _pi_serialization_get(
            interaction,
            ("penalties",),
            {},
        )

        record = {
            "interaction_id": (
                _pi_serialization_identifier(
                    interaction,
                    str(id(interaction)),
                )
            ),
            "pose_id": _pi_serialization_get(
                interaction,
                (
                    "pose_id",
                    "pose",
                    "model_id",
                    "state_id",
                ),
            ),
            "interaction_type": (
                _pi_serialization_interaction_type(
                    interaction
                )
            ),
            "geometry_subtype": (
                _pi_serialization_get(
                    interaction,
                    (
                        "geometry_subtype",
                        "geometry",
                        "subtype",
                    ),
                    "unclassified",
                )
            ),
            "geometry_class": (
                _pi_serialization_get(
                    interaction,
                    (
                        "global_geometry_class",
                        "geometry_quality",
                    ),
                    "unclassified",
                )
            ),
            "strength_class": (
                _pi_serialization_get(
                    interaction,
                    (
                        "strength_class",
                        "strength",
                    ),
                    "weak",
                )
            ),
            "rank": _pi_serialization_get(
                interaction,
                ("rank",),
            ),
            "score": _pi_serialization_float(
                _pi_serialization_get(
                    interaction,
                    (
                        "normalized_score",
                        "score",
                    ),
                )
            ),
            "raw_score": _pi_serialization_float(
                _pi_serialization_get(
                    interaction,
                    ("raw_score",),
                )
            ),
            "confidence": _pi_serialization_float(
                _pi_serialization_get(
                    interaction,
                    (
                        "geometry_confidence",
                        "confidence",
                    ),
                )
            ),
            "centroid_distance": (
                _pi_serialization_float(
                    _pi_serialization_get(
                        interaction,
                        ("centroid_distance",),
                    )
                )
            ),
            "minimum_atomic_distance": (
                _pi_serialization_float(
                    _pi_serialization_get(
                        interaction,
                        ("minimum_atomic_distance",),
                    )
                )
            ),
            "plane_angle": _pi_serialization_float(
                _pi_serialization_get(
                    interaction,
                    (
                        "plane_angle",
                        "normal_angle",
                    ),
                )
            ),
            "orientation_angle": (
                _pi_serialization_float(
                    _pi_serialization_get(
                        interaction,
                        ("orientation_angle",),
                    )
                )
            ),
            "radial_offset": _pi_serialization_float(
                _pi_serialization_get(
                    interaction,
                    ("radial_offset",),
                )
            ),
            "lateral_offset": _pi_serialization_float(
                _pi_serialization_get(
                    interaction,
                    ("lateral_offset",),
                )
            ),
            "effective_charge": (
                _pi_serialization_float(
                    _pi_serialization_get(
                        interaction,
                        ("effective_charge",),
                    )
                )
            ),
            "participant_1_id": (
                participant_1_summary["id"]
            ),
            "participant_1_role": (
                participant_1_summary["role"]
            ),
            "participant_1_residue": (
                participant_1_summary["residue_id"]
            ),
            "participant_1_chain": (
                participant_1_summary["chain_id"]
            ),
            "participant_2_id": (
                participant_2_summary["id"]
            ),
            "participant_2_role": (
                participant_2_summary["role"]
            ),
            "participant_2_residue": (
                participant_2_summary["residue_id"]
            ),
            "participant_2_chain": (
                participant_2_summary["chain_id"]
            ),
            "atomic_contact_count": (
                len(contacts)
                if contacts is not None
                else 0
            ),
            "penalty_total": (
                sum(
                    float(value)
                    for value in penalties.values()
                    if _pi_serialization_float(
                        value
                    )
                    is not None
                )
                if isinstance(
                    penalties,
                    Mapping,
                )
                else None
            ),
            "penalties": _pi_table_join(
                make_pi_value_serializable(
                    penalties,
                    config=config,
                ),
                config=config,
            ),
        }

        records.append(
            {
                key: _pi_table_join(
                    make_pi_value_serializable(
                        value,
                        config=config,
                    ),
                    config=config,
                )
                for key, value in record.items()
                if (
                    config.include_empty_values
                    or value is not None
                )
            }
        )

    return records


# -----------------------------------------------------------------------------
# 16.16. Resumo por resíduo
# -----------------------------------------------------------------------------

def pi_residue_summary_table(
    result_or_interactions: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> List[Dict[str, Any]]:
    """
    Produce one summary row per involved residue.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    interactions = extract_pi_interactions(
        result_or_interactions
    )

    if "calculate_pi_statistics_by_residue" in globals():
        try:
            summaries = calculate_pi_statistics_by_residue(
                interactions,
                precision=(
                    config.numeric_precision
                    if config.numeric_precision is not None
                    else 6
                ),
            )

        except Exception:
            summaries = {}

    else:
        summaries = {}

    records: List[
        Dict[str, Any]
    ] = []

    for residue_id, summary in summaries.items():
        chain_id = (
            residue_id.split(
                ":",
                1,
            )[0]
            if ":" in residue_id
            else None
        )

        best = summary.get(
            "best_interaction"
        )

        record = {
            "residue_id": residue_id,
            "chain_id": chain_id,
            "interaction_count": summary.get(
                "interaction_count",
                0,
            ),
            "atomic_contact_count": summary.get(
                "atomic_contact_count",
                0,
            ),
            "total_score": summary.get(
                "total_score",
                0.0,
            ),
            "mean_score": summary.get(
                "mean_score",
                0.0,
            ),
            "maximum_score": summary.get(
                "maximum_score",
                0.0,
            ),
            "minimum_score": summary.get(
                "minimum_score",
                0.0,
            ),
            "interaction_types": _pi_table_join(
                summary.get(
                    "type_distribution",
                    {},
                ),
                config=config,
            ),
            "geometric_subtypes": _pi_table_join(
                summary.get(
                    "subtype_distribution",
                    {},
                ),
                config=config,
            ),
            "strength_distribution": _pi_table_join(
                summary.get(
                    "strength_distribution",
                    {},
                ),
                config=config,
            ),
            "mean_centroid_distance": (
                summary.get(
                    "centroid_distance",
                    {},
                ).get(
                    "mean"
                )
            ),
            "minimum_centroid_distance": (
                summary.get(
                    "centroid_distance",
                    {},
                ).get(
                    "minimum"
                )
            ),
            "maximum_centroid_distance": (
                summary.get(
                    "centroid_distance",
                    {},
                ).get(
                    "maximum"
                )
            ),
            "best_interaction_id": (
                None
                if not isinstance(
                    best,
                    Mapping,
                )
                else best.get(
                    "interaction_id"
                )
            ),
            "best_interaction_type": (
                None
                if not isinstance(
                    best,
                    Mapping,
                )
                else best.get(
                    "interaction_type"
                )
            ),
            "best_interaction_score": (
                None
                if not isinstance(
                    best,
                    Mapping,
                )
                else best.get(
                    "score"
                )
            ),
        }

        records.append(
            record
        )

    return records


# -----------------------------------------------------------------------------
# 16.17. Resumo por pose
# -----------------------------------------------------------------------------

def pi_pose_summary_table(
    result_or_interactions: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> List[Dict[str, Any]]:
    """
    Produce one summary row per docking pose.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    interactions = extract_pi_interactions(
        result_or_interactions
    )

    if "calculate_pi_statistics_by_pose" in globals():
        try:
            summaries = calculate_pi_statistics_by_pose(
                interactions,
                precision=(
                    config.numeric_precision
                    if config.numeric_precision is not None
                    else 6
                ),
            )

        except Exception:
            summaries = {}

    else:
        summaries = {}

    records: List[
        Dict[str, Any]
    ] = []

    for pose_id, summary in summaries.items():
        best = summary.get(
            "best_interaction"
        )

        record = {
            "pose_id": pose_id,
            "interaction_count": summary.get(
                "interaction_count",
                0,
            ),
            "atomic_contact_count": summary.get(
                "atomic_contact_count",
                0,
            ),
            "total_score": summary.get(
                "total_score",
                0.0,
            ),
            "mean_score": summary.get(
                "mean_score",
                0.0,
            ),
            "maximum_score": summary.get(
                "maximum_score",
                0.0,
            ),
            "minimum_score": summary.get(
                "minimum_score",
                0.0,
            ),
            "interaction_types": _pi_table_join(
                summary.get(
                    "type_distribution",
                    {},
                ),
                config=config,
            ),
            "geometric_subtypes": _pi_table_join(
                summary.get(
                    "subtype_distribution",
                    {},
                ),
                config=config,
            ),
            "strength_distribution": _pi_table_join(
                summary.get(
                    "strength_distribution",
                    {},
                ),
                config=config,
            ),
            "mean_centroid_distance": (
                summary.get(
                    "centroid_distance",
                    {},
                ).get(
                    "mean"
                )
            ),
            "minimum_centroid_distance": (
                summary.get(
                    "centroid_distance",
                    {},
                ).get(
                    "minimum"
                )
            ),
            "maximum_centroid_distance": (
                summary.get(
                    "centroid_distance",
                    {},
                ).get(
                    "maximum"
                )
            ),
            "best_interaction_id": (
                None
                if not isinstance(
                    best,
                    Mapping,
                )
                else best.get(
                    "interaction_id"
                )
            ),
            "best_interaction_type": (
                None
                if not isinstance(
                    best,
                    Mapping,
                )
                else best.get(
                    "interaction_type"
                )
            ),
            "best_interaction_score": (
                None
                if not isinstance(
                    best,
                    Mapping,
                )
                else best.get(
                    "score"
                )
            ),
        }

        records.append(
            record
        )

    return records


# -----------------------------------------------------------------------------
# 16.18. Resumo por tipo e anel
# -----------------------------------------------------------------------------

def pi_type_summary_table(
    result_or_interactions: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> List[Dict[str, Any]]:
    """
    Produce one summary row per interaction type.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    interactions = extract_pi_interactions(
        result_or_interactions
    )

    if "calculate_pi_statistics_by_type" in globals():
        summaries = calculate_pi_statistics_by_type(
            interactions,
            precision=(
                config.numeric_precision
                if config.numeric_precision is not None
                else 6
            ),
        )

    else:
        summaries = {}

    return [
        {
            "interaction_type": interaction_type,
            **{
                key: _pi_table_join(
                    value,
                    config=config,
                )
                for key, value in summary.items()
            },
        }
        for interaction_type, summary in summaries.items()
    ]


def pi_ring_summary_table(
    result_or_interactions: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> List[Dict[str, Any]]:
    """
    Produce one summary row per aromatic system.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    interactions = extract_pi_interactions(
        result_or_interactions
    )

    if "calculate_pi_statistics_by_ring" in globals():
        summaries = calculate_pi_statistics_by_ring(
            interactions,
            precision=(
                config.numeric_precision
                if config.numeric_precision is not None
                else 6
            ),
        )

    else:
        summaries = {}

    return [
        {
            "ring_id": ring_id,
            **{
                key: _pi_table_join(
                    value,
                    config=config,
                )
                for key, value in summary.items()
            },
        }
        for ring_id, summary in summaries.items()
    ]


# -----------------------------------------------------------------------------
# 16.19. Tabela de hotspots
# -----------------------------------------------------------------------------

def pi_hotspot_summary_table(
    result: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> List[Dict[str, Any]]:
    """
    Convert hotspot results into flat records.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    hotspots = _pi_serialization_get(
        result,
        ("hotspots",),
    )

    if hotspots is None:
        statistics_report = _pi_serialization_get(
            result,
            ("statistics_report",),
        )

        hotspots = _pi_serialization_get(
            statistics_report,
            ("hotspots",),
            (),
        )

    records: List[
        Dict[str, Any]
    ] = []

    for hotspot in hotspots or ():
        record = {
            "hotspot_id": _pi_serialization_get(
                hotspot,
                ("hotspot_id",),
            ),
            "hotspot_key": _pi_serialization_get(
                hotspot,
                ("hotspot_key",),
            ),
            "hotspot_level": _pi_serialization_get(
                hotspot,
                ("hotspot_level",),
            ),
            "residue_id": _pi_serialization_get(
                hotspot,
                ("residue_id",),
            ),
            "chain_id": _pi_serialization_get(
                hotspot,
                ("chain_id",),
            ),
            "interaction_count": _pi_serialization_get(
                hotspot,
                ("interaction_count",),
                0,
            ),
            "total_score": _pi_serialization_get(
                hotspot,
                ("total_score",),
                0.0,
            ),
            "mean_score": _pi_serialization_get(
                hotspot,
                ("mean_score",),
                0.0,
            ),
            "maximum_score": _pi_serialization_get(
                hotspot,
                ("maximum_score",),
                0.0,
            ),
            "strong_count": _pi_serialization_get(
                hotspot,
                ("strong_count",),
                0,
            ),
            "moderate_count": _pi_serialization_get(
                hotspot,
                ("moderate_count",),
                0,
            ),
            "weak_count": _pi_serialization_get(
                hotspot,
                ("weak_count",),
                0,
            ),
            "interaction_types": _pi_table_join(
                _pi_serialization_get(
                    hotspot,
                    ("interaction_types",),
                    (),
                ),
                config=config,
            ),
            "geometric_subtypes": _pi_table_join(
                _pi_serialization_get(
                    hotspot,
                    ("geometric_subtypes",),
                    (),
                ),
                config=config,
            ),
            "pose_ids": _pi_table_join(
                _pi_serialization_get(
                    hotspot,
                    ("pose_ids",),
                    (),
                ),
                config=config,
            ),
            "ring_ids": _pi_table_join(
                _pi_serialization_get(
                    hotspot,
                    ("ring_ids",),
                    (),
                ),
                config=config,
            ),
        }

        records.append(
            record
        )

    return records


# -----------------------------------------------------------------------------
# 16.20. API tabular genérica
# -----------------------------------------------------------------------------

def pi_results_to_table(
    result: Any,
    *,
    level: str = PI_TABLE_LEVEL_INTERACTION,
    config: Optional[PiSerializationConfig] = None,
) -> List[Dict[str, Any]]:
    """
    Convert π results into a selected tabular representation.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    level = str(
        level
    ).strip().lower()

    if level not in SUPPORTED_PI_TABLE_LEVELS:
        raise PiSerializationValidationError(
            f"Unsupported π table level: {level!r}."
        )

    if level == PI_TABLE_LEVEL_INTERACTION:
        return pi_interactions_to_table(
            extract_pi_interactions(
                result
            ),
            config=config,
        )

    if level == PI_TABLE_LEVEL_RESIDUE:
        return pi_residue_summary_table(
            result,
            config=config,
        )

    if level == PI_TABLE_LEVEL_POSE:
        return pi_pose_summary_table(
            result,
            config=config,
        )

    if level == PI_TABLE_LEVEL_RING:
        return pi_ring_summary_table(
            result,
            config=config,
        )

    if level == PI_TABLE_LEVEL_TYPE:
        return pi_type_summary_table(
            result,
            config=config,
        )

    return pi_hotspot_summary_table(
        result,
        config=config,
    )


# -----------------------------------------------------------------------------
# 16.21. Exportação CSV
# -----------------------------------------------------------------------------

def save_pi_table_csv(
    records: Iterable[Mapping[str, Any]],
    output_path: Union[str, Path],
    *,
    config: Optional[PiSerializationConfig] = None,
) -> Path:
    """
    Save a collection of flat mappings as CSV.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    record_list = [
        dict(record)
        for record in records
    ]

    path = Path(
        output_path
    )

    if path.suffix.lower() != ".csv":
        path = path.with_suffix(
            ".csv"
        )

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    field_names: List[str] = []

    for record in record_list:
        for key in record:
            if key not in field_names:
                field_names.append(
                    key
                )

    try:
        with path.open(
            "w",
            encoding=config.csv_encoding,
            newline="",
        ) as file_handle:
            writer = csv.DictWriter(
                file_handle,
                fieldnames=field_names,
                delimiter=config.csv_delimiter,
                lineterminator=(
                    config.csv_line_terminator
                ),
                extrasaction="ignore",
            )

            writer.writeheader()

            for record in record_list:
                writer.writerow(
                    {
                        key: _pi_table_join(
                            make_pi_value_serializable(
                                value,
                                config=config,
                            ),
                            config=config,
                        )
                        for key, value in record.items()
                    }
                )

    except OSError as exc:
        raise PiExportError(
            f"Could not write π CSV file {path!s}: {exc}"
        ) from exc

    return path


def export_pi_results_csv(
    result: Any,
    output_path: Union[str, Path],
    *,
    level: str = PI_TABLE_LEVEL_INTERACTION,
    config: Optional[PiSerializationConfig] = None,
) -> Path:
    """
    Convert π results to a table and export them as CSV.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    records = pi_results_to_table(
        result,
        level=level,
        config=config,
    )

    return save_pi_table_csv(
        records,
        output_path,
        config=config,
    )


# -----------------------------------------------------------------------------
# 16.22. Pacote de exportação
# -----------------------------------------------------------------------------

@dataclass(slots=True)
class PiExportBundle:
    """
    Collection of serializable π-analysis representations.
    """

    result: Dict[str, Any]

    interaction_table: List[Dict[str, Any]]
    residue_table: List[Dict[str, Any]]
    pose_table: List[Dict[str, Any]]
    ring_table: List[Dict[str, Any]]
    type_table: List[Dict[str, Any]]
    hotspot_table: List[Dict[str, Any]]

    general_report: Dict[str, Any]

    metadata: Dict[str, Any] = field(
        default_factory=dict
    )

    def to_dict(self) -> Dict[str, Any]:
        return {
            "result": self.result,
            "tables": {
                "interactions": self.interaction_table,
                "residues": self.residue_table,
                "poses": self.pose_table,
                "rings": self.ring_table,
                "types": self.type_table,
                "hotspots": self.hotspot_table,
            },
            "general_report": self.general_report,
            "metadata": dict(
                self.metadata
            ),
        }


def create_pi_export_bundle(
    result: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> PiExportBundle:
    """
    Create all principal export representations at once.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    serialized_result = pi_result_to_dict(
        result,
        config=config,
    )

    general_report = create_pi_general_report_section(
        result,
        config=config,
    )

    return PiExportBundle(
        result=serialized_result,
        interaction_table=pi_results_to_table(
            result,
            level=PI_TABLE_LEVEL_INTERACTION,
            config=config,
        ),
        residue_table=pi_results_to_table(
            result,
            level=PI_TABLE_LEVEL_RESIDUE,
            config=config,
        ),
        pose_table=pi_results_to_table(
            result,
            level=PI_TABLE_LEVEL_POSE,
            config=config,
        ),
        ring_table=pi_results_to_table(
            result,
            level=PI_TABLE_LEVEL_RING,
            config=config,
        ),
        type_table=pi_results_to_table(
            result,
            level=PI_TABLE_LEVEL_TYPE,
            config=config,
        ),
        hotspot_table=pi_results_to_table(
            result,
            level=PI_TABLE_LEVEL_HOTSPOT,
            config=config,
        ),
        general_report=general_report,
        metadata={
            "schema": "pi-export-bundle",
            "schema_version": (
                PI_SERIALIZATION_SCHEMA_VERSION
            ),
        },
    )


# -----------------------------------------------------------------------------
# 16.23. Integração com relatórios gerais
# -----------------------------------------------------------------------------

def _pi_serialization_resolve_statistics_report(
    result: Any,
) -> Optional[Any]:
    if isinstance(
        result,
        PiStatisticsReport,
    ):
        return result

    if isinstance(
        result,
        PiAnalysisResult,
    ):
        return result.statistics_report

    if isinstance(
        result,
        PiMultiplePoseAnalysisResult,
    ):
        return result.statistics_report

    if isinstance(
        result,
        DockModelPiIntegrationResult,
    ):
        return result.analysis_result.statistics_report

    if isinstance(
        result,
        DockModelPiMultipleIntegrationResult,
    ):
        if result.multipose_result is not None:
            return result.multipose_result.statistics_report

    return _pi_serialization_get(
        result,
        (
            "statistics_report",
            "pi_statistics",
            "statistics",
        ),
    )


def create_pi_general_report_section(
    result: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> Dict[str, Any]:
    """
    Create a compact π section suitable for a general interaction report.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    statistics_report = (
        _pi_serialization_resolve_statistics_report(
            result
        )
    )

    interactions = extract_pi_interactions(
        result
    )

    if statistics_report is not None:
        total_interactions = _pi_serialization_get(
            statistics_report,
            ("total_interactions",),
            len(interactions),
        )

        total_score = _pi_serialization_get(
            statistics_report,
            ("total_score",),
            0.0,
        )

        normalized_score = _pi_serialization_get(
            statistics_report,
            ("normalized_total_score",),
            0.0,
        )

        total_by_type = _pi_serialization_get(
            statistics_report,
            ("total_by_type",),
            {},
        )

        strength_distribution = (
            _pi_serialization_get(
                statistics_report,
                ("strength_distribution",),
                {},
            )
        )

        best_interaction = _pi_serialization_get(
            statistics_report,
            ("best_interaction",),
        )

        predominant_interaction = (
            _pi_serialization_get(
                statistics_report,
                ("predominant_interaction",),
            )
        )

        distance_statistics = (
            _pi_serialization_get(
                statistics_report,
                ("centroid_distance_statistics",),
            )
        )

        hotspots = _pi_serialization_get(
            statistics_report,
            ("hotspots",),
            (),
        )

    else:
        total_interactions = len(
            interactions
        )

        scores = [
            _pi_serialization_float(
                _pi_serialization_get(
                    interaction,
                    (
                        "normalized_score",
                        "score",
                    ),
                ),
                0.0,
            )
            or 0.0
            for interaction in interactions
        ]

        total_score = sum(
            scores
        )

        normalized_score = (
            total_score / len(scores)
            if scores
            else 0.0
        )

        total_by_type: Dict[str, int] = defaultdict(
            int
        )

        strength_distribution: Dict[str, int] = defaultdict(
            int
        )

        for interaction in interactions:
            total_by_type[
                _pi_serialization_interaction_type(
                    interaction
                )
            ] += 1

            strength_distribution[
                str(
                    _pi_serialization_get(
                        interaction,
                        (
                            "strength_class",
                            "strength",
                        ),
                        "weak",
                    )
                )
            ] += 1

        best_interaction = (
            max(
                interactions,
                key=lambda interaction: (
                    _pi_serialization_float(
                        _pi_serialization_get(
                            interaction,
                            (
                                "normalized_score",
                                "score",
                            ),
                        ),
                        0.0,
                    )
                    or 0.0
                ),
            )
            if interactions
            else None
        )

        predominant_interaction = None
        distance_statistics = None
        hotspots = ()

    best_interaction_dict = (
        None
        if best_interaction is None
        else (
            best_interaction.to_dict()
            if hasattr(
                best_interaction,
                "to_dict",
            )
            else pi_interaction_to_dict(
                best_interaction,
                config=replace(
                    config,
                    include_atomic_contacts=False,
                    include_score_components=False,
                    include_metadata=False,
                ),
            )
        )
    )

    predominant_dict = (
        None
        if predominant_interaction is None
        else make_pi_value_serializable(
            predominant_interaction,
            config=config,
        )
    )

    distance_dict = (
        None
        if distance_statistics is None
        else make_pi_value_serializable(
            distance_statistics,
            config=config,
        )
    )

    return {
        "module": "pi",
        "title": "π interactions",
        "schema_version": (
            PI_SERIALIZATION_SCHEMA_VERSION
        ),
        "total_interactions": total_interactions,
        "total_atomic_contacts": sum(
            len(
                _pi_serialization_get(
                    interaction,
                    (
                        "atomic_contacts",
                        "contacts",
                    ),
                    (),
                )
            )
            for interaction in interactions
        ),
        "total_by_type": make_pi_value_serializable(
            total_by_type,
            config=config,
        ),
        "strength_distribution": (
            make_pi_value_serializable(
                strength_distribution,
                config=config,
            )
        ),
        "total_score": total_score,
        "normalized_score": normalized_score,
        "distance_statistics": distance_dict,
        "best_interaction": best_interaction_dict,
        "predominant_interaction": predominant_dict,
        "hotspot_count": len(
            hotspots or ()
        ),
        "hotspots": (
            [
                make_pi_value_serializable(
                    hotspot,
                    config=config,
                )
                for hotspot in hotspots
            ]
            if config.include_interactions
            else None
        ),
    }


def attach_pi_to_general_report(
    general_report: MutableMapping[str, Any],
    pi_result: Any,
    *,
    section_key: str = "pi",
    config: Optional[PiSerializationConfig] = None,
    preserve_existing: bool = True,
) -> MutableMapping[str, Any]:
    """
    Insert the π section into a general DockAnalyzer report.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    section_key = str(
        section_key
    ).strip()

    if not section_key:
        raise PiSerializationValidationError(
            "section_key cannot be empty."
        )

    if (
        preserve_existing
        and section_key in general_report
    ):
        previous_sections = general_report.setdefault(
            "_previous_sections",
            {},
        )

        if isinstance(
            previous_sections,
            MutableMapping,
        ):
            previous_sections[
                section_key
            ] = general_report[
                section_key
            ]

    general_report[
        section_key
    ] = create_pi_general_report_section(
        pi_result,
        config=config,
    )

    return general_report


# -----------------------------------------------------------------------------
# 16.24. Exportação completa para diretório
# -----------------------------------------------------------------------------

def export_pi_results_bundle(
    result: Any,
    output_directory: Union[str, Path],
    *,
    basename: str = "pi_results",
    config: Optional[PiSerializationConfig] = None,
) -> Dict[str, Path]:
    """
    Export JSON and all principal CSV tables to one directory.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    output_directory = Path(
        output_directory
    )

    output_directory.mkdir(
        parents=True,
        exist_ok=True,
    )

    basename = str(
        basename
    ).strip() or "pi_results"

    bundle = create_pi_export_bundle(
        result,
        config=config,
    )

    exported_paths: Dict[
        str,
        Path,
    ] = {}

    exported_paths["json"] = save_pi_results_json(
        bundle.to_dict(),
        output_directory
        / f"{basename}.json",
        config=config,
    )

    table_map = {
        "interactions": bundle.interaction_table,
        "residues": bundle.residue_table,
        "poses": bundle.pose_table,
        "rings": bundle.ring_table,
        "types": bundle.type_table,
        "hotspots": bundle.hotspot_table,
    }

    for table_name, records in table_map.items():
        exported_paths[
            table_name
        ] = save_pi_table_csv(
            records,
            output_directory
            / f"{basename}_{table_name}.csv",
            config=config,
        )

    return exported_paths


# -----------------------------------------------------------------------------
# 16.25. Validação de serialização
# -----------------------------------------------------------------------------

def validate_pi_serialization(
    value: Any,
    *,
    config: Optional[PiSerializationConfig] = None,
) -> Tuple[bool, Optional[str]]:
    """
    Verify that a value can be converted and encoded as strict JSON.
    """

    if config is None:
        config = create_default_pi_serialization_config()

    try:
        serialized = make_pi_value_serializable(
            value,
            config=config,
        )

        json.dumps(
            serialized,
            ensure_ascii=config.json_ensure_ascii,
            allow_nan=False,
        )

    except Exception as exc:
        return (
            False,
            str(exc),
        )

    return (
        True,
        None,
    )


