@dataclass(slots=True)
class MockPiAtom:
    """
    Minimal atom model used by the π-interaction self-tests.

    The attribute aliases intentionally cover the access patterns used by
    Sections 3–17.
    """

    index: int
    name: str
    element: str

    coordinate: Tuple[float, float, float]

    residue_name: str = "LIG"
    residue_number: int = 1
    chain_id: str = "L"

    formal_charge: float = 0.0
    partial_charge: float = 0.0

    aromatic: bool = False
    atom_type: Optional[str] = None

    model_id: Optional[str] = "1"
    pose_id: Optional[str] = None

    bonds: List[Any] = field(
        default_factory=list
    )

    metadata: Dict[str, Any] = field(
        default_factory=dict
    )

    @property
    def coord(self) -> Tuple[float, float, float]:
        return self.coordinate

    @coord.setter
    def coord(
        self,
        value: Sequence[float],
    ) -> None:
        self.coordinate = _pi_test_vector3(
            value
        )

    @property
    def coordinates(
        self,
    ) -> Tuple[float, float, float]:
        return self.coordinate

    @coordinates.setter
    def coordinates(
        self,
        value: Sequence[float],
    ) -> None:
        self.coordinate = _pi_test_vector3(
            value
        )

    @property
    def position(
        self,
    ) -> Tuple[float, float, float]:
        return self.coordinate

    @property
    def xyz(
        self,
    ) -> Tuple[float, float, float]:
        return self.coordinate

    @property
    def residue_id(self) -> str:
        return (
            f"{self.chain_id}:"
            f"{self.residue_name}:"
            f"{self.residue_number}"
        )

    @property
    def atomspec(self) -> str:
        model_prefix = (
            ""
            if self.model_id is None
            else (
                self.model_id
                if str(self.model_id).startswith("#")
                else f"#{self.model_id}"
            )
        )

        return (
            f"{model_prefix}/"
            f"{self.chain_id}:"
            f"{self.residue_number}@"
            f"{self.name}"
        )

    def distance_to(
        self,
        other: Any,
    ) -> float:
        other_coordinate = _pi_test_coordinate(
            other
        )

        return _pi_test_distance(
            self.coordinate,
            other_coordinate,
        )

    def copy(
        self,
        **updates: Any,
    ) -> "MockPiAtom":
        return replace(
            self,
            **updates,
        )


