@dataclass(slots=True)
class MockPiResidue:
    """
    Minimal residue model with atom storage and lookup helpers.
    """

    residue_name: str
    residue_number: int
    chain_id: str

    atoms: List[MockPiAtom] = field(
        default_factory=list
    )

    model_id: Optional[str] = "1"
    pose_id: Optional[str] = None

    molecule_type: str = "protein"

    metadata: Dict[str, Any] = field(
        default_factory=dict
    )

    @property
    def name(self) -> str:
        return self.residue_name

    @property
    def number(self) -> int:
        return self.residue_number

    @property
    def chain(self) -> str:
        return self.chain_id

    @property
    def residue_id(self) -> str:
        return (
            f"{self.chain_id}:"
            f"{self.residue_name}:"
            f"{self.residue_number}"
        )

    @property
    def identifier(self) -> str:
        return self.residue_id

    @property
    def atomspec(self) -> str:
        model_prefix = (
            ""
            if self.model_id is None
            else (
                self.model_id
                if str(self.model_id).startswith("#")
                else f"#{self.model_id}"
            )
        )

        return (
            f"{model_prefix}/"
            f"{self.chain_id}:"
            f"{self.residue_number}"
        )

    def add_atom(
        self,
        atom: MockPiAtom,
    ) -> MockPiAtom:
        atom.residue_name = self.residue_name
        atom.residue_number = self.residue_number
        atom.chain_id = self.chain_id
        atom.model_id = self.model_id
        atom.pose_id = self.pose_id

        self.atoms.append(
            atom
        )

        return atom

    def get_atom(
        self,
        name: str,
    ) -> Optional[MockPiAtom]:
        target = str(
            name
        ).strip().upper()

        for atom in self.atoms:
            if atom.name.upper() == target:
                return atom

        return None

    def require_atom(
        self,
        name: str,
    ) -> MockPiAtom:
        atom = self.get_atom(
            name
        )

        if atom is None:
            raise PiSelfTestFixtureError(
                f"Residue {self.residue_id!r} has no atom {name!r}."
            )

        return atom

    def copy(
        self,
        *,
        deep: bool = True,
        **updates: Any,
    ) -> "MockPiResidue":
        copied_atoms = (
            [
                atom.copy(
                    bonds=list(atom.bonds),
                    metadata=dict(atom.metadata),
                )
                for atom in self.atoms
            ]
            if deep
            else list(self.atoms)
        )

        return replace(
            self,
            atoms=copied_atoms,
            metadata=dict(self.metadata),
            **updates,
        )


